  v_hash text;
begin
  for v_course in
    select value from jsonb_array_elements($courses$[{"schemaVersion":1,"id":"f1d89c10-ca34-4223-8c04-de97790a3292","slug":"plotnik","title":"Плотник","description":"Безопасные методы работы плотника: организация рабочего места, ручной и электроинструмент, СИЗ и действия при неисправностях.","icon":"hammer","displayOrder":1,"updatedAt":"2026-08-25T00:00:00.000Z","jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-21","seo":{},"sources":[],"policy":{"durationMinutes":15,"passScore":7,"questionCount":10,"variantCount":3,"attemptsPerCalendarDay":8,"resetTimezone":"Asia/Oral"},"presentation":{"id":"c1f45953-ef66-47cc-b2f8-93047fbfc648","sourceFilename":"presentation.pdf","operatorPptx":"content/source-materials/derived/plotnik/presentation.pptx","file":"presentation.pdf","thumbnail":"thumbnail.webp","storageBucket":"course-presentations","storagePath":"f1d89c10-ca34-4223-8c04-de97790a3292/c1f45953-ef66-47cc-b2f8-93047fbfc648/8a33e78a3f0546b3dd9af99500e1575ac1f6dae21c3a2dedd04e6e49e03c3ea8.pdf","thumbnailPath":"f1d89c10-ca34-4223-8c04-de97790a3292/c1f45953-ef66-47cc-b2f8-93047fbfc648/8a33e78a3f0546b3dd9af99500e1575ac1f6dae21c3a2dedd04e6e49e03c3ea8-thumb.webp","mimeType":"application/pdf","byteSize":1435334,"pageCount":25,"aspectRatio":"16:9","sha256":"8a33e78a3f0546b3dd9af99500e1575ac1f6dae21c3a2dedd04e6e49e03c3ea8","thumbnailSha256":"45c9230c47d6dfa212d7251c8e29cbb0cdd9308731a417560cba1d999b963205","notesIncluded":false},"variants":[{"id":"d3930e8d-40f7-5d9f-98fb-bdb08b119083","variantNumber":1,"questions":[{"id":"d6c4a8d9-1581-540a-b124-a09262885bad","text":"Перед распиловкой доска качается на верстаке. Как следует поступить?","displayOrder":1,"options":[{"id":"afe70682-5b3b-5b17-8f87-ff322b92e682","text":"Удерживать доску коленом и пилить свободной рукой.","displayOrder":1},{"id":"a6ea4733-8f83-54ba-8f8c-a8a529d49ac3","text":"Попросить коллегу держать доску рядом с линией реза.","displayOrder":2},{"id":"f90b68b6-b411-51f9-a468-4c10747519dc","text":"Надёжно закрепить заготовку упорами или зажимами и только затем начать распиловку.","displayOrder":3},{"id":"705e600b-bb35-5e75-8d23-8cf0dc95811e","text":"Начать с коротких быстрых движений, чтобы доска сама заняла устойчивое положение.","displayOrder":4}],"correctOptionId":"f90b68b6-b411-51f9-a468-4c10747519dc","explanation":""},{"id":"eed054b7-721a-5d22-ac3b-153c31b82da1","text":"При ручной распиловке линия реза проходит рядом с поддерживающей рукой. Как изменить работу?","displayOrder":2,"options":[{"id":"55555403-9a84-5874-80d8-9e0b43684ba2","text":"Переставить и закрепить заготовку так, чтобы рука находилась вне линии движения пилы.","displayOrder":1},{"id":"70f15c6c-3a30-5ff0-aa75-a8eeb5b7b235","text":"Увеличить темп распиловки, чтобы быстрее пройти опасный участок.","displayOrder":2},{"id":"43628d7c-f27d-568c-a98b-30d7b9b218db","text":"Развернуть полотно зубьями в противоположную сторону.","displayOrder":3},{"id":"030527f9-df31-5784-b770-6ce81a5e8f84","text":"Продолжить, сильнее прижав заготовку ладонью.","displayOrder":4}],"correctOptionId":"55555403-9a84-5874-80d8-9e0b43684ba2","explanation":""},{"id":"f2b4c912-0614-50a4-bf3c-b1e2b909764d","text":"Плотник строгает доску, направляя рубанок к себе. Как исправить приём?","displayOrder":3,"options":[{"id":"ff437581-3f73-5809-9433-6eb61bc51a1c","text":"Работать одной рукой, а второй придерживать лезвие.","displayOrder":1},{"id":"6dfcc247-af22-5abc-afc3-f63875d8fc04","text":"Продолжить движение к себе, но уменьшить нажим.","displayOrder":2},{"id":"5d78f4ab-8718-56f3-ae79-764a66156a57","text":"Снять упор с верстака, чтобы доска могла смещаться.","displayOrder":3},{"id":"620d6a71-013b-584f-bed4-873494b70f89","text":"Закрепить доску и вести инструмент контролируемо от тела по устойчивой траектории.","displayOrder":4}],"correctOptionId":"620d6a71-013b-584f-bed4-873494b70f89","explanation":""},{"id":"ec122b32-0e93-5af5-9958-709bb78d2d6a","text":"Полотно электролобзика заклинило в заготовке. Какое первое безопасное действие?","displayOrder":4,"options":[{"id":"30f21bbf-9106-50f3-8f4d-050229a15584","text":"Потянуть инструмент на себя при работающем двигателе.","displayOrder":1},{"id":"ae9f9fe2-2f60-5b5d-a267-84d6c8f41fa9","text":"Отпустить выключатель, отключить питание и дождаться полной остановки оснастки.","displayOrder":2},{"id":"e59b9056-c44a-56e1-ad62-12e2fec43ae9","text":"Нажать на заготовку ногой и увеличить скорость.","displayOrder":3},{"id":"30426909-056c-50b6-86bf-5af960a4fbf3","text":"Попытаться освободить полотно отвёрткой без отключения питания.","displayOrder":4}],"correctOptionId":"ae9f9fe2-2f60-5b5d-a267-84d6c8f41fa9","explanation":""},{"id":"e5ec4652-9008-56f2-8bec-708f12c7610d","text":"Как проверить пригодность диска перед установкой на пилу?","displayOrder":5,"options":[{"id":"32edc437-1d5e-553c-bf38-30d21ede0c87","text":"Установить любой диск с подходящим посадочным отверстием.","displayOrder":1},{"id":"3c04b389-ef6c-5711-8d7f-739e8369e1c1","text":"Проверить диск ударом о металлический верстак.","displayOrder":2},{"id":"8a0e1e91-21fd-5665-833f-e1df6e3bf7fc","text":"Сверить тип, размер и допустимую частоту вращения с инструментом и убедиться в отсутствии повреждений.","displayOrder":3},{"id":"e9a3d3a0-cf3a-5854-8710-b4981024a756","text":"Выбрать диск только по цвету упаковки.","displayOrder":4}],"correctOptionId":"8a0e1e91-21fd-5665-833f-e1df6e3bf7fc","explanation":""},{"id":"6840d392-9cec-579f-bf3c-c29d7c274594","text":"При шлифовании образуется много мелкой древесной пыли. Какая мера наиболее эффективна?","displayOrder":6,"options":[{"id":"e8d828e1-f16d-5806-93b2-623ba6af2475","text":"Закрыть вентиляционные отверстия, чтобы пыль не разлеталась.","displayOrder":1},{"id":"402602f8-ebf0-5abd-9a03-d339ada10eee","text":"Использовать только хлопчатобумажные перчатки.","displayOrder":2},{"id":"6229b33f-af34-5b31-abc8-10390cb63cd8","text":"Сместить пыль вентилятором в общий проход.","displayOrder":3},{"id":"8b41e655-555c-5902-a624-ec6a15be3159","text":"Применить удаление пыли у источника, проветривание и подобранные по риску СИЗ.","displayOrder":4}],"correctOptionId":"8b41e655-555c-5902-a624-ec6a15be3159","explanation":""},{"id":"55f72b98-a3b9-5d12-ac79-085d87b81c9b","text":"Когда разрешается менять пильный диск или полотно?","displayOrder":7,"options":[{"id":"995b5ac1-0ba7-5619-8680-29f3e3d1b7d7","text":"После отключения инструмента от источника энергии и полной остановки всех движущихся частей.","displayOrder":1},{"id":"72afca1e-ba27-54cb-807f-82d7b921a26b","text":"На холостом ходу при минимальной частоте вращения.","displayOrder":2},{"id":"d1f960c6-410b-581e-ba62-97b66044ca79","text":"Сразу после отпускания выключателя, пока диск вращается по инерции.","displayOrder":3},{"id":"d526ba2d-9252-54ae-9187-9bd66ec68e7e","text":"При включённом инструменте, если использовать плотные перчатки.","displayOrder":4}],"correctOptionId":"995b5ac1-0ba7-5619-8680-29f3e3d1b7d7","explanation":""},{"id":"bab7074c-e136-5ba1-8b2c-63073ec855a8","text":"Какая последовательность предсменной проверки электроинструмента правильная?","displayOrder":8,"options":[{"id":"9e728bfa-d3ce-5d43-a7d4-b6239cb223c7","text":"Проверить только выключатель, не осматривая оснастку.","displayOrder":1},{"id":"c9743526-1db8-5ca2-9cf0-8472a6fd3788","text":"Снять ограждение, включить инструмент и затем проверить диск рукой.","displayOrder":2},{"id":"2735118e-c220-54f7-a687-308e3f341b03","text":"Осмотреть корпус и кабель, проверить ограждения и оснастку, затем выполнить предусмотренную проверку без нагрузки.","displayOrder":3},{"id":"3c2a36e3-a583-5740-a257-022fef4f6476","text":"Сначала выполнить рабочий рез, затем осмотреть кабель и кожух.","displayOrder":4}],"correctOptionId":"2735118e-c220-54f7-a687-308e3f341b03","explanation":""},{"id":"2324e993-e7cf-5e80-922e-36b09379c4c0","text":"Как завершить работу электроинструментом?","displayOrder":9,"options":[{"id":"ff9efcdd-5612-53e2-b8a0-8fcd9a38f95b","text":"Оставить инструмент подключённым для следующей смены.","displayOrder":1},{"id":"389cfaec-0729-52b2-ad7f-d41aebfcfbb5","text":"Выключить, дождаться полной остановки, отключить питание, очистить и убрать инструмент.","displayOrder":2},{"id":"d50527ea-199e-5735-9f9f-c046b6f2adbf","text":"Положить вращающийся инструмент на верстак и отключить позже.","displayOrder":3},{"id":"4850fe67-795c-5253-a8e1-0dc187d700d3","text":"Остановить оснастку рукой через ветошь.","displayOrder":4}],"correctOptionId":"389cfaec-0729-52b2-ad7f-d41aebfcfbb5","explanation":""},{"id":"9c91c699-13aa-5507-b288-09c1f5d8e94e","text":"Что означает обратный удар при работе пилой?","displayOrder":10,"options":[{"id":"0ea1082d-9f22-5d69-a1bf-3683d5b2eb91","text":"Плановую остановку двигателя после отпускания выключателя.","displayOrder":1},{"id":"bef4cefe-dd30-5b8a-be2e-400de0f63c47","text":"Постепенное затупление режущей кромки.","displayOrder":2},{"id":"ec8bd640-bede-553c-92b7-1066b0ff8df4","text":"Обычное удаление опилок из пропила.","displayOrder":3},{"id":"8799388c-795d-5e28-abd2-64418865647c","text":"Внезапное неконтролируемое движение инструмента или заготовки вследствие заклинивания либо захвата диска.","displayOrder":4}],"correctOptionId":"8799388c-795d-5e28-abd2-64418865647c","explanation":""}]},{"id":"8abfd5d2-320b-51f0-9c7a-1aa87f9bdef0","variantNumber":2,"questions":[{"id":"bf4e9d91-04e0-584f-a631-4612503457a3","text":"В проходе у рабочего места лежат обрезки и кабель электроинструмента. Что сделать до начала работы?","displayOrder":1,"options":[{"id":"41f3e5a3-960d-5c6b-ad53-a1a0f72b8e65","text":"Прикрыть обрезки листом фанеры и начать работу.","displayOrder":1},{"id":"f96b5414-5949-5e47-b1bd-8da003807275","text":"Убрать обрезки, проложить кабель безопасно и обеспечить свободный проход.","displayOrder":2},{"id":"c48a73d4-6416-5c8e-9700-5a4d48f2c3f5","text":"Перенести кабель ближе к линии реза, чтобы он был заметнее.","displayOrder":3},{"id":"6eeabe3e-8ae2-5f96-a44f-543fc603e5cf","text":"Оставить всё на месте, если работа займёт меньше часа.","displayOrder":4}],"correctOptionId":"f96b5414-5949-5e47-b1bd-8da003807275","explanation":""},{"id":"7a130cb7-121b-5651-9b1c-a23cb0bcb1ee","text":"У циркулярной пилы защитный кожух возвращается не полностью. Что должен сделать плотник?","displayOrder":2,"options":[{"id":"89e9c0fa-332b-53dc-ad05-a1c6deba6fe0","text":"Пользоваться пилой только для неглубоких резов.","displayOrder":1},{"id":"9d2e5e18-e61d-58b8-b2aa-38f13a785972","text":"Зафиксировать кожух в открытом положении для удобства.","displayOrder":2},{"id":"fcafaff9-b7f5-5c91-9a0c-4e82b6f7397d","text":"Смазать кожух во время вращения диска и продолжить работу.","displayOrder":3},{"id":"4bdc5a18-1772-5e0c-842f-ac07663b5e0f","text":"Отключить пилу, вывести её из эксплуатации и сообщить о неисправности.","displayOrder":4}],"correctOptionId":"4bdc5a18-1772-5e0c-842f-ac07663b5e0f","explanation":""},{"id":"c28ca391-3c7a-5328-a846-e01309430bde","text":"У стамески расколота рукоятка. Как поступить?","displayOrder":3,"options":[{"id":"096c0a1e-22a8-52ba-bebf-e921164f5b10","text":"Изъять инструмент из работы до замены или исправного ремонта рукоятки.","displayOrder":1},{"id":"f2c2a39b-f653-59b7-9180-3b21bcb53a74","text":"Обмотать раскол изолентой и использовать для лёгких работ.","displayOrder":2},{"id":"f77e465a-f0d5-5e3e-bee7-ccb2d41dd3d5","text":"Держать стамеску за металлическую часть.","displayOrder":3},{"id":"2360b422-85f3-5cee-b809-b5c777c125d2","text":"Работать только мягкой киянкой без замены рукоятки.","displayOrder":4}],"correctOptionId":"096c0a1e-22a8-52ba-bebf-e921164f5b10","explanation":""},{"id":"38fe63cc-a0d7-5b8b-bb04-685d75051407","text":"Работник получил удар электрическим током от инструмента. Что должен сделать очевидец?","displayOrder":4,"options":[{"id":"6e71c69f-0812-5470-9181-acb96ea4bbd7","text":"Полить инструмент водой, чтобы прекратить искрение.","displayOrder":1},{"id":"ed6abfd5-10b0-51a1-b6b0-612a8f3760b3","text":"Сначала убрать инструмент в шкаф, затем сообщить руководителю.","displayOrder":2},{"id":"89304837-9a36-5b0e-9fbc-2ef73f8b170e","text":"Безопасно отключить питание, вызвать помощь и оказывать первую помощь без прямого контакта с токоведущей частью.","displayOrder":3},{"id":"ceee4738-6549-5468-8baa-0e26457ba042","text":"Схватить пострадавшего за руки и оттащить его.","displayOrder":4}],"correctOptionId":"89304837-9a36-5b0e-9fbc-2ef73f8b170e","explanation":""},{"id":"6197587a-8159-5f7a-b57d-060ca8760bef","text":"На кабеле электроинструмента повреждена изоляция. Какое решение соответствует требованиям безопасности?","displayOrder":5,"options":[{"id":"8759c0c7-1d70-5420-a7b2-3af1ece5bab6","text":"Подключить инструмент через более длинный удлинитель без ремонта.","displayOrder":1},{"id":"aacc1e16-86e9-5228-bc12-8db26d0b1a27","text":"Не использовать инструмент до устранения неисправности уполномоченным способом.","displayOrder":2},{"id":"bab54152-90cd-55d8-bc96-6630251efea7","text":"Закрыть повреждение бумагой и работать в сухом помещении.","displayOrder":3},{"id":"c63c37f6-589d-577d-b91b-6e6ccd6b1059","text":"Держать кабель ногой, чтобы место повреждения не двигалось.","displayOrder":4}],"correctOptionId":"aacc1e16-86e9-5228-bc12-8db26d0b1a27","explanation":""},{"id":"d28794af-3bbb-5ded-b718-3b38291f849d","text":"Почему свободные перчатки опасны возле вращающейся оснастки?","displayOrder":6,"options":[{"id":"4c7fdf42-817b-5878-86f3-d9e83fa9cbd7","text":"Перчатки обязательно повышают температуру двигателя.","displayOrder":1},{"id":"f1fb97b2-fd40-5fd3-bbbe-caa1c1b9a87b","text":"Перчатки меняют направление вращения инструмента.","displayOrder":2},{"id":"e1d48829-ca52-5c26-a45b-1b245defb419","text":"Перчатки мешают работе только при низкой температуре.","displayOrder":3},{"id":"a14d8ba5-f4b2-5787-91dd-a76d46325ee5","text":"Материал перчатки может быть захвачен вращающейся частью и затянуть руку.","displayOrder":4}],"correctOptionId":"a14d8ba5-f4b2-5787-91dd-a76d46325ee5","explanation":""},{"id":"535250e4-ff60-5c6c-b1de-fb7d6e7f63a5","text":"Как правильно хранить ручной режущий инструмент после очистки?","displayOrder":7,"options":[{"id":"4f24f6a9-be50-579c-a567-a31ee7d59f52","text":"В общей куче с крепежом и обрезками.","displayOrder":1},{"id":"0011c056-c08f-556b-bef2-b99aee9cda12","text":"Во влажной ветоши, чтобы металл не нагревался.","displayOrder":2},{"id":"7c3c2b29-563a-52b0-be93-39aedeaa4246","text":"В сухом отведённом месте, с защищённой режущей частью и без риска падения.","displayOrder":3},{"id":"c6735c4d-818c-5316-8a6f-52c4ffddb0a9","text":"На краю верстака режущей частью наружу.","displayOrder":4}],"correctOptionId":"7c3c2b29-563a-52b0-be93-39aedeaa4246","explanation":""},{"id":"a27ef516-349c-5595-81ce-60becd4cb45c","text":"Какой порядок проверки ручного инструмента наиболее рационален?","displayOrder":8,"options":[{"id":"8f1797ab-c7f8-5916-a1a2-e871e0dd662e","text":"Проверить назначение, целостность рукоятки, состояние рабочей части и надёжность её крепления.","displayOrder":1},{"id":"32d03942-b080-50be-a1aa-38ac98600288","text":"Заточить любой инструмент независимо от его назначения.","displayOrder":2},{"id":"bd9576d3-ffec-5335-8415-70401a795169","text":"Сначала испытать инструмент максимальным ударом по металлу.","displayOrder":3},{"id":"7364813d-0323-55d7-8d72-f4e8736a6880","text":"Проверить только чистоту рукоятки.","displayOrder":4}],"correctOptionId":"8f1797ab-c7f8-5916-a1a2-e871e0dd662e","explanation":""},{"id":"b2096a33-d277-58bf-a4c4-783c1f793a77","text":"Инструмент начал сильно вибрировать и появился запах перегрева. Какова правильная последовательность?","displayOrder":9,"options":[{"id":"67d15d9c-5ace-5fa3-96d8-7dd786fc598a","text":"Увеличить нагрузку, чтобы вибрация уменьшилась.","displayOrder":1},{"id":"020e68b1-268b-5154-9e89-f5a7c4e8eb53","text":"Охладить инструмент водой без отключения.","displayOrder":2},{"id":"998ada4c-6831-56e0-9c28-49f82365aeeb","text":"Продолжать до полного отказа, затем заменить оснастку.","displayOrder":3},{"id":"ec62b09f-c1a1-5b3f-a4fc-a8b752452adf","text":"Немедленно остановить, отключить, обозначить неисправность и передать на проверку.","displayOrder":4}],"correctOptionId":"ec62b09f-c1a1-5b3f-a4fc-a8b752452adf","explanation":""},{"id":"55548083-4a49-5b46-a1bb-df857482f431","text":"Каково назначение защитного ограждения инструмента?","displayOrder":10,"options":[{"id":"fa91def9-a442-5171-97d5-cd6de4abe981","text":"Заменять обучение и другие меры защиты.","displayOrder":1},{"id":"26cc1286-64cf-5c42-b542-1fff1a56848e","text":"Ограничивать доступ к опасной движущейся части и сдерживать выброс частиц в предусмотренных пределах.","displayOrder":2},{"id":"27389fc5-4478-55bf-90d7-64a97c934021","text":"Удерживать заготовку вместо зажимного устройства.","displayOrder":3},{"id":"01730d90-71f8-594f-aece-40ffdb822be1","text":"Увеличивать скорость вращения оснастки.","displayOrder":4}],"correctOptionId":"26cc1286-64cf-5c42-b542-1fff1a56848e","explanation":""}]},{"id":"91f10066-0447-5e23-87da-032ae5ca37b1","variantNumber":3,"questions":[{"id":"a4676234-b37a-53b4-99a5-567be5236cbf","text":"При осмотре деревянной заготовки обнаружен выступающий гвоздь. Какое действие правильное?","displayOrder":1,"options":[{"id":"1e15e599-f256-5345-bb71-314ac1eff289","text":"Не начинать обработку, пока металлическое включение не удалено или заготовка не заменена.","displayOrder":1},{"id":"1ca0f285-f5ca-550f-bc18-8eca2ae667d7","text":"Надеть более плотные перчатки и обработать заготовку обычным способом.","displayOrder":2},{"id":"039787b3-c0ec-56c3-9399-e164d6c8cd1d","text":"Обработать участок на минимальной скорости, не меняя оснастку.","displayOrder":3},{"id":"d6e1698e-290a-56e1-a1bb-0ba5b193704e","text":"Отметить гвоздь мелом и продолжить пиление рядом с ним.","displayOrder":4}],"correctOptionId":"1e15e599-f256-5345-bb71-314ac1eff289","explanation":""},{"id":"d5b8618e-480c-543f-95a0-13abd8e6b23e","text":"Небольшую деталь неудобно удерживать при обработке электроинструментом. Какой способ безопаснее?","displayOrder":2,"options":[{"id":"e4945645-2413-51e2-abf7-0f6fac26c101","text":"Удерживать деталь пальцами как можно ближе к месту обработки.","displayOrder":1},{"id":"a770aa55-7d37-58fb-b6f2-2b57409ae3ce","text":"Прижать деталь обувью к полу.","displayOrder":2},{"id":"4c3dda87-094b-5ad3-b703-bc8883b1a129","text":"Закрепить деталь подходящим приспособлением и держать руки вне опасной зоны.","displayOrder":3},{"id":"5f815f2c-c512-5855-af9c-519a253df24a","text":"Попросить коллегу держать деталь рукой со стороны выхода оснастки.","displayOrder":4}],"correctOptionId":"4c3dda87-094b-5ad3-b703-bc8883b1a129","explanation":""},{"id":"34eea8cc-16aa-54d5-90d2-a0360c233f33","text":"После строгания на верстаке осталась стружка возле режущего инструмента. Как её убрать?","displayOrder":3,"options":[{"id":"71332ca9-b123-5eea-8724-7124491411ca","text":"Сдуть стружку на коллегу сжатым воздухом.","displayOrder":1},{"id":"7f9d0faf-a32c-5ef8-b0d8-39f7a670ff9d","text":"После остановки и безопасного размещения инструмента удалить стружку щёткой или другим приспособлением.","displayOrder":2},{"id":"27f71c0c-57d2-52d3-bb3b-d04228dffe2f","text":"Убирать стружку только после окончания смены, не останавливая работу.","displayOrder":3},{"id":"4f79c45a-ff94-5a08-b64c-afe073d66273","text":"Смахнуть стружку ладонью в сторону прохода.","displayOrder":4}],"correctOptionId":"7f9d0faf-a32c-5ef8-b0d8-39f7a670ff9d","explanation":""},{"id":"58b9e341-d705-526f-960a-0c7af961235a","text":"В зоне обработки древесины появился дым и запах горения. Как действовать?","displayOrder":4,"options":[{"id":"2b88c665-5d74-52ba-8c14-d47adb5416bb","text":"Открыть все ёмкости с горючими материалами для проверки.","displayOrder":1},{"id":"cce1a900-6db1-5cc6-8cc0-d038cda8980c","text":"Закрыть помещение и продолжить работу в соседней зоне.","displayOrder":2},{"id":"08dbd77b-7161-5178-8bff-c97683c4b5cd","text":"Ждать видимого пламени, не сообщая о признаках пожара.","displayOrder":3},{"id":"03b8e1bf-83ad-52b7-86c6-4418f263c616","text":"Остановить работу, отключить энергию при безопасной возможности, подать тревогу, сообщить 101/112 и эвакуироваться по обстановке.","displayOrder":4}],"correctOptionId":"03b8e1bf-83ad-52b7-86c6-4418f263c616","explanation":""},{"id":"29f5db9d-1996-5974-a7e7-2e6fce8c01a2","text":"Работнику мешает штатное ограждение режущей части. Что допустимо?","displayOrder":5,"options":[{"id":"a867e1d2-e839-5932-b829-c802f6fa5d4c","text":"Снять ограждение на один рез и установить его после работы.","displayOrder":1},{"id":"3b2b4f3c-9902-5367-9a9a-aabb87dbf1ed","text":"Закрепить ограждение проволокой в открытом положении.","displayOrder":2},{"id":"86292da2-cb4e-5405-8657-4ad08f33d5c2","text":"Сохранить исправное ограждение и подобрать безопасный способ выполнения операции по инструкции изготовителя.","displayOrder":3},{"id":"403bdee0-cdb2-5ede-b86b-7b25adce5d7a","text":"Попросить коллегу удерживать ограждение рукой.","displayOrder":4}],"correctOptionId":"86292da2-cb4e-5405-8657-4ad08f33d5c2","explanation":""},{"id":"d946b86f-f721-52ff-8e48-a84845b3b7c5","text":"Одновременно присутствуют высокий шум и летящая стружка. Как выбрать защиту?","displayOrder":6,"options":[{"id":"4c20c937-858f-5e4b-9afd-94f76c3fb94c","text":"Использовать исправную защиту глаз и слуха, соответствующую оценке риска и выполняемой операции.","displayOrder":1},{"id":"7c8d285d-586b-5571-a285-919564e45038","text":"Закрыть глаза при прохождении стружки и не использовать СИЗ.","displayOrder":2},{"id":"d74f9bca-b0d7-5039-9f62-c61b7c1dc66c","text":"Надеть обычные очки и отключить штатное ограждение.","displayOrder":3},{"id":"c8682863-fdee-5de2-b9a2-d4d65152df7c","text":"Выбрать только защиту слуха, поскольку шум опаснее стружки.","displayOrder":4}],"correctOptionId":"4c20c937-858f-5e4b-9afd-94f76c3fb94c","explanation":""},{"id":"890c6cc1-4db1-5623-995e-cec8dab489a3","text":"Как безопасно удалять пыль с инструмента после работы?","displayOrder":7,"options":[{"id":"bf405947-aeb9-56e1-923a-6f80f3d5f3c7","text":"Очищать вентиляционные отверстия металлической проволокой при включённом питании.","displayOrder":1},{"id":"e3c6ae2b-5ce4-5328-b5c6-02acc6351a73","text":"Обдувать работающий инструмент сжатым воздухом в сторону коллег.","displayOrder":2},{"id":"18afcd14-4532-586b-ba3e-0f5c6e670b7f","text":"Погружать электрический инструмент в воду.","displayOrder":3},{"id":"4c964e58-4e4e-51cd-b560-0bcc912f8744","text":"Отключить инструмент и очистить его способом, предусмотренным инструкцией, не направляя загрязнение на людей.","displayOrder":4}],"correctOptionId":"4c964e58-4e4e-51cd-b560-0bcc912f8744","explanation":""},{"id":"d95244c7-64ed-594a-afce-7695c2fa8cfd","text":"Что следует проверить перед началом обработки заготовки?","displayOrder":8,"options":[{"id":"a56b6911-7bb2-5f99-bd2a-c925164dfe6c","text":"Только наличие свободной розетки.","displayOrder":1},{"id":"abeaa3ac-016c-5daa-8383-8230454b480b","text":"Рабочее место, материал и его крепление, исправность инструмента и требуемые меры защиты.","displayOrder":2},{"id":"56c58aab-3d60-5b9a-adc2-aa0a805be97f","text":"Только внешний вид готового изделия.","displayOrder":3},{"id":"07863388-bc02-54b3-b727-79c636d00809","text":"Только скорость выполнения предыдущей операции.","displayOrder":4}],"correctOptionId":"abeaa3ac-016c-5daa-8383-8230454b480b","explanation":""},{"id":"28d7415c-20bd-5f43-bada-3785e1c1f1e9","text":"Как безопасно заменить оснастку?","displayOrder":9,"options":[{"id":"1836c106-3353-528a-92f1-c9dec9d8161a","text":"Отключить энергию, проверить совместимость и состояние оснастки, установить её по инструкции и восстановить ограждения.","displayOrder":1},{"id":"b59600a0-0b49-52bd-8bc2-bfb866501760","text":"Использовать любую оснастку одинакового цвета.","displayOrder":2},{"id":"c140e6cd-6151-593a-af2b-739b45a7e1d7","text":"После установки сразу работать на полной нагрузке без проверки.","displayOrder":3},{"id":"625a7d46-5f8e-550e-8477-3f17b1fa5dba","text":"Снять ограждение при включённом двигателе и быстро заменить оснастку.","displayOrder":4}],"correctOptionId":"1836c106-3353-528a-92f1-c9dec9d8161a","explanation":""},{"id":"f245a326-8260-5616-bbc2-865f09ff4436","text":"Что такое местное удаление пыли?","displayOrder":10,"options":[{"id":"712dc75c-ab11-5a85-a719-4045a68b32a3","text":"Закрытие всех приточных отверстий во время работы.","displayOrder":1},{"id":"4e2bae48-fd58-58c6-afc5-4f5ad8961c4a","text":"Уборка пола в конце смены сухой метлой.","displayOrder":2},{"id":"6b61fdc7-ec45-5a9e-a3e0-1aecb03bc8fb","text":"Захват загрязнения непосредственно у места его образования до распространения по рабочей зоне.","displayOrder":3},{"id":"aaca6744-f139-5839-85c1-09fc427175b0","text":"Перемещение пыли вентилятором в соседнее помещение.","displayOrder":4}],"correctOptionId":"6b61fdc7-ec45-5a9e-a3e0-1aecb03bc8fb","explanation":""}]}],"sourceMaterials":{"presentation":{"filename":"01_Плотник.pptx","sha256":"d3b84cbe64a5376c61168ee798b5130c4e593ba39c302f785a13293125766948"},"tests":{"filename":"06_Тестовые_задания.docx","sha256":"3b36bba9f031c233cd10a4a80e1f7dd2a89af523b5df2145056dc7366086ce00"}},"dbContentHash":"deca2868066fc4bac15a20cac2cda38ae877451c34fff975e124be538cf6908e","snapshotContentHash":"708cef990b7fb3b59c0c64673debed451dccd2d48103eddcd2f400a8a0b7b535","contentHash":"deca2868066fc4bac15a20cac2cda38ae877451c34fff975e124be538cf6908e"},{"schemaVersion":1,"id":"edfaf13a-6111-4940-bc06-28d655c3001d","slug":"armaturshchik","title":"Арматурщик","description":"Безопасная подготовка, обработка, перемещение и монтаж арматуры с контролем инструмента, каркаса и рабочей зоны.","icon":"hard-hat","displayOrder":2,"updatedAt":"2026-08-25T00:00:00.000Z","jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-21","seo":{},"sources":[],"policy":{"durationMinutes":15,"passScore":7,"questionCount":10,"variantCount":3,"attemptsPerCalendarDay":8,"resetTimezone":"Asia/Oral"},"presentation":{"id":"8e741453-9053-40d5-9a17-05e1136fd7b2","sourceFilename":"presentation.pdf","operatorPptx":"content/source-materials/derived/armaturshchik/presentation.pptx","file":"presentation.pdf","thumbnail":"thumbnail.webp","storageBucket":"course-presentations","storagePath":"edfaf13a-6111-4940-bc06-28d655c3001d/8e741453-9053-40d5-9a17-05e1136fd7b2/b76f7b404953629d78972bb197a8fb01c004741270f487ae492f2f5749684c32.pdf","thumbnailPath":"edfaf13a-6111-4940-bc06-28d655c3001d/8e741453-9053-40d5-9a17-05e1136fd7b2/b76f7b404953629d78972bb197a8fb01c004741270f487ae492f2f5749684c32-thumb.webp","mimeType":"application/pdf","byteSize":2180188,"pageCount":31,"aspectRatio":"16:9","sha256":"b76f7b404953629d78972bb197a8fb01c004741270f487ae492f2f5749684c32","thumbnailSha256":"1e052a500d5722758671072877e0caea9ff6de665c60762f56f2e6eb86814a9c","notesIncluded":false},"variants":[{"id":"2b72195c-a2cf-5a40-8ab1-2e3be956e8d6","variantNumber":1,"questions":[{"id":"d155e90a-824c-539b-b66e-3015c433bc12","text":"Размер каркаса на чертеже не совпадает с подготовленной заготовкой. Что делать?","displayOrder":1,"options":[{"id":"d03ed4ca-bc50-5546-8836-d897c1b5f566","text":"Подогнуть заготовку на месте без согласования.","displayOrder":1},{"id":"c0bba186-cd46-50c0-94d2-270e3cd482ec","text":"Изменить шаг стержней на глаз.","displayOrder":2},{"id":"a0cb8a27-737c-56ed-a715-4cd2b10f4ff0","text":"Собрать каркас и скрыть отклонение при бетонировании.","displayOrder":3},{"id":"edc66359-b1b7-5098-bf42-87fdee9b61c4","text":"Остановить сборку и уточнить несоответствие у ответственного лица по проектной документации.","displayOrder":4}],"correctOptionId":"edc66359-b1b7-5098-bf42-87fdee9b61c4","explanation":""},{"id":"9155603a-7588-5157-85e1-a26cde8334be","text":"Пачка арматуры лежит без упоров на уклонной площадке. Что сделать?","displayOrder":2,"options":[{"id":"dade6a0b-a286-5626-8f6c-3adfda4995b7","text":"Оставить пачку до начала перемещения краном.","displayOrder":1},{"id":"b3543270-8e55-5e57-9093-5341cdbc06ce","text":"Остановить работы и обеспечить устойчивое складирование на подготовленных подкладках с упорами.","displayOrder":2},{"id":"641fa84e-6b9f-59b5-98ff-8876d1409bf4","text":"Разрезать обвязку, находясь ниже по уклону.","displayOrder":3},{"id":"1d31f77a-a26b-5779-88b9-d4799d65de24","text":"Подложить один случайный обрезок под середину пачки.","displayOrder":4}],"correctOptionId":"b3543270-8e55-5e57-9093-5341cdbc06ce","explanation":""},{"id":"8543a437-bc11-5547-83a6-19c2332ed3d5","text":"Работник держит короткий стержень рукой у зоны резания станка. Как организовать операцию?","displayOrder":3,"options":[{"id":"b97a5874-e939-5bd7-90d2-50d3d6f989ee","text":"Удерживать стержень вдвоём по обе стороны ножа.","displayOrder":1},{"id":"833c19d0-30d3-5556-90d2-1329660df0a8","text":"Надеть более толстые перчатки и продолжить удержание рукой.","displayOrder":2},{"id":"8182faf7-36db-59ec-83d5-04f57e72fc1e","text":"Использовать предусмотренное приспособление для подачи и удержания, сохранив руки вне опасной зоны.","displayOrder":3},{"id":"bac945e6-12e5-5060-b063-a978c7fc767b","text":"Увеличить скорость резания, чтобы быстрее закончить.","displayOrder":4}],"correctOptionId":"8182faf7-36db-59ec-83d5-04f57e72fc1e","explanation":""},{"id":"40a38c06-2fda-515f-93ec-876fbc091705","text":"Из каркаса в проход выступают незащищённые концы стержней. Какая мера нужна?","displayOrder":4,"options":[{"id":"f8eb5d4f-42de-544d-a170-8cb4bf628ffc","text":"Оградить опасную зону и установить предусмотренную защиту выступающих концов либо изменить организацию прохода.","displayOrder":1},{"id":"947599ff-ea4b-5912-a2c9-d9705dba1a67","text":"Покрасить концы яркой краской и оставить проход открытым.","displayOrder":2},{"id":"528bef61-80e3-5e66-a3ed-d2922d033f83","text":"Накрыть концы тонкой бумагой.","displayOrder":3},{"id":"cb265e29-4a20-5930-b1ad-7729d78127c0","text":"Предупредить работников устно без физической защиты.","displayOrder":4}],"correctOptionId":"f8eb5d4f-42de-544d-a170-8cb4bf628ffc","explanation":""},{"id":"44684521-968f-5136-81e5-904715a5fe1e","text":"Когда допускается сварное соединение арматуры?","displayOrder":5,"options":[{"id":"60d273c9-d7a4-5a48-914a-89871023e6ad","text":"Когда стержни имеют одинаковый цвет.","displayOrder":1},{"id":"bbbceaa4-4515-54d5-bc7a-8350aee488f3","text":"Когда на площадке есть любой сварочный аппарат.","displayOrder":2},{"id":"4a4aa856-bfd9-526c-b2d8-35d1b7e6a1bb","text":"Когда вязка занимает больше времени.","displayOrder":3},{"id":"cb49e3b7-54ce-510a-b7fd-40971ffbc6cb","text":"Когда оно предусмотрено проектом и технологией, а работу выполняет допущенный квалифицированный работник.","displayOrder":4}],"correctOptionId":"cb49e3b7-54ce-510a-b7fd-40971ffbc6cb","explanation":""},{"id":"20932fb4-7f0f-5de3-94da-8547aabc12f6","text":"Перед бетонированием обнаружено смещение каркаса. Что требуется?","displayOrder":6,"options":[{"id":"d80e8304-17bd-5513-8b4e-8164635b134d","text":"Компенсировать смещение увеличением количества бетона.","displayOrder":1},{"id":"60395797-06be-559b-a5b1-02e516b671a5","text":"Оставить смещение, если арматура не касается опалубки.","displayOrder":2},{"id":"a9116b69-cc5b-5a29-9092-569c3af5c8ad","text":"Остановить подготовку к бетонированию, восстановить проектное положение и выполнить контроль.","displayOrder":3},{"id":"831a19cd-fd37-55de-95fc-de7233e523c3","text":"Срезать мешающие стержни без согласования.","displayOrder":4}],"correctOptionId":"a9116b69-cc5b-5a29-9092-569c3af5c8ad","explanation":""},{"id":"a55e5e2c-b460-5c16-91f7-426484f33b47","text":"Арматурщик работает у края перекрытия. Какая защита имеет приоритет?","displayOrder":7,"options":[{"id":"e50d1a14-c0b6-572d-aeaf-be42dda39a4e","text":"Только предупреждающая надпись на полу.","displayOrder":1},{"id":"e7c4939f-2728-5b9f-b2e8-419283a449bf","text":"Исправное коллективное ограждение; при необходимости — дополняющая страховочная система по плану работ.","displayOrder":2},{"id":"103f7d0c-9117-570e-b052-f0b1b0378b5c","text":"Один страховочный пояс без проверки точки крепления.","displayOrder":3},{"id":"3200cb35-65bf-5a92-a8e7-35c7a4dfa4b1","text":"Присутствие коллеги рядом без ограждения.","displayOrder":4}],"correctOptionId":"e7c4939f-2728-5b9f-b2e8-419283a449bf","explanation":""},{"id":"150e1860-038e-5f8f-80b3-4fba5384a5a0","text":"Какова правильная предсменная проверка станка для резки арматуры?","displayOrder":8,"options":[{"id":"51622035-7fa8-5932-bd24-9a12403389cf","text":"Начать с максимальной нагрузки без осмотра.","displayOrder":1},{"id":"4f55e7b6-3f1f-5e4c-8cf5-c5b212d0eed0","text":"Проверить только наличие электропитания.","displayOrder":2},{"id":"f20790d2-748e-5853-8a0a-f62b1274cd62","text":"Сначала снять ограждение и проверить нож рукой.","displayOrder":3},{"id":"a5d6c512-25fb-5448-9e85-a2c79e3b688b","text":"Осмотреть ограждения, органы управления, рабочую оснастку и зону работы, затем выполнить предусмотренную пробную проверку.","displayOrder":4}],"correctOptionId":"a5d6c512-25fb-5448-9e85-a2c79e3b688b","explanation":""},{"id":"3b769351-ca84-58bd-96bf-84fa59fb2402","text":"Каркас начал смещаться во время установки. Как действовать?","displayOrder":9,"options":[{"id":"2d392b20-757f-52fa-ac82-77828042cb65","text":"Остановить перемещение, исключить доступ в опасную зону, стабилизировать каркас и только затем продолжить по команде.","displayOrder":1},{"id":"387e91d7-88c5-5e25-b75b-0ff1fbdb3fff","text":"Зайти под каркас и поправить опоры.","displayOrder":2},{"id":"8741c24d-20be-5ac8-b1a6-b0666f8cc899","text":"Удерживать каркас телом до завершения подъёма.","displayOrder":3},{"id":"3c846be4-e4c2-5eb4-a269-4e779aff5cee","text":"Ускорить перемещение, чтобы каркас быстрее встал на место.","displayOrder":4}],"correctOptionId":"2d392b20-757f-52fa-ac82-77828042cb65","explanation":""},{"id":"2c2504b5-5055-5925-b559-a7c19939a605","text":"Что называют защитным слоем бетона?","displayOrder":10,"options":[{"id":"03338867-3ff8-5770-9167-73671acdc033","text":"Слой смазки на поверхности стержня.","displayOrder":1},{"id":"13820dce-fac0-5f04-955a-760e13e67412","text":"Временную плёнку поверх опалубки.","displayOrder":2},{"id":"c9a362c6-e7bb-5632-877e-a5ce35e8fd91","text":"Проектное расстояние от поверхности бетона до арматуры, обеспечиваемое её правильным положением.","displayOrder":3},{"id":"35473d46-edc8-54ad-aee2-23941460e360","text":"Дополнительный ряд вязальной проволоки.","displayOrder":4}],"correctOptionId":"c9a362c6-e7bb-5632-877e-a5ce35e8fd91","explanation":""}]},{"id":"753ce2bd-1961-56fe-b33a-85c044512257","variantNumber":2,"questions":[{"id":"272e7cec-f274-50f6-9753-32fc63416e9b","text":"Для узла отсутствует рабочая схема армирования. Как поступить арматурщику?","displayOrder":1,"options":[{"id":"b8b4070e-aa31-5bb4-b1c4-5ee00a8edfa1","text":"Не выполнять узел до получения утверждённой проектной информации и задания.","displayOrder":1},{"id":"87b70dd4-1a62-58ae-8d8a-363428a10311","text":"Выбрать диаметр и шаг по остатку материала.","displayOrder":2},{"id":"d577374a-7f8f-5be4-b15a-d45f0cb85cb4","text":"Заменить недостающую арматуру вязальной проволокой.","displayOrder":3},{"id":"25a371a6-15df-5240-b444-f77c9c59ed9d","text":"Повторить схему соседнего узла независимо от нагрузки.","displayOrder":4}],"correctOptionId":"b8b4070e-aa31-5bb4-b1c4-5ee00a8edfa1","explanation":""},{"id":"f7b020f8-edd0-56ce-9934-ff0ca32b6f98","text":"Во время перемещения каркаса краном работник оказался под грузом. Как должен действовать сигнальщик или руководитель?","displayOrder":2,"options":[{"id":"8c321b04-3ab5-5cc0-9e3c-4fa78ef1fa47","text":"Попросить работника придержать каркас руками.","displayOrder":1},{"id":"1bd703aa-6ccb-555b-9b2e-b44571a4f4da","text":"Немедленно остановить перемещение и вывести человека из опасной зоны.","displayOrder":2},{"id":"e0f10d78-9a20-5738-a7dc-0b9844ed51e4","text":"Продолжить подъём на меньшей скорости.","displayOrder":3},{"id":"8d3bc139-35e6-5ce9-8b9f-ca348685ac14","text":"Подать груз выше, не останавливая операцию.","displayOrder":4}],"correctOptionId":"1bd703aa-6ccb-555b-9b2e-b44571a4f4da","explanation":""},{"id":"b2f39577-6b65-5dfc-a0ae-4c14f6059719","text":"При гибке арматуры коллега находится в секторе возможного движения стержня. Как поступить?","displayOrder":3,"options":[{"id":"c21ba407-3fe3-58da-9a1f-310c5db511db","text":"Предупредить коллегу криком и начать гибку.","displayOrder":1},{"id":"6a9f806e-acb3-5415-b206-b07bbb4d7e04","text":"Уменьшить угол гиба, не меняя положение коллеги.","displayOrder":2},{"id":"5ed159a4-732b-5b63-9506-6e0a567f4431","text":"Придерживать свободный конец стержня ногой.","displayOrder":3},{"id":"53469778-4da0-5cd4-b0e7-a11fd14ceb1f","text":"Остановить операцию и освободить опасную зону до включения оборудования.","displayOrder":4}],"correctOptionId":"53469778-4da0-5cd4-b0e7-a11fd14ceb1f","explanation":""},{"id":"27b9178b-493f-5a3b-8fda-6399cc565059","text":"При вязке проволока порвалась и острый конец направлен к лицу. Как снизить риск?","displayOrder":4,"options":[{"id":"3657b2c4-8df2-5b3d-89bd-47376edff0ca","text":"Удлинить конец проволоки и оставить его наружу.","displayOrder":1},{"id":"6b4265e4-076c-59a7-953c-d50e4c24eef8","text":"Скручивать проволоку только руками без инструмента.","displayOrder":2},{"id":"dc186eef-3f31-5b9a-97aa-6ef776da0cad","text":"Использовать исправный инструмент, контролировать направление концов проволоки и применять защиту глаз и рук по риску.","displayOrder":3},{"id":"be9a9387-c74b-58a5-8e4f-0c8a8f2eb31b","text":"Наклониться ближе, чтобы лучше видеть место вязки.","displayOrder":4}],"correctOptionId":"dc186eef-3f31-5b9a-97aa-6ef776da0cad","explanation":""},{"id":"b087ce96-3116-5b36-bd0c-8a99576d1e1a","text":"Можно ли заменить проектную муфту сваркой без согласования?","displayOrder":5,"options":[{"id":"12b1f311-1bd2-5fff-908b-780a18e1e3a8","text":"Можно, если диаметр стержня меньше соседнего.","displayOrder":1},{"id":"55a8e4b1-d2c5-59d1-9308-cadf4e45042d","text":"Нельзя: способ соединения меняют только в установленном порядке по проектному решению.","displayOrder":2},{"id":"1167b08f-28a5-578a-9b49-b1e3f21eb9c9","text":"Можно, если сварщик считает шов прочным.","displayOrder":3},{"id":"bc779bfe-4c00-5eff-8a28-ce1569e89909","text":"Можно для одного стыка без записи.","displayOrder":4}],"correctOptionId":"55a8e4b1-d2c5-59d1-9308-cadf4e45042d","explanation":""},{"id":"32649218-e755-5c27-882b-d100344a29af","text":"Как устанавливают защитный слой бетона для арматуры?","displayOrder":6,"options":[{"id":"56bef418-7531-5e90-8788-44a06c16210e","text":"По проектной документации с применением предусмотренных фиксаторов и контролем положения.","displayOrder":1},{"id":"a6cb76ab-a511-5752-b89d-433e1bb44b6b","text":"По одному универсальному размеру для всех конструкций.","displayOrder":2},{"id":"bcbbe36d-cbc3-5886-a2a6-f2d249e83f8f","text":"По расстоянию, которое удобно выдержать вручную.","displayOrder":3},{"id":"5dffe213-e0ab-555f-b778-79aba1be9155","text":"За счёт свободного перемещения каркаса при бетонировании.","displayOrder":4}],"correctOptionId":"56bef418-7531-5e90-8788-44a06c16210e","explanation":""},{"id":"814f0e02-2557-5ed6-b8b5-a95c4ca982be","text":"Каркас подаётся краном в монтажную зону. Как организовать взаимодействие?","displayOrder":7,"options":[{"id":"a31530e7-ab9b-51ed-8e4b-aebf7bb5cc50","text":"Направлять груз руками, находясь под ним.","displayOrder":1},{"id":"45b77eb6-8cc7-563e-9eb1-820342bbd903","text":"Продолжать движение при потере видимости машинистом.","displayOrder":2},{"id":"bfdf05b0-5222-5b08-91e8-d0d8f9dd9460","text":"Разрешить любому работнику подавать разные команды.","displayOrder":3},{"id":"2474303c-d5ce-574c-a540-a877ed3d0ac2","text":"Назначить установленного сигнальщика, использовать согласованные команды и не допускать людей под груз.","displayOrder":4}],"correctOptionId":"2474303c-d5ce-574c-a540-a877ed3d0ac2","explanation":""},{"id":"fb447427-81e0-5b82-bd63-45b9ac707a97","text":"Что проверить у ручного инструмента для вязки?","displayOrder":8,"options":[{"id":"a7154d84-3ee1-52f6-8b1d-0286190631be","text":"Только дату последней уборки рабочего места.","displayOrder":1},{"id":"e61c5c9b-dc09-5ea2-8a07-a3a1f9e12801","text":"Целостность рукояток, рабочей части, креплений и отсутствие опасных заусенцев.","displayOrder":2},{"id":"313e419c-6369-5dfd-963e-8a400c1a54ac","text":"Только цвет рукоятки.","displayOrder":3},{"id":"901cf25c-b040-586a-9a9a-9c1363c065cb","text":"Только массу инструмента.","displayOrder":4}],"correctOptionId":"e61c5c9b-dc09-5ea2-8a07-a3a1f9e12801","explanation":""},{"id":"e9929882-9e71-534d-bd81-e67daec3f6a3","text":"Во время резки обнаружено разрушение защитного ограждения станка. Каков порядок действий?","displayOrder":9,"options":[{"id":"75773664-d866-5745-84f7-03662c18f591","text":"Закрыть место картоном и продолжить резку.","displayOrder":1},{"id":"bc23d580-07ec-50af-9dbb-afaec7e83e7a","text":"Работать только на малых диаметрах.","displayOrder":2},{"id":"532b8549-9cff-5934-ad96-4df7aa23d0b7","text":"Остановить станок, отключить энергию, обозначить неисправность и передать оборудование на ремонт.","displayOrder":3},{"id":"6bdb1dcb-6ac0-5a62-8cb3-a5d3fc3329eb","text":"Попросить коллегу держать временный щит.","displayOrder":4}],"correctOptionId":"532b8549-9cff-5934-ad96-4df7aa23d0b7","explanation":""},{"id":"02d66848-659e-556d-9ccb-3f04c88db30d","text":"Что такое механическое соединение арматуры?","displayOrder":10,"options":[{"id":"c950d66d-6ab5-51ce-a911-580f08d8b98f","text":"Случайное перекрытие двух стержней без фиксации.","displayOrder":1},{"id":"ff8aa177-6284-525e-b235-8077b7cf708d","text":"Сварка любых стержней без проектного решения.","displayOrder":2},{"id":"eac465ad-c015-564f-b4cf-0ccdb91dea06","text":"Любая ручная вязка проволокой.","displayOrder":3},{"id":"7b0bdc99-99bd-53e9-8ff1-9b83854486f0","text":"Соединение стержней специальным устройством, выполняемое по проекту и технологии конкретной системы.","displayOrder":4}],"correctOptionId":"7b0bdc99-99bd-53e9-8ff1-9b83854486f0","explanation":""}]},{"id":"9c9513cc-6c34-586b-bf3d-81feab93b8c2","variantNumber":3,"questions":[{"id":"5694d58e-0306-5e67-99c5-dfa2235d1b50","text":"На площадке предлагают изменить тип соединения стержней ради ускорения работы. Какое решение правильное?","displayOrder":1,"options":[{"id":"239fc8c8-f872-590c-b6ee-bc3df3cf53e0","text":"Смешать разные способы в одном узле без согласования.","displayOrder":1},{"id":"dd9d148d-c61f-5bbc-852e-98965f92c2e0","text":"Заменять соединения по усмотрению исполнителя.","displayOrder":2},{"id":"8dd527d3-1e64-5e15-bb79-936077ce7b40","text":"Применять только соединение, предусмотренное проектом и утверждённой технологией.","displayOrder":3},{"id":"a9b4f5a7-f3ad-55f2-8cb6-e9e3f706865b","text":"Использовать самый дешёвый способ без контроля.","displayOrder":4}],"correctOptionId":"8dd527d3-1e64-5e15-bb79-936077ce7b40","explanation":""},{"id":"c15c6945-d695-53f0-bf36-e7d0b832f488","text":"Перед подъёмом связки стержней обнаружено повреждение стропа. Что делать?","displayOrder":2,"options":[{"id":"7c486bfe-e8cc-5ed5-8a29-8485a6d371dc","text":"Не выполнять подъём и заменить строп исправным после проверки ответственным лицом.","displayOrder":1},{"id":"b6c6e09c-bc72-5d4f-a0b7-14ae7f0b2d43","text":"Уменьшить массу груза и использовать повреждённый строп.","displayOrder":2},{"id":"6fbae5b9-1d82-52c7-8c1e-ef2090ee92dc","text":"Усилить строп вязальной проволокой.","displayOrder":3},{"id":"67f57e5f-5bb6-5bd7-817a-24ba607ffe38","text":"Поднимать груз рывком, чтобы сократить время нагрузки.","displayOrder":4}],"correctOptionId":"7c486bfe-e8cc-5ed5-8a29-8485a6d371dc","explanation":""},{"id":"5089da5c-dcb6-55a5-8a8a-5999d003bfa3","text":"После резки рядом со станком накопились острые обрезки. Что сделать?","displayOrder":3,"options":[{"id":"72406deb-f88b-523e-9373-ec79d83a74fd","text":"Оставить обрезки до окончания всей партии.","displayOrder":1},{"id":"db9077d7-deb6-581a-b4b1-6c07a3bb7084","text":"Остановить и безопасно убрать обрезки в предназначенную тару, используя подходящее приспособление.","displayOrder":2},{"id":"74cb9861-b60f-591e-91c1-2d57fb03451f","text":"Сбрасывать обрезки в проход для последующей уборки.","displayOrder":3},{"id":"e382ea46-bc92-5c1b-b9a4-7163239a1c48","text":"Сдвинуть обрезки ногой под станок.","displayOrder":4}],"correctOptionId":"db9077d7-deb6-581a-b4b1-6c07a3bb7084","explanation":""},{"id":"db7790c4-b4ba-525c-b886-4322554ca29d","text":"При установке каркаса возникла зона защемления между каркасом и опалубкой. Как действовать?","displayOrder":4,"options":[{"id":"b09bbae4-6f4c-5692-8480-9a9abb035e2e","text":"Встать между каркасом и опалубкой для точного совмещения.","displayOrder":1},{"id":"334d123e-a33d-582c-a63e-359382668e2e","text":"Удерживать каркас пальцами до полной посадки.","displayOrder":2},{"id":"66f50813-5889-54e5-bccf-d149fed1bec9","text":"Не помещать руки в зону защемления и управлять положением каркаса согласованными средствами и командами.","displayOrder":3},{"id":"51a5c96e-e511-5e18-ab42-52f95625273e","text":"Подталкивать каркас плечом во время опускания.","displayOrder":4}],"correctOptionId":"66f50813-5889-54e5-bccf-d149fed1bec9","explanation":""},{"id":"1ac2d5fb-5bbf-5ccd-90ca-632a439a9723","text":"От чего зависит правильная сборка механического соединения?","displayOrder":5,"options":[{"id":"16f7777f-a905-504a-82a6-f811917ddab3","text":"Только от внешнего блеска муфты.","displayOrder":1},{"id":"059b73ed-9789-532b-8bdd-76292b933de9","text":"Только от усилия, приложенного вручную.","displayOrder":2},{"id":"360799ef-c9b1-5699-a1a1-f3af343f8772","text":"Только от температуры воздуха в начале смены.","displayOrder":3},{"id":"a2f5f61d-a4fb-57e8-9d67-1f9b2f4dc4d6","text":"От проектного решения, совместимости системы, инструкции изготовителя и установленного контроля.","displayOrder":4}],"correctOptionId":"a2f5f61d-a4fb-57e8-9d67-1f9b2f4dc4d6","explanation":""},{"id":"496e0f61-1e0b-5612-8f56-c886a93b90b3","text":"Фиксатор каркаса разрушен до бетонирования. Как поступить?","displayOrder":6,"options":[{"id":"b7f10470-3c8d-541f-8fb0-5f99495773d0","text":"Заменить его подходящим исправным элементом и повторно проверить устойчивость и положение каркаса.","displayOrder":1},{"id":"f08f9f25-f824-594f-bf1e-6aaefd883381","text":"Оставить каркас без фиксатора, если он тяжёлый.","displayOrder":2},{"id":"610f07b2-acbf-5a2e-ab51-8d53fa39cf03","text":"Привязать каркас к опалубке случайной проволокой.","displayOrder":3},{"id":"9f5e5fce-2e63-5e2f-b2a0-492331088996","text":"Подложить случайный деревянный обрезок.","displayOrder":4}],"correctOptionId":"b7f10470-3c8d-541f-8fb0-5f99495773d0","explanation":""},{"id":"f31fe743-cdad-5dee-84eb-b22186396855","text":"Электроинструмент требуется применить на мокром участке. Как поступить?","displayOrder":7,"options":[{"id":"0e9ad062-37ab-5345-800e-8de5b3482cbd","text":"Отключить защитные устройства, чтобы избежать срабатывания.","displayOrder":1},{"id":"41dc91ff-b6c7-542c-86ec-d3c4e2eca973","text":"Положить инструмент на мокрый пол и включить через обычный удлинитель.","displayOrder":2},{"id":"33efc22a-3e4c-50b6-9486-983669161827","text":"Оценить условия, применить предусмотренную электрозащиту и не работать неисправным или неподходящим инструментом.","displayOrder":3},{"id":"d54b469d-e17e-5051-b6e0-ad0df8210e3b","text":"Обернуть корпус тканью и продолжить работу.","displayOrder":4}],"correctOptionId":"33efc22a-3e4c-50b6-9486-983669161827","explanation":""},{"id":"48623af7-e32e-52ab-9fb3-390dab796c09","text":"В какой последовательности готовят место сборки каркаса?","displayOrder":8,"options":[{"id":"690d59e1-4c09-5069-8da8-430a08b6a19d","text":"Сначала раскладывают стержни в проходе, затем ищут чертёж.","displayOrder":1},{"id":"0cf64ac9-28fc-58df-9ce1-f079d7d42462","text":"Изучают задание, ограждают и очищают зону, размещают материалы устойчиво, проверяют инструмент и защиту.","displayOrder":2},{"id":"4ca408d5-5380-5866-b728-b74e9f8a270f","text":"Сначала включают станки, затем освобождают рабочую зону.","displayOrder":3},{"id":"08cbbd40-9181-50aa-9f98-d8917f15930a","text":"Сначала снимают ограждения, затем выбирают СИЗ.","displayOrder":4}],"correctOptionId":"0cf64ac9-28fc-58df-9ce1-f079d7d42462","explanation":""},{"id":"e4c92932-37b2-521d-bcb4-01543cc84051","text":"Поднятый груз завис над монтажной зоной. Что следует сделать?","displayOrder":9,"options":[{"id":"c4a9673d-d18d-5b36-accb-b15b9eada1f3","text":"Использовать груз как временную опору.","displayOrder":1},{"id":"ae0d1c73-fdf1-5ce2-846c-591039b3d9de","text":"Подтолкнуть груз руками снизу.","displayOrder":2},{"id":"37865185-3b4e-504e-95c6-1954987a867b","text":"Продолжить вязку под грузом, пока кран неподвижен.","displayOrder":3},{"id":"9518ffac-9b52-55e6-883c-77903960f449","text":"Прекратить работы под грузом, вывести людей и действовать по установленным командам ответственного персонала.","displayOrder":4}],"correctOptionId":"9518ffac-9b52-55e6-883c-77903960f449","explanation":""},{"id":"5422664f-ee24-55c2-b7d0-e6d33cd90ec7","text":"Для чего применяют фиксаторы арматуры?","displayOrder":10,"options":[{"id":"d3e2ed57-6284-590b-b722-b46b78797a2a","text":"Для удержания каркаса в проектном положении и обеспечения заданного защитного слоя.","displayOrder":1},{"id":"17ec74e4-52ef-5fe4-8b89-e32527515517","text":"Для временного хранения режущего инструмента.","displayOrder":2},{"id":"5702e229-f6af-5e44-8d5d-fa2d0c9f1c11","text":"Для изменения класса стали на площадке.","displayOrder":3},{"id":"376a09d9-17ee-5447-83a5-555a0c200294","text":"Для замены всех соединений стержней.","displayOrder":4}],"correctOptionId":"d3e2ed57-6284-590b-b722-b46b78797a2a","explanation":""}]}],"sourceMaterials":{"presentation":{"filename":"02_Арматурщик.pptx","sha256":"480cd55c460114d9210fae0a1b7232a71345587c676cdecc644351ec2497ffbe"},"tests":{"filename":"06_Тестовые_задания.docx","sha256":"3b36bba9f031c233cd10a4a80e1f7dd2a89af523b5df2145056dc7366086ce00"}},"dbContentHash":"2f7a23db13eee141b55babca50e180de202ce60c7939e7aed771cd3d71f84585","snapshotContentHash":"cbc41898f80dbc720ca392a5c2a1e9860a550b2b02c89c8348a07176fd1713ff","contentHash":"2f7a23db13eee141b55babca50e180de202ce60c7939e7aed771cd3d71f84585"},{"schemaVersion":1,"id":"697acb0f-4761-4eef-bdd3-191939cf0afb","slug":"lesomontazhnye-raboty","title":"Лесомонтажные работы","description":"Безопасный монтаж и эксплуатация лесов: проект, основание, связи, настил, ограждения, доступ, допуск и контроль условий.","icon":"ladder","displayOrder":3,"updatedAt":"2026-08-25T00:00:00.000Z","jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-21","seo":{},"sources":[],"policy":{"durationMinutes":15,"passScore":7,"questionCount":10,"variantCount":3,"attemptsPerCalendarDay":8,"resetTimezone":"Asia/Oral"},"presentation":{"id":"f7ef39ad-72c3-483e-8062-01beb02d4c42","sourceFilename":"presentation.pdf","operatorPptx":"content/source-materials/derived/lesomontazhnye-raboty/presentation.pptx","file":"presentation.pdf","thumbnail":"thumbnail.webp","storageBucket":"course-presentations","storagePath":"697acb0f-4761-4eef-bdd3-191939cf0afb/f7ef39ad-72c3-483e-8062-01beb02d4c42/84034f4073330e9de1de1fd7cf4a12c25751435ab4ec6cac3251944e0500cf8e.pdf","thumbnailPath":"697acb0f-4761-4eef-bdd3-191939cf0afb/f7ef39ad-72c3-483e-8062-01beb02d4c42/84034f4073330e9de1de1fd7cf4a12c25751435ab4ec6cac3251944e0500cf8e-thumb.webp","mimeType":"application/pdf","byteSize":1628986,"pageCount":42,"aspectRatio":"16:9","sha256":"84034f4073330e9de1de1fd7cf4a12c25751435ab4ec6cac3251944e0500cf8e","thumbnailSha256":"2bfa071fe4d833c0beb41f190393bd1a297445cf59d6c5d1b05359bc154fb764","notesIncluded":false},"variants":[{"id":"0ed3fd0d-07bb-53ee-8c0b-dda4bd89ba1e","variantNumber":1,"questions":[{"id":"7d6d72f1-1f4d-5a6c-be94-d6478feeb5d0","text":"Пользователь лесов снял диагональную связь, чтобы пронести материал. Как действовать?","displayOrder":1,"options":[{"id":"b2a38aee-d39c-54d9-ba98-d36287ef7c82","text":"Немедленно прекратить использование участка и восстановить конструкцию допущенным персоналом по проекту.","displayOrder":1},{"id":"fb43b758-cfa3-54a8-beda-832bd5f697c5","text":"Оставить связь снятой до конца смены.","displayOrder":2},{"id":"84365384-7574-5305-be87-5f52ccc118a1","text":"Заменить связь верёвкой.","displayOrder":3},{"id":"cc2f5921-89d1-5112-b37b-169f94ccda05","text":"Разрешить работу, если на настиле находится один человек.","displayOrder":4}],"correctOptionId":"b2a38aee-d39c-54d9-ba98-d36287ef7c82","explanation":""},{"id":"6769c0ca-1f86-5959-910f-e160a39fefb4","text":"Опорная плита лесов установлена на рыхлый грунт без подкладки. Что требуется?","displayOrder":2,"options":[{"id":"1f96b1f0-e729-5e0b-a7dc-fa4421bac739","text":"Подложить случайный кирпич под одну сторону плиты.","displayOrder":1},{"id":"59833fc2-168e-5ea3-a833-73b5279dacdb","text":"Увеличить нагрузку на стойку для уплотнения грунта.","displayOrder":2},{"id":"1a29a980-87fa-5192-bb7f-8e642f7b37fa","text":"Утрамбовать грунт ногой вокруг стойки.","displayOrder":3},{"id":"f6fdebc8-0ac1-50d5-93bc-31dcfff2fe47","text":"Прекратить монтаж и подготовить устойчивое основание по проекту и паспорту системы.","displayOrder":4}],"correctOptionId":"f6fdebc8-0ac1-50d5-93bc-31dcfff2fe47","explanation":""},{"id":"125ee8c2-aef7-5702-a648-7bb0b2933bc9","text":"После сильного ветра видимых повреждений с земли нет. Можно ли сразу возобновить работу?","displayOrder":3,"options":[{"id":"2a89d0af-4b8a-502b-877c-cadbd559834e","text":"Да, если снизить количество материалов на настиле.","displayOrder":1},{"id":"5cda491d-e173-59ca-830d-f4743255aae9","text":"Да, если настил сухой.","displayOrder":2},{"id":"cb51c0bb-c96f-5ef0-bd02-319969219a72","text":"Нет; леса должны пройти внеочередную проверку компетентным лицом до допуска.","displayOrder":3},{"id":"03e6539b-0d79-5bf1-88f7-8df08f169440","text":"Да, если работники используют каски.","displayOrder":4}],"correctOptionId":"cb51c0bb-c96f-5ef0-bd02-319969219a72","explanation":""},{"id":"63665f9e-9350-57c8-8608-47145e4c7205","text":"На настил складируют материалы сверх указанной допустимой нагрузки. Что делать?","displayOrder":4,"options":[{"id":"861a440c-60ad-5017-b768-4fb4abdeff47","text":"Распределить груз у одного края настила.","displayOrder":1},{"id":"db1297af-0b4e-5140-8504-828c70032638","text":"Немедленно прекратить загрузку и привести нагрузку в соответствие с проектом и статусом лесов.","displayOrder":2},{"id":"77324bd6-f300-5dc9-9b81-3054fa118d76","text":"Снять часть связей для расширения места.","displayOrder":3},{"id":"feb744da-75ef-5e26-a0ef-741949d0bcbc","text":"Разрешить перегрузку на короткое время.","displayOrder":4}],"correctOptionId":"db1297af-0b4e-5140-8504-828c70032638","explanation":""},{"id":"088d7595-6f55-579b-adfa-695b5e0f73f0","text":"Для чего леса крепят к сооружению?","displayOrder":5,"options":[{"id":"226944f1-0e15-5225-bda3-9b76c98763ee","text":"Для замены всех диагональных связей.","displayOrder":1},{"id":"cce74001-f22f-5a68-bb8d-d9bcd0125dcb","text":"Чтобы увеличить ширину настила без расчёта.","displayOrder":2},{"id":"7e3b8568-f6b9-5657-ad1f-62697c4cdfdb","text":"Только для обозначения высоты яруса.","displayOrder":3},{"id":"b42c12c1-1cab-5793-97f5-aca894172bf4","text":"Для обеспечения расчётной пространственной устойчивости по проекту и схеме монтажа.","displayOrder":4}],"correctOptionId":"b42c12c1-1cab-5793-97f5-aca894172bf4","explanation":""},{"id":"0e6cf77a-3615-5ba9-ae0e-6bdee837ebfc","text":"Каким должен быть рабочий настил?","displayOrder":6,"options":[{"id":"b450e982-07b2-55dc-a0ff-10ea8400a86c","text":"Сплошным в предусмотренных пределах, устойчивым, закреплённым и без опасных зазоров и повреждений.","displayOrder":1},{"id":"754cd847-3821-5af8-9f2a-6094cb1084d8","text":"Наклонённым к внешнему краю для стока воды.","displayOrder":2},{"id":"918b5257-b1c8-501c-86e0-8b255d4b6a27","text":"Свободно уложенным для быстрого снятия.","displayOrder":3},{"id":"f2a66ca0-9e68-56ef-8a6f-cd3a27865c77","text":"Составленным из любых обрезков разной толщины.","displayOrder":4}],"correctOptionId":"b450e982-07b2-55dc-a0ff-10ea8400a86c","explanation":""},{"id":"102f95b2-ba00-5633-ab4c-a61ecb8e9b4f","text":"Какая мера от падения имеет приоритет при монтаже лесов?","displayOrder":7,"options":[{"id":"c2f82404-2cc7-592d-aefc-3567866e6833","text":"Только личная осторожность монтажника.","displayOrder":1},{"id":"153ab31f-64ab-5fd0-a5f0-a497c30b6762","text":"Только каска без ограждений и страховки.","displayOrder":2},{"id":"ebe1ded0-9d23-5ad5-928e-5ad8ec3e1989","text":"Предусмотренная технология коллективной защиты, дополненная страховочной системой там, где это требуется.","displayOrder":3},{"id":"48976c8f-9a45-5bb8-9391-26b0e39eeffa","text":"Устное предупреждение о высоте.","displayOrder":4}],"correctOptionId":"ebe1ded0-9d23-5ad5-928e-5ad8ec3e1989","explanation":""},{"id":"5830f751-52f8-5dc5-a840-bceb70397b48","text":"Какова правильная последовательность допуска лесов к эксплуатации?","displayOrder":8,"options":[{"id":"f6c1cd59-53ed-5518-a865-d54dfdcc29ed","text":"Проверить только нижний ярус и открыть все уровни.","displayOrder":1},{"id":"3a2c6419-0bd4-51cd-b30b-3e215e7f23c9","text":"Установить маркировку без осмотра конструкции.","displayOrder":2},{"id":"12f99518-f581-56c3-beeb-d9bbd6e203fe","text":"Разрешить работу, затем проверить леса в конце смены.","displayOrder":3},{"id":"c692f7b0-5b06-5f2a-ae85-d6884920a2c4","text":"Завершить монтаж по схеме, провести проверку компетентным лицом, зафиксировать результат и обозначить статус.","displayOrder":4}],"correctOptionId":"c692f7b0-5b06-5f2a-ae85-d6884920a2c4","explanation":""},{"id":"e3376089-fa59-5718-b389-8060e6a2e615","text":"Какова безопасная последовательность демонтажа лесов?","displayOrder":9,"options":[{"id":"4bc987f8-5d1f-5202-bc47-fa2f717af096","text":"Одновременно разбирать несвязанные участки без руководства.","displayOrder":1},{"id":"c63ab398-96b4-5b61-a53f-d029eaf11be2","text":"По утверждённой схеме в обратной технологической последовательности с сохранением устойчивости и ограждением зоны.","displayOrder":2},{"id":"e30deb60-bb97-578e-a707-1b312903349b","text":"Сначала снять все анкеры, затем разбирать настилы.","displayOrder":3},{"id":"c41abc59-33f1-5167-ac20-cb32ceea4d31","text":"Сбрасывать элементы вниз в ограждённую зону.","displayOrder":4}],"correctOptionId":"c63ab398-96b4-5b61-a53f-d029eaf11be2","explanation":""},{"id":"2b1de486-d32a-5e2b-846d-463d53d4c922","text":"Кто такое компетентное лицо при работе с лесами?","displayOrder":10,"options":[{"id":"79039d02-270e-5f8c-9b04-350c03b4f403","text":"Любой пользователь, первым поднявшийся на настил.","displayOrder":1},{"id":"3931d09f-3412-546c-872d-75dc58d26eea","text":"Работник, который только переносит материалы.","displayOrder":2},{"id":"c670127b-013f-588f-abfa-31c18b24fb4d","text":"Назначенный работник с необходимыми знаниями и полномочиями для предусмотренных проверок и решений.","displayOrder":3},{"id":"a51e2917-0fc9-501a-8811-5d65cd71707a","text":"Любой посетитель строительной площадки.","displayOrder":4}],"correctOptionId":"c670127b-013f-588f-abfa-31c18b24fb4d","explanation":""}]},{"id":"8cb0b85c-fab5-5e92-b733-6b0a969f201c","variantNumber":2,"questions":[{"id":"5692c857-f86e-5af4-a9f3-10bc7aa390ed","text":"Работник без соответствующего допуска предлагает изменить высоту настила. Что делать?","displayOrder":1,"options":[{"id":"e3bf3016-7928-5642-ae21-b8085f4dc1be","text":"Разрешить, если не используются инструменты.","displayOrder":1},{"id":"97728e58-c94a-57b4-803f-cec8b36d05a3","text":"Снять ограждение, чтобы ускорить перестановку.","displayOrder":2},{"id":"223449d7-d4b4-5bf4-a3f8-5ac42668e7c3","text":"Не разрешать изменение; монтаж и перестановку выполняет назначенный обученный персонал.","displayOrder":3},{"id":"a52cc2f9-1919-5390-b965-498acbe8cefe","text":"Разрешить изменение под устным наблюдением коллеги.","displayOrder":4}],"correctOptionId":"223449d7-d4b4-5bf4-a3f8-5ac42668e7c3","explanation":""},{"id":"b47dee41-0c82-5cc4-a039-350b4e6e0534","text":"После дождя под основанием лесов появилась просадка. Как поступить?","displayOrder":2,"options":[{"id":"bb9dc14b-a142-5620-b79e-521b7e55b167","text":"Продолжить работу до окончания смены.","displayOrder":1},{"id":"d162894e-0fbe-5857-a43c-9678f14688f5","text":"Закрыть доступ, разгрузить участок по безопасной процедуре и провести проверку с восстановлением основания.","displayOrder":2},{"id":"361169d2-ff9f-55a6-b299-5b7403b6005a","text":"Подбить клинья во время нахождения людей на настиле.","displayOrder":3},{"id":"79a96c3d-56c1-5d2f-88d3-4b1ef9e1ee16","text":"Добавить материалы на противоположную сторону.","displayOrder":4}],"correctOptionId":"d162894e-0fbe-5857-a43c-9678f14688f5","explanation":""},{"id":"d78550a6-f3bc-5ed4-a205-c0045e20c637","text":"На настиле образовался лёд. Как действовать?","displayOrder":3,"options":[{"id":"3c3df9c7-38ad-514b-a997-518dc47d91ee","text":"Посыпать лёд опилками во время продолжения работы.","displayOrder":1},{"id":"ba7f9851-6efe-5a3c-94f2-0011ae1d4120","text":"Передвигаться быстрее, чтобы не задерживаться.","displayOrder":2},{"id":"89fe62b1-96d7-5ff7-9e0c-57c662f5351c","text":"Снять поручень для удобства очистки.","displayOrder":3},{"id":"3bc6520e-d425-5cb5-8b42-744bc4852ccc","text":"Остановить использование участка до безопасного устранения скольжения и повторной оценки условий.","displayOrder":4}],"correctOptionId":"3bc6520e-d425-5cb5-8b42-744bc4852ccc","explanation":""},{"id":"276bdb24-899e-59a9-a079-915e8a10ac45","text":"В настиле обнаружена незакреплённая доска. Как поступить?","displayOrder":4,"options":[{"id":"69ba8e8c-97b6-54d8-ae0d-4dd4a2354e71","text":"Закрыть участок и закрепить или заменить настил допущенным персоналом до использования.","displayOrder":1},{"id":"63a52059-277f-549a-a2fa-c54e5e53ebc4","text":"Прижать доску материалами.","displayOrder":2},{"id":"d16ba25c-c20f-5080-8ebd-daf1bf9a419f","text":"Предупредить работников перешагивать опасное место.","displayOrder":3},{"id":"a26078f2-afd5-58bb-9c4b-cd0d6e416560","text":"Перевернуть доску и продолжить работу.","displayOrder":4}],"correctOptionId":"69ba8e8c-97b6-54d8-ae0d-4dd4a2354e71","explanation":""},{"id":"037aec4a-3506-52d6-8828-f206bdd1126b","text":"Можно ли определять шаг анкеров по одной универсальной цифре?","displayOrder":5,"options":[{"id":"0d718307-9bf4-5d45-adff-a1d3cc0e4439","text":"Да, если леса ниже соседнего здания.","displayOrder":1},{"id":"08e43fa8-4283-54e7-9279-4226642e7693","text":"Нет; параметры принимают по проекту, паспорту изготовителя и схеме конкретной системы.","displayOrder":2},{"id":"4f8d5e48-fe99-595c-875d-3f58c133b1cf","text":"Да, одна цифра подходит для любых лесов.","displayOrder":3},{"id":"88e01f70-2df5-5bdd-9345-f90b6d0e9793","text":"Да, если фасад выполнен из бетона.","displayOrder":4}],"correctOptionId":"08e43fa8-4283-54e7-9279-4226642e7693","explanation":""},{"id":"80b90315-86eb-5bec-a434-decfe2472630","text":"Как организуют безопасный доступ на ярусы лесов?","displayOrder":6,"options":[{"id":"36ba0b91-3604-53d8-85c3-1948ab40c06a","text":"По внешней стороне рам без специальных средств.","displayOrder":1},{"id":"a6b89ee5-d17c-5b43-b063-20038708fc63","text":"По диагональным связям.","displayOrder":2},{"id":"c5ca6347-4f20-5fa8-8458-bd85b94a59cb","text":"С помощью подъёма на грузовой платформе, не предназначенной для людей.","displayOrder":3},{"id":"35972f2b-340f-5f09-88ea-27f001e4d79a","text":"По предусмотренной лестнице или лестничному маршу с исправным креплением и защищённым проёмом.","displayOrder":4}],"correctOptionId":"35972f2b-340f-5f09-88ea-27f001e4d79a","explanation":""},{"id":"1ad23bc6-8cd8-5542-b6cd-321a6b48f47e","text":"Анкерная точка для страховки выбрана на случайном элементе лесов. Что сделать?","displayOrder":7,"options":[{"id":"5a018eef-1ea9-5bb0-bd65-c0a5ce0f950d","text":"Соединить привязь с поясом коллеги.","displayOrder":1},{"id":"c214b37c-fd62-5be7-a454-a930aed00419","text":"Не учитывать возможное свободное падение.","displayOrder":2},{"id":"73e0e34f-a84a-5587-9fce-730b2c157d2e","text":"Использовать только предусмотренную планом и рассчитанную точку крепления с учётом запаса высоты.","displayOrder":3},{"id":"66aa8c10-46cd-5746-964a-4a3ce2f48e2f","text":"Закрепиться за ближайший поручень без проверки.","displayOrder":4}],"correctOptionId":"73e0e34f-a84a-5587-9fce-730b2c157d2e","explanation":""},{"id":"40af5b4c-0367-5887-acc8-a4345d2945b1","text":"Что включает проверка после изменения лесов?","displayOrder":8,"options":[{"id":"95e170ff-1018-5cbc-97c9-1ec860a4d5bd","text":"Проверку только верхнего поручня.","displayOrder":1},{"id":"46eb5597-d542-5ecc-863f-d807e1adaab3","text":"Осмотр основания, элементов, связей, креплений, настилов, ограждений и доступа с фиксацией статуса.","displayOrder":2},{"id":"0273376d-ad87-54f4-9e71-74878c15f9ef","text":"Проверку только цвета маркировки.","displayOrder":3},{"id":"134c0c5f-1d18-5947-a4ff-b4f6cbde0720","text":"Проверку только количества работников.","displayOrder":4}],"correctOptionId":"46eb5597-d542-5ecc-863f-d807e1adaab3","explanation":""},{"id":"a5d5a75a-0515-59db-86eb-8c53cebe713a","text":"На лесах размещена маркировка «не использовать». Что делать?","displayOrder":9,"options":[{"id":"27a8292d-2ccc-59fb-baa5-951787848670","text":"Не входить на леса и ожидать устранения причин и нового допуска компетентным лицом.","displayOrder":1},{"id":"68fa6851-7873-550c-b2a7-3f7e22d91fe2","text":"Использовать только нижний ярус.","displayOrder":2},{"id":"be6d595e-9eb8-55d1-9f16-e50b64720e27","text":"Снять маркировку после устного разрешения коллеги.","displayOrder":3},{"id":"5c0bd61c-8592-541d-b04d-71d603f410fb","text":"Работать без материалов, сохраняя маркировку.","displayOrder":4}],"correctOptionId":"27a8292d-2ccc-59fb-baa5-951787848670","explanation":""},{"id":"b7ac1bbd-f68a-5f06-a682-78b5f2d113d7","text":"Для чего нужен бортовой элемент ограждения?","displayOrder":10,"options":[{"id":"5be2d4f8-0e8b-5eab-ba3e-e04454c9b008","text":"Для увеличения допустимой нагрузки лесов.","displayOrder":1},{"id":"13ff7656-cd4d-5076-9135-175a9d6b48e1","text":"Для замены среднего поручня во всех случаях.","displayOrder":2},{"id":"4f499786-d72c-59f8-8dd4-9879f4fc8fe3","text":"Для крепления электрических кабелей.","displayOrder":3},{"id":"cdfe1ece-13e5-5824-8d78-0156421ef934","text":"Для снижения риска соскальзывания предметов и ног работника за край настила.","displayOrder":4}],"correctOptionId":"cdfe1ece-13e5-5824-8d78-0156421ef934","explanation":""}]},{"id":"ba490446-8f39-5277-ab62-d2124035492c","variantNumber":3,"questions":[{"id":"278ccf96-38a9-5f5e-bb81-8841dbe3e1dd","text":"После передачи лесов в эксплуатацию пользователь заметил недостающий элемент. Какое действие правильное?","displayOrder":1,"options":[{"id":"eae7ccae-e37b-56f8-a5e2-99dc742d3f2c","text":"Перейти на соседний пролёт, не сообщая о дефекте.","displayOrder":1},{"id":"4a9dfb8d-bc92-5a4e-ab29-f539d39e3192","text":"Остановить использование, оградить участок и сообщить компетентному лицу для проверки.","displayOrder":2},{"id":"4b024e9d-7331-5571-beee-9a65b6c1f5f6","text":"Самостоятельно заменить элемент любым подходящим профилем.","displayOrder":3},{"id":"62042341-4ad5-51d9-ab48-18837fe6ea37","text":"Продолжить работу без размещения материалов.","displayOrder":4}],"correctOptionId":"4a9dfb8d-bc92-5a4e-ab29-f539d39e3192","explanation":""},{"id":"7885e909-7fe7-5287-a6d1-6fc6e14347bf","text":"Стойка установлена на набор незакреплённых обрезков. Какое решение верное?","displayOrder":2,"options":[{"id":"f3739f24-20be-51ba-8030-4bdfcd453d5d","text":"Скрепить обрезки проволокой и оставить.","displayOrder":1},{"id":"b7eeeec5-2d0f-5578-b5f4-73322a3dedb2","text":"Подсыпать песок только с одной стороны.","displayOrder":2},{"id":"72742e8b-2b1a-5633-a098-6e74b5eb655b","text":"Переделать опору с использованием предусмотренных базовых элементов на подготовленном основании.","displayOrder":3},{"id":"4e920141-f958-56ce-bfa7-6fd31172eb12","text":"Считать опору допустимой при отсутствии ветра.","displayOrder":4}],"correctOptionId":"72742e8b-2b1a-5633-a098-6e74b5eb655b","explanation":""},{"id":"a6868dc3-cd8a-5a49-b60c-d0148c73d692","text":"При работе ухудшилась видимость и усилился ветер. Что должен сделать руководитель?","displayOrder":3,"options":[{"id":"cbac7473-0343-5941-85f0-a40d7b2c585a","text":"Оценить условия и остановить работу, если безопасное выполнение и устойчивость не обеспечены.","displayOrder":1},{"id":"23b3d84c-ff04-5ca2-8596-309c278c713f","text":"Убрать сигнальные ограждения, чтобы их не сорвало.","displayOrder":2},{"id":"1506c3b7-f181-5063-bec9-c0dbafcb9acc","text":"Разрешить работу без перемещения материалов.","displayOrder":3},{"id":"41ae0574-866e-5eb3-b99b-238955e8c927","text":"Продолжить работу только на верхнем ярусе.","displayOrder":4}],"correctOptionId":"cbac7473-0343-5941-85f0-a40d7b2c585a","explanation":""},{"id":"57be894a-ea0f-5209-94dc-9c54523c4fce","text":"На ярусе отсутствует бортовой элемент, а внизу работают люди. Какое действие правильное?","displayOrder":4,"options":[{"id":"86c20103-061a-5c2a-822e-d924776e393f","text":"Сдвинуть материалы ближе к краю для освобождения прохода.","displayOrder":1},{"id":"40c3dd22-d271-5044-b005-560e84df97a0","text":"Продолжить, если инструмент лежит в карманах.","displayOrder":2},{"id":"cd147d86-0666-52f0-b247-f44f9088c127","text":"Поставить устное предупреждение без ограждения зоны.","displayOrder":3},{"id":"2613b877-b504-519c-a0e4-b096271a9763","text":"Остановить работу, исключить нахождение людей внизу и восстановить защиту от падения предметов.","displayOrder":4}],"correctOptionId":"2613b877-b504-519c-a0e4-b096271a9763","explanation":""},{"id":"53ac272c-f246-5208-8198-9dfa6af90216","text":"Как следует поступить с ослабленным хомутом или соединением?","displayOrder":5,"options":[{"id":"b67b973b-d47a-532e-89fc-66a6d394af23","text":"Подтянуть его во время нахождения людей на настиле.","displayOrder":1},{"id":"ed0cc646-2b91-53bf-a073-e4633c656de0","text":"Заменить хомут проволокой.","displayOrder":2},{"id":"e18d9924-f2ff-52fc-a17c-84b98d50b46f","text":"Остановить использование затронутого участка и восстановить соединение по системе с последующей проверкой.","displayOrder":3},{"id":"5c241580-1d25-5908-9f10-3161cf1b5aeb","text":"Оставить до планового демонтажа.","displayOrder":4}],"correctOptionId":"e18d9924-f2ff-52fc-a17c-84b98d50b46f","explanation":""},{"id":"a8580d1d-b97b-5ab4-8e8a-10f209c2a08e","text":"Что обязательно учитывать при устройстве ограждения настила?","displayOrder":6,"options":[{"id":"e1aa8a8c-99a0-5f9f-9e73-0a479f1c03cf","text":"Непрерывность поручней, промежуточной защиты и бортовых элементов согласно проекту и системе лесов.","displayOrder":1},{"id":"a6cceb3a-9be1-5a33-9f71-e89180e439b2","text":"Только наличие одного каната на внешней стороне.","displayOrder":2},{"id":"9625466b-a240-563a-93d9-7f0af4c17db3","text":"Только высоту ближайшей стены.","displayOrder":3},{"id":"80e52545-3d7d-5b3f-aceb-38d8eb15ca0c","text":"Только цвет верхнего поручня.","displayOrder":4}],"correctOptionId":"e1aa8a8c-99a0-5f9f-9e73-0a479f1c03cf","explanation":""},{"id":"5bdc6210-5957-59dd-89df-fc0c5b4dc433","text":"Леса расположены рядом с электроустановкой. Как действовать?","displayOrder":7,"options":[{"id":"0f4a651f-96f2-5f12-84b0-2108675cc668","text":"Перемещать длинные элементы над проводами вручную.","displayOrder":1},{"id":"77c1063e-7d0d-544c-9094-9d9fcf6ab68e","text":"Соблюсти установленные безопасные расстояния и защитные меры по плану, исключив приближение элементов и людей.","displayOrder":2},{"id":"51c582b6-3756-58a6-8dcf-aaa32064f23a","text":"Считать металлические леса защитным заземлением без проверки.","displayOrder":3},{"id":"23093c95-d691-5861-ae3a-d721792954f2","text":"Продолжить работу при отключённом освещении.","displayOrder":4}],"correctOptionId":"77c1063e-7d0d-544c-9094-9d9fcf6ab68e","explanation":""},{"id":"3da37fc5-bb04-57c5-8ca8-a7cb0fc3fd67","text":"Когда требуется внеочередная проверка?","displayOrder":8,"options":[{"id":"77962d55-ba31-5785-83f5-823f25e80598","text":"Только после полного демонтажа.","displayOrder":1},{"id":"8dfdefbe-dbcb-535f-8527-c4a65bdfa228","text":"Только перед праздничными днями.","displayOrder":2},{"id":"c4a3b9fe-0cd8-586b-8603-a362ac22287e","text":"После изменения, повреждения, просадки, неблагоприятной погоды или другого события, способного повлиять на безопасность.","displayOrder":3},{"id":"d41bec89-6674-5aca-995b-1a1dcf1c5b24","text":"Только при смене цвета фасада.","displayOrder":4}],"correctOptionId":"c4a3b9fe-0cd8-586b-8603-a362ac22287e","explanation":""},{"id":"45427f1d-f108-5aa0-88e2-f23a404cb6be","text":"Во время демонтажа найден деформированный элемент. Как поступить?","displayOrder":9,"options":[{"id":"f0ea4f18-3bbb-51a6-a522-9d9247e707a7","text":"Спрятать элемент в общей пачке.","displayOrder":1},{"id":"ae367e9f-72df-5213-810b-0a0ecf40d6e5","text":"Использовать его как временную опорную подкладку.","displayOrder":2},{"id":"875a4d99-124f-5b7e-a674-82ca8a554229","text":"Выпрямить ударом и сразу установить на другом участке.","displayOrder":3},{"id":"94c2c398-66e0-569c-a227-c05ed69b1223","text":"Отделить его от исправных элементов, промаркировать и направить на установленную отбраковку или оценку.","displayOrder":4}],"correctOptionId":"94c2c398-66e0-569c-a227-c05ed69b1223","explanation":""},{"id":"0b63f5e5-62ed-5a5a-b439-cbcf4a93d2c4","text":"Что означает анкерное крепление лесов?","displayOrder":10,"options":[{"id":"a2e7a74f-b504-5cab-b646-ad5490dd683e","text":"Предусмотренное проектом соединение лесов с сооружением, обеспечивающее их устойчивость.","displayOrder":1},{"id":"f4f3e019-a8c9-54dd-affe-502d48a7146c","text":"Маркировку допустимой нагрузки на настиле.","displayOrder":2},{"id":"d1e46088-3658-579c-928b-534e5b29d638","text":"Любую верёвку между двумя стойками.","displayOrder":3},{"id":"81113a66-6c91-50b7-bf5a-8b56b98f034b","text":"Подкладку под базовую плиту.","displayOrder":4}],"correctOptionId":"a2e7a74f-b504-5cab-b646-ad5490dd683e","explanation":""}]}],"sourceMaterials":{"presentation":{"filename":"03_Лесомонтажные_работы.pptx","sha256":"7b8b4b247ba1fe3ff3480ded219417ece9710daa0fd12875f81db10d058228d6"},"tests":{"filename":"06_Тестовые_задания.docx","sha256":"3b36bba9f031c233cd10a4a80e1f7dd2a89af523b5df2145056dc7366086ce00"}},"dbContentHash":"2f260a510155afc0fb2bc20271deecd24b05afa6e68a7da13b68d3a90d9dcf01","snapshotContentHash":"1ff50fbdb46faeb0c2473bdd6ff82bd193ab4f975e04b021a08d0735b96a8584","contentHash":"2f260a510155afc0fb2bc20271deecd24b05afa6e68a7da13b68d3a90d9dcf01"},{"schemaVersion":1,"id":"56c7fac7-7181-47e9-91cc-aa88e3c59191","slug":"biot","title":"БИОТ","description":"Базовые требования безопасности и охраны труда: опасности, оценка риска, обучение, допуск, средства защиты и аварийные действия.","icon":"shield","displayOrder":4,"updatedAt":"2026-08-25T00:00:00.000Z","jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-21","seo":{},"sources":[],"policy":{"durationMinutes":15,"passScore":7,"questionCount":10,"variantCount":3,"attemptsPerCalendarDay":8,"resetTimezone":"Asia/Oral"},"presentation":{"id":"9ece511d-f3b3-4209-bc7d-0429ba387684","sourceFilename":"presentation.pdf","operatorPptx":"content/source-materials/derived/biot/presentation.pptx","file":"presentation.pdf","thumbnail":"thumbnail.webp","storageBucket":"course-presentations","storagePath":"56c7fac7-7181-47e9-91cc-aa88e3c59191/9ece511d-f3b3-4209-bc7d-0429ba387684/a68cdfab938ab90cc8e847cd6fa5c0309c9caaa856795cbd70289eeb091afd9c.pdf","thumbnailPath":"56c7fac7-7181-47e9-91cc-aa88e3c59191/9ece511d-f3b3-4209-bc7d-0429ba387684/a68cdfab938ab90cc8e847cd6fa5c0309c9caaa856795cbd70289eeb091afd9c-thumb.webp","mimeType":"application/pdf","byteSize":1176614,"pageCount":59,"aspectRatio":"16:9","sha256":"a68cdfab938ab90cc8e847cd6fa5c0309c9caaa856795cbd70289eeb091afd9c","thumbnailSha256":"99439358d73cbe9428b681beeeef39311b25b64d8c8dca85a169015393a3901c","notesIncluded":false},"variants":[{"id":"cb8dfec8-21a6-59a3-8725-931cfc14bf5a","variantNumber":1,"questions":[{"id":"b96a656b-41f1-5470-9591-e672694a80d4","text":"Работник видит непосредственную угрозу обрушения в своей зоне. Как действовать?","displayOrder":1,"options":[{"id":"3d80e1fd-a064-535a-9183-a93a48845297","text":"Продолжить работу до получения письменного указания.","displayOrder":1},{"id":"8df94b5f-9e02-5504-8c25-0f547a62ccf5","text":"Прекратить работу, выйти из опасной зоны и немедленно сообщить руководителю в установленном порядке.","displayOrder":2},{"id":"059d1b90-1bfb-54df-802d-6c77012563ac","text":"Самостоятельно устранить угрозу без оценки и ограждения.","displayOrder":3},{"id":"a8cb0294-a61a-54a6-973e-4c7dc740898e","text":"Попросить коллегу наблюдать, пока работа продолжается.","displayOrder":4}],"correctOptionId":"8df94b5f-9e02-5504-8c25-0f547a62ccf5","explanation":""},{"id":"132a9aa0-21b1-5407-b38c-e95fbe579410","text":"Произошла травма работника. Какое первоочередное действие очевидца правильное?","displayOrder":2,"options":[{"id":"c1434394-5882-5284-beba-a5964dfdbe2a","text":"Немедленно изменить место происшествия без необходимости спасения.","displayOrder":1},{"id":"a4558963-d046-5259-b923-c824a8b1890a","text":"Отправить пострадавшего одного заполнять документы.","displayOrder":2},{"id":"4420fbed-ac73-5fc0-9b3d-4ab5977d2e1b","text":"Остановить воздействие опасности, вызвать помощь, оказать посильную первую помощь и сообщить о происшествии.","displayOrder":3},{"id":"a37e5c5c-ee12-5466-8410-2af18436cc45","text":"Сначала закончить производственную операцию.","displayOrder":4}],"correctOptionId":"4420fbed-ac73-5fc0-9b3d-4ab5977d2e1b","explanation":""},{"id":"ea421348-3b63-536c-a8a4-c2f46a9945cb","text":"Защитное ограждение оборудования повреждено. Что обязан сделать работник?","displayOrder":3,"options":[{"id":"c5dac3c2-a0ba-596b-806e-56fde4ffb915","text":"Работать только при присутствии коллеги.","displayOrder":1},{"id":"0ec46c0a-cfd5-5b82-b142-c71d3a7c3234","text":"Снять оставшуюся часть ограждения и продолжить работу.","displayOrder":2},{"id":"ad8ff1a5-9fc7-5e68-a3c5-6726a002a6cf","text":"Закрыть повреждение картоном без сообщения.","displayOrder":3},{"id":"786a4aef-5056-5516-af08-0c5f811ec2df","text":"Остановить использование оборудования и сообщить о неисправности ответственному лицу.","displayOrder":4}],"correctOptionId":"786a4aef-5056-5516-af08-0c5f811ec2df","explanation":""},{"id":"08644b64-94d3-5f58-8960-85740a7ecc08","text":"Какую меру следует рассматривать раньше выдачи дополнительных СИЗ?","displayOrder":4,"options":[{"id":"6d5c920f-21ba-5060-a463-958d7f2b4bfa","text":"Устранение опасности или техническое ограждение и изоляцию источника, если это возможно.","displayOrder":1},{"id":"61e8d935-44a9-51c2-9695-a2fade0b8e1b","text":"Увеличение продолжительности смены.","displayOrder":2},{"id":"d004ce74-5eea-5486-ab29-948fcd85f71e","text":"Перенос инструктажа на конец работы.","displayOrder":3},{"id":"7b5a032c-5437-57cb-b8ef-9cfe96d6a1d9","text":"Замена предупреждающего знака на более крупный без иных мер.","displayOrder":4}],"correctOptionId":"6d5c920f-21ba-5060-a463-958d7f2b4bfa","explanation":""},{"id":"7ccde0d5-2976-5bcb-9fcf-9ef4066781ec","text":"Когда работника допускают к самостоятельной работе?","displayOrder":5,"options":[{"id":"ab91f431-2c74-586f-bc00-2dff483ad4d4","text":"После устного знакомства с коллегой.","displayOrder":1},{"id":"7dd5801a-415a-5943-be6b-42b258f3c339","text":"После первого самостоятельного выполнения операции.","displayOrder":2},{"id":"1ab378d4-f1cd-5dc2-875c-25a48bde5dc5","text":"После требуемого обучения, инструктажа, проверки знаний и иных установленных допусков для его работы.","displayOrder":3},{"id":"dd60a02e-ad61-5eb1-8881-02676192d39d","text":"Сразу после подписания табеля.","displayOrder":4}],"correctOptionId":"1ab378d4-f1cd-5dc2-875c-25a48bde5dc5","explanation":""},{"id":"8e8eb823-6b0f-549d-8a53-816782664d0a","text":"Кто обеспечивает выдачу необходимых СИЗ работнику?","displayOrder":6,"options":[{"id":"adfe99f9-16be-5438-96c5-941bf9e0708a","text":"Любой посетитель рабочей площадки.","displayOrder":1},{"id":"8ec13757-df81-5d97-a9cf-579683a6a7c1","text":"Сам работник за счёт обязательной покупки в любом магазине.","displayOrder":2},{"id":"35cc8555-dcee-5e46-afef-19f0c992eaba","text":"Только изготовитель оборудования.","displayOrder":3},{"id":"15290c7d-0df8-5bcc-922a-5fc807f79e4b","text":"Работодатель в соответствии с рисками, нормами и установленным порядком.","displayOrder":4}],"correctOptionId":"15290c7d-0df8-5bcc-922a-5fc807f79e4b","explanation":""},{"id":"c8171b54-c12c-599c-97e8-7b74abc3ddc0","text":"На опасном производственном объекте планируется газоопасная работа. Что необходимо до начала?","displayOrder":7,"options":[{"id":"4ad0b8d9-3b0f-5427-87d4-897ad5eab21e","text":"Начать работу после устного согласия ближайшего коллеги.","displayOrder":1},{"id":"3a34d569-cb02-5209-b142-5e283df618b9","text":"Организовать работу по установленной процедуре и наряду-допуску с анализом среды, защитой и готовностью к аварии.","displayOrder":2},{"id":"8d4f8e13-3643-5922-993c-57f5c878f0b0","text":"Проверить атмосферу по запаху.","displayOrder":3},{"id":"da642e1a-3b43-5f2d-b4d3-6afa00b11eee","text":"Отключить сигнализацию, чтобы она не мешала.","displayOrder":4}],"correctOptionId":"3a34d569-cb02-5209-b142-5e283df618b9","explanation":""},{"id":"f5b6ee1d-f2fe-5960-9d9d-3241f09fd06e","text":"Как работник должен действовать при сигнале аварии на ОПО?","displayOrder":8,"options":[{"id":"182a0b0c-485f-506b-980b-130e8bb3b919","text":"Прекратить работу, выполнить предусмотренные планом действия, покинуть или занять безопасное место и доложить по установленной связи.","displayOrder":1},{"id":"a086cbd6-f0ae-52ff-a847-e5ea12b58316","text":"Продолжить работу до указания коллеги.","displayOrder":2},{"id":"a6f45a7d-f1fa-55ba-a523-0e78e5071595","text":"Вернуться за личными вещами после выхода.","displayOrder":3},{"id":"a73bffca-153f-54fc-bc55-4d62bcc483b5","text":"Самостоятельно изменить маршрут эвакуации без причины.","displayOrder":4}],"correctOptionId":"182a0b0c-485f-506b-980b-130e8bb3b919","explanation":""},{"id":"25b5b16f-ca43-531b-b0c0-04bd7dabe4db","text":"Перед работой с оборудованием под давлением отсутствует разрешающая маркировка и статус непонятен. Что делать?","displayOrder":9,"options":[{"id":"2d9df961-1c83-56a4-8504-cdbe8ec05d96","text":"Открыть арматуру ударами инструмента.","displayOrder":1},{"id":"e53d34ff-2416-5677-9017-96c3d05c6101","text":"Включить на минимальном давлении для проверки.","displayOrder":2},{"id":"af9fcfa3-53c1-52d3-bc55-6855e457a511","text":"Нанести дату маркером самостоятельно.","displayOrder":3},{"id":"5af83904-4aa9-5a4b-91da-b0cc2451cd0c","text":"Не включать оборудование и запросить подтверждение допуска и технического состояния у ответственного лица.","displayOrder":4}],"correctOptionId":"5af83904-4aa9-5a4b-91da-b0cc2451cd0c","explanation":""},{"id":"b1e7342a-f694-5346-b959-2d404a37151d","text":"Что такое опасный производственный объект?","displayOrder":10,"options":[{"id":"776067b3-105c-54b5-a1dc-bda99e77d0fe","text":"Любое помещение, где работает больше двух человек.","displayOrder":1},{"id":"a4ea85ad-20d3-50b8-877d-001c340dccd4","text":"Только здание пожарной части.","displayOrder":2},{"id":"bc864dde-7007-58fa-b0cf-2702d12e7ff2","text":"Объект, идентифицированный по установленным законом признакам наличия опасных веществ, процессов или технических устройств.","displayOrder":3},{"id":"967b9c84-6269-5d8a-b812-0f90c2ea2975","text":"Любая территория с пропускным режимом.","displayOrder":4}],"correctOptionId":"bc864dde-7007-58fa-b0cf-2702d12e7ff2","explanation":""}]},{"id":"adf6ab88-5108-5cad-b44a-162073d7632a","variantNumber":2,"questions":[{"id":"8cdf7782-a80c-5cbd-aa0e-cdd3aeb26e2c","text":"Работнику поручили операцию, безопасному выполнению которой он не обучен. Как поступить?","displayOrder":1,"options":[{"id":"ff6b9194-9692-5785-b826-0ac9b4bf4aec","text":"Подписать журнал после выполнения работы.","displayOrder":1},{"id":"d46128ad-7556-5024-a2bd-f4cea6d2e5f7","text":"Передать операцию другому необученному работнику.","displayOrder":2},{"id":"eb88cbd9-057e-5ae7-a261-a4dd5c5b9f5e","text":"Выполнить операцию по примеру коллеги без инструктажа.","displayOrder":3},{"id":"39c59ddb-183b-5b70-9efa-7abaabae9f3c","text":"Не начинать операцию и сообщить руководителю о необходимости обучения и допуска.","displayOrder":4}],"correctOptionId":"39c59ddb-183b-5b70-9efa-7abaabae9f3c","explanation":""},{"id":"ae4258bd-6a0e-551e-9f29-2a7b7f15632b","text":"Произошёл инцидент без травмы, но могло быть тяжёлое последствие. Что следует сделать?","displayOrder":2,"options":[{"id":"e5019704-1db4-579d-be85-c6fffa4c9896","text":"Сообщить об инциденте, сохранить доступные сведения и участвовать в разборе причин и мерах предупреждения.","displayOrder":1},{"id":"10d667d4-7886-5847-98f3-350776baf457","text":"Обсудить случай только неофициально после смены.","displayOrder":2},{"id":"834af64f-8d47-5f8c-994b-17fa06e76301","text":"Не сообщать, поскольку никто не пострадал.","displayOrder":3},{"id":"dd766577-d309-5753-85d1-3b0f61579230","text":"Удалить записи, чтобы не останавливать работу.","displayOrder":4}],"correctOptionId":"e5019704-1db4-579d-be85-c6fffa4c9896","explanation":""},{"id":"83c5fdf0-9a52-5731-a87e-6e6af48a995f","text":"Работник заметил разлив неизвестного вещества. Как действовать?","displayOrder":3,"options":[{"id":"4e425888-6735-5815-849a-29051d13121c","text":"Проверить вещество на запах с близкого расстояния.","displayOrder":1},{"id":"27d537ad-b069-5625-9583-6dd6a6538506","text":"Оградить или покинуть опасную зону по обстановке и сообщить, не приступая к ликвидации без подготовки и средств.","displayOrder":2},{"id":"f675830d-c6ed-577c-ab0b-18dec82aaa0f","text":"Смыть разлив в канализацию.","displayOrder":3},{"id":"60205898-3f4a-5b80-854c-cf4453d7345d","text":"Собрать вещество голыми руками в обычную тару.","displayOrder":4}],"correctOptionId":"27d537ad-b069-5625-9583-6dd6a6538506","explanation":""},{"id":"f0210db0-654c-5ef6-bcbe-5a713da95894","text":"В зоне постоянно возникает опасная пыль. Какой подход соответствует иерархии контроля?","displayOrder":4,"options":[{"id":"865f4b1c-e43d-5316-a343-243640e7810d","text":"Убирать пыль сухой метлой во время работы.","displayOrder":1},{"id":"3aa16ec1-10ee-5b11-82a7-9c705067dea9","text":"Считать предупреждающую надпись достаточной защитой.","displayOrder":2},{"id":"9b87bfaf-e101-5410-a258-89f425ee17c1","text":"Ограничиться выдачей одноразовых масок без оценки.","displayOrder":3},{"id":"b55c58f1-decf-53b4-b9b3-23bd67d3d631","text":"Сначала рассмотреть устранение или замену процесса и инженерное удаление пыли, затем организационные меры и СИЗ.","displayOrder":4}],"correctOptionId":"b55c58f1-decf-53b4-b9b3-23bd67d3d631","explanation":""},{"id":"cb6a97f2-e65c-5b41-9b69-645a9b1abc98","text":"Переводится ли обучение автоматически при любом переводе работника?","displayOrder":5,"options":[{"id":"fa99446a-9511-55ac-b7f0-25f34f07102d","text":"Решение принимает сам работник без документов работодателя.","displayOrder":1},{"id":"3fd23602-4571-5fc5-a7b9-fdbba2b6dfe9","text":"Да, повторное обучение запрещено при любом переводе.","displayOrder":2},{"id":"c3ab6856-ea49-57aa-96a0-a445df5d3e8d","text":"Порядок определяет работодатель по действующим правилам с учётом профессии, работы и условий; отсутствие повторения возможно только в предусмотренном случае.","displayOrder":3},{"id":"c6d9b034-6c4e-5f56-b2ac-a47e2404e1d7","text":"Нет, обучение всегда повторяется независимо от условий.","displayOrder":4}],"correctOptionId":"c3ab6856-ea49-57aa-96a0-a445df5d3e8d","explanation":""},{"id":"3d8486fb-7cd3-5949-806d-7747dcb475b4","text":"Что обязан сделать работник с выданными СИЗ?","displayOrder":6,"options":[{"id":"53f2c7d6-1c1f-5732-9f87-61397db0a677","text":"Изменять конструкцию для удобства без согласования.","displayOrder":1},{"id":"3daf22fb-28f1-5559-94fa-dbee37afa396","text":"Правильно применять, проверять перед использованием, беречь и сообщать о дефектах.","displayOrder":2},{"id":"17e12411-832d-56c2-adb1-af2ce2452017","text":"Передавать их любому лицу без учёта размера и назначения.","displayOrder":3},{"id":"26e7f553-1183-59b8-adfb-23b26e8d1812","text":"Использовать неисправные СИЗ до получения новых.","displayOrder":4}],"correctOptionId":"3daf22fb-28f1-5559-94fa-dbee37afa396","explanation":""},{"id":"54d4fbe1-0235-565d-9c0a-bf8d24c5fe59","text":"Обнаружен запах, похожий на сероводород, и сработал газоанализатор. Как действовать?","displayOrder":7,"options":[{"id":"a455be56-91db-5a2d-8adc-87d92f6472d6","text":"Немедленно покинуть опасную зону по маршруту, предупредить других и сообщить по аварийному порядку.","displayOrder":1},{"id":"4923c962-6c1c-53a7-9b12-77594d7072e5","text":"Продолжить работу при открытой двери.","displayOrder":2},{"id":"6cfeef59-1c12-58a6-88d3-108efbd9e873","text":"Искать утечку в одиночку без дыхательной защиты.","displayOrder":3},{"id":"5423b12d-ff59-5e1a-8cd1-5babb5f71d8e","text":"Снять средство защиты, чтобы точнее определить запах.","displayOrder":4}],"correctOptionId":"a455be56-91db-5a2d-8adc-87d92f6472d6","explanation":""},{"id":"84f7ead1-6adb-5123-9371-fe3fc20f698f","text":"Какова цель плана ликвидации аварий?","displayOrder":8,"options":[{"id":"f52fb4ba-c6b3-5c2d-b1f0-6acae7fa8070","text":"Определить размер заработной платы аварийной группы.","displayOrder":1},{"id":"5e99f603-9438-53f5-9cae-7a2644668f40","text":"Заменить техническое обслуживание оборудования.","displayOrder":2},{"id":"4f4b332f-3c84-5ce5-b93c-7c1af83997aa","text":"Установить график обычной уборки помещений.","displayOrder":3},{"id":"5bbdf605-5d5e-57b1-ba4d-7de9e84d757e","text":"Заранее определить оповещение, действия персонала, управление и ресурсы для локализации аварии и защиты людей.","displayOrder":4}],"correctOptionId":"5bbdf605-5d5e-57b1-ba4d-7de9e84d757e","explanation":""},{"id":"498d012e-7466-5ccc-92a8-6d416e82c366","text":"Перед входом в резервуар газоанализ не выполнен. Как поступить?","displayOrder":9,"options":[{"id":"d5ad42c0-bafe-5243-8689-d8f379435099","text":"Войти на короткое время, задержав дыхание.","displayOrder":1},{"id":"c219e516-cbce-55b2-9a3a-ceb92a2d2443","text":"Проверить воздух горящей спичкой.","displayOrder":2},{"id":"ca167b24-fccd-5c7c-bee8-41f9d790da8a","text":"Не входить до оформления процедуры, анализа среды, вентиляции, наблюдения и готовности к спасению.","displayOrder":3},{"id":"21fae48e-6545-585b-934e-aaba228cf9a0","text":"Разрешить вход одному работнику без наблюдающего.","displayOrder":4}],"correctOptionId":"ca167b24-fccd-5c7c-bee8-41f9d790da8a","explanation":""},{"id":"3ab428ba-4222-56c8-92c0-410eb3ab6aab","text":"Что означает инцидент в промышленной безопасности?","displayOrder":10,"options":[{"id":"bba1e961-564f-535a-93af-57f22bb82e5c","text":"Любое письменное замечание работнику.","displayOrder":1},{"id":"cb0a277f-ae39-5303-b1a4-b1679b14fb30","text":"Отказ, повреждение или отклонение на ОПО, которое нарушило безопасное ведение процесса, но не достигло признаков аварии.","displayOrder":2},{"id":"e87e147e-5bcf-5ca3-b61d-8b28d4eacd1c","text":"Только несчастный случай вне производства.","displayOrder":3},{"id":"c65b1393-396d-5817-9eca-a1a97d675cc0","text":"Любую плановую остановку на обед.","displayOrder":4}],"correctOptionId":"cb0a277f-ae39-5303-b1a4-b1679b14fb30","explanation":""}]},{"id":"1c6f90ed-50d9-5f92-a14f-380caec6523a","variantNumber":3,"questions":[{"id":"added656-a55c-52cb-a44d-8d359edb6183","text":"В рабочей зоне внезапно возникла опасность для жизни. Как реализуется право на безопасный труд?","displayOrder":1,"options":[{"id":"ba57aaa7-97dd-51a0-9165-f995b32fca56","text":"Работник прекращает работу и уведомляет установленное ответственное лицо о непосредственной угрозе.","displayOrder":1},{"id":"7d25423c-a3b7-56a5-865a-c43650c8467c","text":"Работник скрывает опасность до планового совещания.","displayOrder":2},{"id":"34157b98-457c-5c49-9dfb-9693b6bddee8","text":"Работник покидает организацию без сообщения.","displayOrder":3},{"id":"93ad51ba-196a-5739-a59d-c3b2ed4f536d","text":"Работник продолжает работу, если смена почти закончилась.","displayOrder":4}],"correctOptionId":"ba57aaa7-97dd-51a0-9165-f995b32fca56","explanation":""},{"id":"6f1b3155-2144-5411-8e9b-a262f99d2868","text":"После происшествия нужно сохранить обстановку. Когда её допустимо изменить?","displayOrder":2,"options":[{"id":"bdcfd472-7a2a-540f-ab10-4e613fee6bef","text":"Всегда сразу после происшествия для быстрой уборки.","displayOrder":1},{"id":"325d742f-c69d-5fff-8b27-57009aa45a35","text":"Только ради продолжения производственного плана.","displayOrder":2},{"id":"1e2dbb5b-f0b6-52c4-a678-8008f5aed8b8","text":"По просьбе любого свидетеля без документирования.","displayOrder":3},{"id":"2d210e33-3859-5cb1-892c-2d8101e1bb80","text":"Когда это необходимо для спасения людей, предотвращения дальнейшей опасности или по указанию ответственных служб с фиксацией изменений.","displayOrder":4}],"correctOptionId":"2d210e33-3859-5cb1-892c-2d8101e1bb80","explanation":""},{"id":"746f572b-5f22-5f6a-9ff2-e8b9ab877fb8","text":"Инструмент начал издавать необычный звук и вибрацию. Что требуется?","displayOrder":3,"options":[{"id":"f5d880bf-6145-535c-8b75-6850c760a60d","text":"Продолжить до планового перерыва.","displayOrder":1},{"id":"a03c44b0-fbe0-5569-9d59-eb9c43c73301","text":"Передать работающий инструмент коллеге без объяснения.","displayOrder":2},{"id":"2365b0aa-18b4-5dcc-b88d-9ed30bfe8e37","text":"Прекратить работу, безопасно отключить инструмент и сообщить о неисправности.","displayOrder":3},{"id":"bf6d63c7-c2d4-5eca-8310-a39ab67acb2e","text":"Увеличить нагрузку для проверки мощности.","displayOrder":4}],"correctOptionId":"2365b0aa-18b4-5dcc-b88d-9ed30bfe8e37","explanation":""},{"id":"83fef26f-148d-5958-85cf-f950a39d6506","text":"Опасное движение механизма можно физически изолировать. Какой контроль предпочтителен?","displayOrder":4,"options":[{"id":"8f0d8b89-151c-5420-88c7-159e82cd65f1","text":"Только выдать перчатки независимо от риска захвата.","displayOrder":1},{"id":"8d63e01e-d1e4-55d1-be37-0a58385dccdc","text":"Установить исправное техническое ограждение с предусмотренными блокировками.","displayOrder":2},{"id":"a2274050-9490-5f24-a221-4878dc006792","text":"Только напомнить работникам быть внимательнее.","displayOrder":3},{"id":"786cc205-fd27-5fc4-a8c3-0010bd0b966a","text":"Только сократить время нахождения рядом.","displayOrder":4}],"correctOptionId":"8d63e01e-d1e4-55d1-be37-0a58385dccdc","explanation":""},{"id":"12e7e21a-bc88-5bad-937f-fd65dbc6bc74","text":"Зачем проводится целевой инструктаж?","displayOrder":5,"options":[{"id":"cd7d6c90-cbf3-54dd-9a93-a995715081ba","text":"Для конкретной разовой или опасной работы и условий её безопасного выполнения в установленных случаях.","displayOrder":1},{"id":"13b40efb-1886-5a2f-a0d7-48eb55067cb7","text":"Для замены всех видов профессионального обучения.","displayOrder":2},{"id":"1d2b66e4-da71-5221-ac44-f16b7071c093","text":"Только для ознакомления с графиком отпусков.","displayOrder":3},{"id":"dbf57436-2565-51ae-adef-dc342a70845e","text":"Для разрешения работать неисправным оборудованием.","displayOrder":4}],"correctOptionId":"cd7d6c90-cbf3-54dd-9a93-a995715081ba","explanation":""},{"id":"6de1f664-6418-5957-9aa8-e454ff09f413","text":"Почему коллективная защита обычно рассматривается раньше индивидуальной?","displayOrder":6,"options":[{"id":"a3034cb0-7e15-5eac-a944-828d791f7730","text":"Она всегда дешевле любого другого решения.","displayOrder":1},{"id":"b8baba1a-c824-5d6d-93ef-6ad5bc29f187","text":"Она используется только после несчастного случая.","displayOrder":2},{"id":"63bbabd9-0a2e-5cf2-9443-d02e5f4fb9cf","text":"Она снижает воздействие опасности сразу для группы людей и меньше зависит от поведения каждого.","displayOrder":3},{"id":"e47b32a7-e669-5a86-be18-9ceb2dbf7f4c","text":"Она позволяет отменить обучение персонала.","displayOrder":4}],"correctOptionId":"63bbabd9-0a2e-5cf2-9443-d02e5f4fb9cf","explanation":""},{"id":"ce9886c6-8c21-5c39-9fd1-040e4427f54c","text":"Перед огневой работой на ОПО не устранены горючие материалы. Какое решение верное?","displayOrder":7,"options":[{"id":"8b9e4f31-fec9-5696-8488-7616dec7875b","text":"Попросить одного работника наблюдать без средств тушения.","displayOrder":1},{"id":"a63b517c-a158-5ede-a3c1-dcd5802d0d0d","text":"Начать работу, поставив рядом ведро воды.","displayOrder":2},{"id":"4a6b1461-2c5b-50a2-ae00-4c5f96b381f3","text":"Накрыть материалы бумагой.","displayOrder":3},{"id":"6a50ff26-407b-56fe-8c01-c09dd9898e26","text":"Не начинать работу до выполнения мер наряда-допуска и подготовки пожаробезопасной зоны.","displayOrder":4}],"correctOptionId":"6a50ff26-407b-56fe-8c01-c09dd9898e26","explanation":""},{"id":"6aca454f-67e5-5312-a73e-09fb9a658dd0","text":"Что проверяют на противоаварийной тренировке?","displayOrder":8,"options":[{"id":"e17a2dc3-720d-5e92-bc5b-eaa42ce92efe","text":"Понимание сигналов, маршрутов, ролей, связи и практических действий без создания реальной опасности.","displayOrder":1},{"id":"97e15ff2-765b-5657-8532-009a54969f2c","text":"Только скорость заполнения табеля.","displayOrder":2},{"id":"7bafe744-8b4c-5d96-a7b3-e76998f11ec8","text":"Только знание номера кабинета руководителя.","displayOrder":3},{"id":"b297dd4b-e690-56da-a813-039b2486d223","text":"Только наличие повседневной одежды.","displayOrder":4}],"correctOptionId":"e17a2dc3-720d-5e92-bc5b-eaa42ce92efe","explanation":""},{"id":"f3197da2-ce96-5838-b4a9-69c41e655b1e","text":"Газоанализатор показал значение выше установленного безопасного предела. Как действовать?","displayOrder":9,"options":[{"id":"3d41feae-7908-507f-9826-deddafde180f","text":"Отключить прибор и ориентироваться на самочувствие.","displayOrder":1},{"id":"87236056-4c73-5b62-9a0c-6500b6b9ee0a","text":"Не начинать или прекратить работу, выйти из зоны и выполнить аварийные и контрольные меры по процедуре.","displayOrder":2},{"id":"dbb2d46b-c81b-52d4-81f6-02f744e30001","text":"Передать прибор другому работнику и остаться в зоне.","displayOrder":3},{"id":"f6f758f3-7d5d-514e-b95e-cc4fafd4a9a9","text":"Продолжить работу в более быстром темпе.","displayOrder":4}],"correctOptionId":"87236056-4c73-5b62-9a0c-6500b6b9ee0a","explanation":""},{"id":"2e65f150-d64e-5858-94bd-d4d1b7d5e6b6","text":"Что обозначает сокращение ПЛА?","displayOrder":10,"options":[{"id":"0abc679d-55fd-5f77-997b-83e2df519252","text":"Плановое листовое армирование.","displayOrder":1},{"id":"66dd3741-3e45-5366-b651-29d0d77eb357","text":"Перечень личных отпусков администрации.","displayOrder":2},{"id":"3e4fee19-0def-5b28-9bae-3eecd7872509","text":"План ликвидации аварий, определяющий организованные действия при аварийной ситуации.","displayOrder":3},{"id":"32d895a7-31cf-5732-ab5c-4e71fe5ad043","text":"Паспорт лабораторного анализа.","displayOrder":4}],"correctOptionId":"3e4fee19-0def-5b28-9bae-3eecd7872509","explanation":""}]}],"sourceMaterials":{"presentation":{"filename":"04_БИОТ.pptx","sha256":"aaca0cb2b612774e7d574f66d0bf2c103536333bb575dca43db4cf657b601c8f"},"tests":{"filename":"06_Тестовые_задания.docx","sha256":"3b36bba9f031c233cd10a4a80e1f7dd2a89af523b5df2145056dc7366086ce00"}},"dbContentHash":"25d6cb6a6e881ee40d255dcf4374e5c384af2d255b6aa1a5cd3de29cbdb2ceb4","snapshotContentHash":"1546e6b9d2068aa56a4f7b94fbfbcd0624e973022225e262120728ab25b2fa26","contentHash":"25d6cb6a6e881ee40d255dcf4374e5c384af2d255b6aa1a5cd3de29cbdb2ceb4"},{"schemaVersion":1,"id":"5641b254-4aa5-4a8c-a7cf-4364a1de6db0","slug":"pozharnaya-bezopasnost","title":"Пожарная безопасность","description":"Профилактика пожаров, оповещение, эвакуация, применение первичных средств тушения и безопасные действия при пожаре.","icon":"fire","displayOrder":5,"updatedAt":"2026-08-25T00:00:00.000Z","jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-21","seo":{},"sources":[],"policy":{"durationMinutes":15,"passScore":7,"questionCount":10,"variantCount":3,"attemptsPerCalendarDay":8,"resetTimezone":"Asia/Oral"},"presentation":{"id":"669596f1-7ce7-412d-97ad-a50c4c223cef","sourceFilename":"presentation.pdf","operatorPptx":"content/source-materials/derived/pozharnaya-bezopasnost/presentation.pptx","file":"presentation.pdf","thumbnail":"thumbnail.webp","storageBucket":"course-presentations","storagePath":"5641b254-4aa5-4a8c-a7cf-4364a1de6db0/669596f1-7ce7-412d-97ad-a50c4c223cef/69f2e4cbe8d284996aa891862cf6228116cfda997775a7caa1d51bd9ee648eef.pdf","thumbnailPath":"5641b254-4aa5-4a8c-a7cf-4364a1de6db0/669596f1-7ce7-412d-97ad-a50c4c223cef/69f2e4cbe8d284996aa891862cf6228116cfda997775a7caa1d51bd9ee648eef-thumb.webp","mimeType":"application/pdf","byteSize":642302,"pageCount":41,"aspectRatio":"16:9","sha256":"69f2e4cbe8d284996aa891862cf6228116cfda997775a7caa1d51bd9ee648eef","thumbnailSha256":"f66043fa245ec4fa8511acad85397eb3fe26e48948c464f47e26b5408cacbbca","notesIncluded":false},"variants":[{"id":"cca1995b-d347-56c1-90d2-02bd7a87cb8e","variantNumber":1,"questions":[{"id":"9600e24e-2e63-5d17-84f1-fedfa9c739ad","text":"Работник заметил дым и запах гари. Какое первое решение правильное?","displayOrder":1,"options":[{"id":"a23f4c20-2790-5769-bfcf-2e4e8ab9eba3","text":"Ждать появления открытого пламени.","displayOrder":1},{"id":"a67c2c6c-8bbc-587b-a68a-9d8f493f8c9c","text":"Сначала закончить текущую операцию.","displayOrder":2},{"id":"1121fc84-294b-53f4-8f30-21cb7a3379c6","text":"Открыть все двери и окна, не сообщая о пожаре.","displayOrder":3},{"id":"7030608f-d7e9-5dec-bdea-d56b753d3d77","text":"Немедленно подать сигнал тревоги, сообщить 101/112 и начать действия по эвакуации.","displayOrder":4}],"correctOptionId":"7030608f-d7e9-5dec-bdea-d56b753d3d77","explanation":""},{"id":"21bc1c81-cadc-5fd7-a4d1-15964e140615","text":"Начальный очаг пожара растёт, помещение быстро заполняется дымом. Можно ли продолжать тушение?","displayOrder":2,"options":[{"id":"e8c5350a-62a0-5962-916a-d938736cbbf5","text":"Да, если в помещении есть ещё один человек.","displayOrder":1},{"id":"e03cc981-4d67-50e6-8559-2c91f1f39152","text":"Да, если стать ближе к очагу.","displayOrder":2},{"id":"4cac5d98-78b6-5587-a2c5-bd6280d5de46","text":"Нет; нужно немедленно прекратить тушение, закрыть дверь без запирания и эвакуироваться.","displayOrder":3},{"id":"77aa9486-d9b2-57dc-bf83-2eb8cf79bfc5","text":"Да, пока огнетушитель не разрядится полностью.","displayOrder":4}],"correctOptionId":"4cac5d98-78b6-5587-a2c5-bd6280d5de46","explanation":""},{"id":"e6eecce6-4f42-574c-b157-4f70e409a21f","text":"Загорелось электрооборудование, которое остаётся под напряжением. Что учитывать при выборе огнетушителя?","displayOrder":3,"options":[{"id":"d5ccd973-f626-5573-afee-2a2d2b8d02f9","text":"Использовать средство, разрешённое маркировкой для электрооборудования, и соблюдать безопасные условия применения.","displayOrder":1},{"id":"deddf6a1-d043-5fec-999a-c807513d8bd4","text":"Накрыть оборудование мокрой тканью руками.","displayOrder":2},{"id":"68018f72-4f83-55fa-b177-56dc280855dd","text":"Использовать струю воды независимо от напряжения.","displayOrder":3},{"id":"281529fe-8f98-539b-b82f-034a197ff457","text":"Применить пену без отключения и проверки маркировки.","displayOrder":4}],"correctOptionId":"d5ccd973-f626-5573-afee-2a2d2b8d02f9","explanation":""},{"id":"e1b2b29e-e303-5521-809d-dda793bccc2a","text":"После огневых работ наблюдение за местом завершили сразу. В чём ошибка?","displayOrder":4,"options":[{"id":"13edb70c-fcf1-5730-a37b-f13d0cc2d118","text":"Наблюдение нужно только до начала работ.","displayOrder":1},{"id":"ba90bb26-e6f3-5793-9deb-ca649fd43979","text":"Место должно контролироваться после окончания в течение установленного для условий периода по наряду и процедуре.","displayOrder":2},{"id":"9310fe1f-c0d9-58d7-8b06-36826dce839d","text":"После выключения инструмента тление невозможно.","displayOrder":3},{"id":"b5b9975f-4ca9-5221-9af5-5c51689dea6e","text":"Контроль требуется только при работе на открытом воздухе.","displayOrder":4}],"correctOptionId":"ba90bb26-e6f3-5793-9deb-ca649fd43979","explanation":""},{"id":"e6e947f9-a053-5820-a7b7-1be40657769c","text":"Как прекратить горение по модели огненного треугольника?","displayOrder":5,"options":[{"id":"9001de08-3689-59b9-a1b0-d27f889ee42b","text":"Добавить горючий материал.","displayOrder":1},{"id":"0f7e38b6-ba82-540b-9504-3dfa02a35a58","text":"Повысить температуру очага.","displayOrder":2},{"id":"3c9dd856-9904-5bcf-8060-e81debf0ea31","text":"Устранить хотя бы один необходимый фактор: горючее, окислитель или источник тепла.","displayOrder":3},{"id":"80e95be0-405e-5124-846a-3ab26dd24306","text":"Увеличить приток воздуха.","displayOrder":4}],"correctOptionId":"3c9dd856-9904-5bcf-8060-e81debf0ea31","explanation":""},{"id":"e8cfd42b-8ca5-59d8-900a-f11155c35f23","text":"От чего зависит предельное расстояние до огнетушителя в помещении?","displayOrder":6,"options":[{"id":"bcb3e165-8109-5716-8018-8d9a09308c45","text":"Только от цвета огнетушителя.","displayOrder":1},{"id":"2909c63b-7b0a-5e0a-964c-68c614a94a12","text":"Всегда только от универсального значения 30 метров.","displayOrder":2},{"id":"94ac6e42-f132-5c03-84fd-b2fd685502d1","text":"Только от роста работников.","displayOrder":3},{"id":"0103be91-41c2-597f-b5b7-f4beed9fa7c9","text":"От назначения и категории помещения; правила предусматривают разные значения 20, 30, 40 или 70 метров.","displayOrder":4}],"correctOptionId":"0103be91-41c2-597f-b5b7-f4beed9fa7c9","explanation":""},{"id":"71f7fc27-7d78-5126-a030-755aa27f8bec","text":"Эвакуационный выход загромождён коробками. Какое требование нарушено?","displayOrder":7,"options":[{"id":"77ab2d84-1127-5e13-8172-1eda38d41644","text":"Пути и выходы должны постоянно оставаться свободными и доступными.","displayOrder":1},{"id":"f4f03d98-54cc-5643-8c8c-86e641a2da8b","text":"Коробки запрещены только в рабочее время.","displayOrder":2},{"id":"88631dad-95df-5c49-b765-506990950ec7","text":"Загромождение допустимо при наличии огнетушителя.","displayOrder":3},{"id":"8195ee12-3a85-57e9-961b-023698e9bca3","text":"Выход можно перекрыть, если рядом есть окно.","displayOrder":4}],"correctOptionId":"77ab2d84-1127-5e13-8172-1eda38d41644","explanation":""},{"id":"186672fa-6fe0-5ba1-b05f-7d113cb09598","text":"Какова правильная последовательность при обнаружении пожара?","displayOrder":8,"options":[{"id":"294ac2ce-10b6-5740-a157-b68e09e7355b","text":"Сначала собрать личные вещи, затем закрыть выходы.","displayOrder":1},{"id":"99f56786-7830-5b87-9332-5354114e9bc3","text":"Ждать указания от коллег и не подавать тревогу.","displayOrder":2},{"id":"33bc128e-9805-5e10-ac61-733fd0e05c2a","text":"Сообщить 101/112, предупредить людей, эвакуироваться, встретить службы; тушить только безопасный начальный очаг.","displayOrder":3},{"id":"96dc61bd-ba23-594b-a8d4-5183d33e34a8","text":"Сначала тушить до полного расхода средств, затем сообщить.","displayOrder":4}],"correctOptionId":"33bc128e-9805-5e10-ac61-733fd0e05c2a","explanation":""},{"id":"5ddf5d4e-3ef7-57a8-802e-f2dc2b827a99","text":"Как подготовить переносной огнетушитель к применению?","displayOrder":9,"options":[{"id":"4b010dab-b397-57c8-b805-88fba78b50b3","text":"Открыть корпус и смешать заряд вручную.","displayOrder":1},{"id":"5fd8f7c1-71a5-5b0e-a16b-fd1eae979d8a","text":"Сначала направить насадок на людей для проверки.","displayOrder":2},{"id":"61396b00-e2d1-53f1-9355-e22882450a76","text":"Положить огнетушитель горизонтально и ударить по корпусу.","displayOrder":3},{"id":"47d6d6ea-1adf-5c1c-b543-284263d7940e","text":"Снять пломбу и предохранитель по инструкции, направить насадок на основание пламени и привести огнетушитель в действие.","displayOrder":4}],"correctOptionId":"47d6d6ea-1adf-5c1c-b543-284263d7940e","explanation":""},{"id":"d4594fcc-e8ae-557e-835e-80e0df35af26","text":"Что относится к пожару класса A?","displayOrder":10,"options":[{"id":"d1de72e0-c0f0-50fd-8d57-afee0056dfd3","text":"Горение газов.","displayOrder":1},{"id":"51ed51b2-c235-5835-b37a-86e8610b548c","text":"Горение твёрдых веществ, обычно органического происхождения, часто с образованием тлеющих углей.","displayOrder":2},{"id":"f7f294a1-f94e-5ef5-828c-7a488d637d53","text":"Горение металлов.","displayOrder":3},{"id":"de49df16-69d7-5328-98e9-042f1e475239","text":"Горение кулинарных масел и жиров.","displayOrder":4}],"correctOptionId":"51ed51b2-c235-5835-b37a-86e8610b548c","explanation":""}]},{"id":"d218d7d0-22a9-528d-8c09-d003ce99d0c4","variantNumber":2,"questions":[{"id":"4c4a5f08-d028-55b7-ae74-4d16a93a2c9f","text":"Сработала пожарная сигнализация, но пламени не видно. Как действовать?","displayOrder":1,"options":[{"id":"9322daeb-72bb-56c8-ad44-3c94603fe1d8","text":"Спрятаться в помещении до подтверждения пожара.","displayOrder":1},{"id":"ac9d822c-6ae0-50dc-a8dd-d5480eb666c6","text":"Выполнить установленный порядок эвакуации и указания ответственного персонала, не игнорируя сигнал.","displayOrder":2},{"id":"868e9eb9-78d2-5051-8d51-37685bf6901a","text":"Пойти искать очаг в одиночку по задымлённым коридорам.","displayOrder":3},{"id":"ef3afebf-4e85-5af3-9155-48939fa50dad","text":"Отключить сигнализацию и продолжить работу.","displayOrder":4}],"correctOptionId":"ac9d822c-6ae0-50dc-a8dd-d5480eb666c6","explanation":""},{"id":"88242eff-679d-51e8-82d5-ccd88ce5518b","text":"Работник не обучен применению огнетушителя и не видит безопасного пути отхода. Что делать?","displayOrder":2,"options":[{"id":"6677c30f-be19-54aa-9e54-d1491e5ae9c1","text":"Не приступать к тушению, предупредить людей и эвакуироваться, сообщив 101/112.","displayOrder":1},{"id":"57acb836-b417-5e6c-b21e-52eb5594b0dd","text":"Ждать у очага прибытия пожарных.","displayOrder":2},{"id":"5976fffb-d3f7-5ed9-98f3-2c7b364a655d","text":"Искать подходящий огнетушитель в задымлённой зоне.","displayOrder":3},{"id":"dffaf32f-c44d-5c57-ad11-663b4f77e33b","text":"Тушить любой жидкостью, находящейся рядом.","displayOrder":4}],"correctOptionId":"6677c30f-be19-54aa-9e54-d1491e5ae9c1","explanation":""},{"id":"5968ef69-6c0c-52c3-8e4e-191b41ecad41","text":"Какое действие при пожаре электрооборудования повышает безопасность, если оно выполнимо без риска?","displayOrder":3,"options":[{"id":"d0a3e945-9856-5e7b-8cd8-bfec18b6ab61","text":"Разобрать корпус работающего оборудования.","displayOrder":1},{"id":"8b10f9d9-9daf-573b-9c8e-667d83b5e120","text":"Прикасаться к кабелю металлическим инструментом.","displayOrder":2},{"id":"331911d3-ba4b-5ab8-9c63-37fb32ae1fff","text":"Залить распределительный щит водой.","displayOrder":3},{"id":"e385cb4c-ed19-5d24-80be-838a38928fa9","text":"Отключить питание установленным способом и затем применять подходящее средство тушения.","displayOrder":4}],"correctOptionId":"e385cb4c-ed19-5d24-80be-838a38928fa9","explanation":""},{"id":"f315bceb-b812-557a-bc44-fcc8e1838589","text":"Перед сваркой рядом находятся горючие материалы. Как поступить?","displayOrder":4,"options":[{"id":"c602edd9-808b-5b14-be37-1ce5b1a051be","text":"Начать сварку на меньшем токе.","displayOrder":1},{"id":"1e3693c4-10ce-56d9-ab66-7eb4d6f96da2","text":"Удалить или защитить материалы, подготовить средства тушения и выполнить требования наряда-допуска.","displayOrder":2},{"id":"7ebd6b77-18fc-525c-95af-01386380fd5b","text":"Оставить материалы и открыть окно.","displayOrder":3},{"id":"8102e71a-ff21-5693-baa7-41e2cde77383","text":"Накрыть материалы обычной бумагой.","displayOrder":4}],"correctOptionId":"1e3693c4-10ce-56d9-ab66-7eb4d6f96da2","explanation":""},{"id":"af16c829-bf30-59fc-b24e-c6e3b520671c","text":"Какой огнетушитель выбирают для конкретного очага?","displayOrder":5,"options":[{"id":"d162d8fa-cc90-52aa-8332-3c56a10f821c","text":"По расположению ближайшего шкафа без учёта очага.","displayOrder":1},{"id":"22b887ec-fdbd-53ed-b3c3-4875b41a5ac4","text":"Только по цвету наклейки иностранного шаблона.","displayOrder":2},{"id":"cbb8e529-7bc8-5032-a208-da2943f7c7ec","text":"По классу пожара, типу заряда, маркировке огнетушителя и условиям безопасности.","displayOrder":3},{"id":"69ae70ff-da5a-58fc-8800-36f21b376121","text":"Только по массе корпуса.","displayOrder":4}],"correctOptionId":"cbb8e529-7bc8-5032-a208-da2943f7c7ec","explanation":""},{"id":"f655ca03-94ff-5986-a454-e9e35d9dcd18","text":"Как устанавливают переносной огнетушитель массой 15 кг и более?","displayOrder":6,"options":[{"id":"4a0e08cc-dfff-5ba4-a5e3-ecd2dae464bc","text":"На высоте ровно 1,5 метра до нижней части корпуса.","displayOrder":1},{"id":"d0c3e49d-42c6-5bd4-bdf9-f9fe278ba8d9","text":"Непосредственно на пути эвакуации с сужением прохода.","displayOrder":2},{"id":"bac4ec02-b1b5-574b-a13e-3b90f92e5c46","text":"За запертой дверью без обозначения.","displayOrder":3},{"id":"c3c2199b-74e9-5fff-b9c0-32a1f0f05745","text":"Так, чтобы верх огнетушителя находился не выше 1,0 метра от пола, либо в предусмотренном шкафу или на подставке.","displayOrder":4}],"correctOptionId":"c3c2199b-74e9-5fff-b9c0-32a1f0f05745","explanation":""},{"id":"00b1d525-37d3-5b55-93ab-fcb39d5d5770","text":"Горючие жидкости хранятся в открытой немаркированной таре. Что следует сделать?","displayOrder":7,"options":[{"id":"9ae2ea0a-0795-54bc-90b9-0ffa0d9668b9","text":"Поставить тару у источника тепла.","displayOrder":1},{"id":"b1f00a0b-9476-50e6-b790-712fb3190e20","text":"Прекратить такое хранение и разместить вещества в предусмотренной закрытой маркированной таре и месте.","displayOrder":2},{"id":"3045070e-6293-5117-9601-8617e9d0844e","text":"Оставить тару открытой для испарения.","displayOrder":3},{"id":"718a4ffc-2eb0-51df-bf3f-e9805874d168","text":"Перелить жидкости в пищевые бутылки.","displayOrder":4}],"correctOptionId":"b1f00a0b-9476-50e6-b790-712fb3190e20","explanation":""},{"id":"af967078-e027-5243-8822-c4039f189b62","text":"Что делать после выхода к пункту сбора?","displayOrder":8,"options":[{"id":"87511e10-bdfb-5576-afef-ce139fff6101","text":"Отметиться при перекличке, сообщить известные сведения и не возвращаться без разрешения служб.","displayOrder":1},{"id":"aab1de1a-c5bc-5e19-be9f-c91eeeca3cf1","text":"Встать у входа и мешать проезду пожарных машин.","displayOrder":2},{"id":"7c73e76f-8137-51fe-8e63-75a9fa89a61d","text":"Самостоятельно вернуться за документами.","displayOrder":3},{"id":"ee0d5768-8e72-59eb-8413-67d6bafbdc6d","text":"Покинуть пункт сбора, не сообщая никому.","displayOrder":4}],"correctOptionId":"87511e10-bdfb-5576-afef-ce139fff6101","explanation":""},{"id":"f8dd7505-75e2-55f2-a4e5-69d45aa7c9b1","text":"Какое положение безопаснее при тушении начального очага?","displayOrder":9,"options":[{"id":"f4af2199-1f95-59e1-bfef-6da444755d0e","text":"Встать между очагом и единственным выходом лицом к двери.","displayOrder":1},{"id":"b80e272c-15db-57ea-94a2-9ce8c8e3fce3","text":"Подойти вплотную к пламени независимо от тепла.","displayOrder":2},{"id":"17e3e2fb-6e69-59ef-a5b7-0ae46a75b42e","text":"Работать спиной к очагу, чтобы видеть выход.","displayOrder":3},{"id":"bc5ea7a2-dd70-51a1-a079-f01112cf626c","text":"Сохранять за спиной свободный путь отхода и не входить в дым или зону опасного теплового воздействия.","displayOrder":4}],"correctOptionId":"bc5ea7a2-dd70-51a1-a079-f01112cf626c","explanation":""},{"id":"c4ee66a5-9806-5f91-a6b0-e42205a02858","text":"Что такое конвекция при пожаре?","displayOrder":10,"options":[{"id":"4f05da42-a4c4-54b6-925b-a1d8e45748c7","text":"Распространение света без нагрева.","displayOrder":1},{"id":"bd0ecfe7-cdb2-56ad-b73d-0e3976a6765e","text":"Прекращение горения из-за отсутствия топлива.","displayOrder":2},{"id":"e945c15b-f5db-5c31-aa3e-1794e0e84baa","text":"Перенос тепла движущимися нагретыми газами и дымом.","displayOrder":3},{"id":"0cb79a6c-dbda-5d31-b7f5-2d5838c46e96","text":"Передача тепла только через непосредственный контакт твёрдых тел.","displayOrder":4}],"correctOptionId":"e945c15b-f5db-5c31-aa3e-1794e0e84baa","explanation":""}]},{"id":"5a114eca-9129-5c97-aeb1-b5a00a263280","variantNumber":3,"questions":[{"id":"19e65d17-2bce-5537-978d-cde623a170fc","text":"Работник первым обнаружил небольшое возгорание. Что он должен обеспечить прежде всего?","displayOrder":1,"options":[{"id":"d24e8376-28b9-5e51-8a54-662ef9923893","text":"Ожидание команды после распространения дыма.","displayOrder":1},{"id":"35654980-f993-5013-a9e2-d5088e080536","text":"Сохранность личных вещей.","displayOrder":2},{"id":"6bc66aa0-64fc-5203-85e6-461a49ba6834","text":"Оповещение людей и пожарной службы, безопасный путь отхода и эвакуацию по обстановке.","displayOrder":3},{"id":"c30b5cec-14f5-5d81-970d-c768d9498f5d","text":"Закрытие всех эвакуационных выходов.","displayOrder":4}],"correctOptionId":"6bc66aa0-64fc-5203-85e6-461a49ba6834","explanation":""},{"id":"37bf813c-78f7-5651-bd3d-563b6b9b90a8","text":"Небольшой очаг доступен, огнетушитель подходит, а выход остаётся за спиной. Когда допустима попытка тушения?","displayOrder":2,"options":[{"id":"60da55f9-1272-5c96-b17a-e2d47160335d","text":"До подачи сигнала тревоги, чтобы не беспокоить людей.","displayOrder":1},{"id":"408aab23-c0de-5738-a714-04a954410273","text":"После оповещения, при наличии обучения, отсутствии угрозы жизни и готовности немедленно отступить.","displayOrder":2},{"id":"f1117e09-e16d-585f-9469-577f34edd3b3","text":"Только после закрытия единственного выхода.","displayOrder":3},{"id":"0ceb12cf-da46-5f88-878d-21e03675d218","text":"При любом размере огня, пока есть огнетушитель.","displayOrder":4}],"correctOptionId":"408aab23-c0de-5738-a714-04a954410273","explanation":""},{"id":"6542fe0a-3c07-54d5-97fb-dfe40f4a7d63","text":"На огнетушителе нет понятной маркировки применимости к электрооборудованию. Как поступить?","displayOrder":3,"options":[{"id":"ce14b1fa-9622-50db-878b-ee9b7946aede","text":"Не использовать его для оборудования под напряжением и выбрать подтверждённо подходящее средство либо эвакуироваться.","displayOrder":1},{"id":"5c046f36-e7ac-505f-b395-1ad306ef7562","text":"Смешать заряд с водой.","displayOrder":2},{"id":"7091535e-54a6-5576-a40d-46632257bddc","text":"Проверить пригодность коротким выпуском в щит.","displayOrder":3},{"id":"aca0e427-7530-5343-832b-fe78a1e562a0","text":"Использовать огнетушитель, ориентируясь на цвет корпуса.","displayOrder":4}],"correctOptionId":"ce14b1fa-9622-50db-878b-ee9b7946aede","explanation":""},{"id":"7600b23d-bb08-5ffd-821f-a622f4a55cfd","text":"Пожарный пост потерял связь с исполнителем огневой работы. Что делать?","displayOrder":4,"options":[{"id":"55849e56-9bcb-5428-b80a-a2dfd1166dd7","text":"Заменить связь периодическими жестами без согласования.","displayOrder":1},{"id":"70f500f5-70b4-5791-b342-533d12b818bd","text":"Продолжить, если искры не видны.","displayOrder":2},{"id":"d0a637c5-ac7e-5311-bd32-089b95fdebce","text":"Приостановить работу до восстановления предусмотренного наблюдения и связи.","displayOrder":3},{"id":"b15c1981-5e6f-5d3a-90f0-e56e276c3c2a","text":"Покинуть пост, не сообщая исполнителю.","displayOrder":4}],"correctOptionId":"d0a637c5-ac7e-5311-bd32-089b95fdebce","explanation":""},{"id":"1f9c940e-3364-5223-8f6e-2b4cc133d194","text":"Почему закрытая без запирания дверь полезна при выходе из горящего помещения?","displayOrder":5,"options":[{"id":"cb8443d3-4403-5912-93d0-e93aa61bdd2e","text":"Она полностью прекращает горение во всех случаях.","displayOrder":1},{"id":"1f4d9056-9ced-55a0-a1cc-42106336a2de","text":"Она заменяет вызов пожарной службы.","displayOrder":2},{"id":"35b1f577-0ec0-56e5-a078-cdfdb351e9e6","text":"Она разрешает повторно войти без защиты.","displayOrder":3},{"id":"92645e91-8799-590a-9277-636fa80788bc","text":"Она может ограничить распространение дыма и огня, сохраняя возможность доступа служб.","displayOrder":4}],"correctOptionId":"92645e91-8799-590a-9277-636fa80788bc","explanation":""},{"id":"0d57c1dc-021b-50ae-95b5-a3c6adb316d1","text":"Что проверяют при внешнем осмотре огнетушителя?","displayOrder":6,"options":[{"id":"d31aee1f-d3b4-5c30-af62-79cf7108e01d","text":"Только массу соседнего оборудования.","displayOrder":1},{"id":"97861680-dd23-5bcc-bffe-d3ec45ef8530","text":"Доступность, пломбу и индикатор при наличии, отсутствие повреждений, читаемость маркировки и срок обслуживания.","displayOrder":2},{"id":"6b93e381-fa30-5334-b3e4-7ba1daae6064","text":"Только наличие свободного окна рядом.","displayOrder":3},{"id":"e24d7ed8-7669-5d1d-a2e4-c90b7478275b","text":"Только цвет корпуса.","displayOrder":4}],"correctOptionId":"97861680-dd23-5bcc-bffe-d3ec45ef8530","explanation":""},{"id":"431f5f26-c949-58df-bfc7-410c1e3eebd2","text":"Где допускается курение на территории организации?","displayOrder":7,"options":[{"id":"1378a8ac-773d-5510-b8dc-b8eab88563d2","text":"Только в специально отведённых и обозначенных местах с соблюдением установленных мер.","displayOrder":1},{"id":"7cfb40a2-dda7-53a2-b60c-6202f413a4e0","text":"У склада горючих материалов при отсутствии ветра.","displayOrder":2},{"id":"b1c00370-ad6a-581b-95ab-f1c7fefd8079","text":"В любом месте на открытом воздухе.","displayOrder":3},{"id":"f2144ab1-b419-54ee-bee1-6c3a02868d3b","text":"В помещении рядом с огнетушителем.","displayOrder":4}],"correctOptionId":"1378a8ac-773d-5510-b8dc-b8eab88563d2","explanation":""},{"id":"a0451b68-5acc-5e9e-9d5b-394812006217","text":"Как действовать при эвакуации через задымлённый участок, если путь остаётся допустимым по плану?","displayOrder":8,"options":[{"id":"537f3590-e4c8-52b1-9e80-d690cd350517","text":"Бежать в противоположную сторону без ориентирования.","displayOrder":1},{"id":"0f3fce79-cd61-5f9a-92f7-c631918fd78c","text":"Открывать все двери и оставлять их настежь.","displayOrder":2},{"id":"701a1c8f-4e8e-5b62-b1c4-9f6331bf3b6b","text":"Двигаться организованно к безопасному выходу, держаться ниже слоя дыма и не пользоваться лифтом.","displayOrder":3},{"id":"8030d0ae-9aab-5a41-850f-d71962e7d0ef","text":"Возвращаться за средствами индивидуальной защиты из другой зоны.","displayOrder":4}],"correctOptionId":"701a1c8f-4e8e-5b62-b1c4-9f6331bf3b6b","explanation":""},{"id":"42d9770c-68c4-5068-8ef1-dc7ad608b3fd","text":"Когда следует прекратить применение огнетушителя?","displayOrder":9,"options":[{"id":"8ce3046e-7a06-5a89-8dce-8a19e6687e3a","text":"Только после прибытия руководителя организации.","displayOrder":1},{"id":"5fcf8d39-aeda-5b3b-a89f-af0aed279f3b","text":"Только если огонь перешёл на пол.","displayOrder":2},{"id":"ee77159d-9a80-5c37-9a5d-8fe36c364ba7","text":"Только после полного опустошения корпуса.","displayOrder":3},{"id":"911ac334-4242-5263-971e-cd5a08713913","text":"Если огонь растёт, усиливается дым, средство неэффективно или безопасный отход оказывается под угрозой.","displayOrder":4}],"correctOptionId":"911ac334-4242-5263-971e-cd5a08713913","explanation":""},{"id":"3e8a1c3b-9133-5f5e-8120-467082b33b00","text":"Что называют источником зажигания?","displayOrder":10,"options":[{"id":"81e99df7-0692-5fa5-ac84-481e9d89bf6c","text":"Источник энергии, способный инициировать горение горючей смеси или материала.","displayOrder":1},{"id":"02d2c294-d56e-55cc-aa02-677be96d0f03","text":"Только негорючую строительную конструкцию.","displayOrder":2},{"id":"afcb4009-d5a7-52f9-bbf7-b14d6214694a","text":"Любой эвакуационный знак.","displayOrder":3},{"id":"6062791e-b3a7-5c56-8e7e-ba714d6f717d","text":"Любое средство тушения.","displayOrder":4}],"correctOptionId":"81e99df7-0692-5fa5-ac84-481e9d89bf6c","explanation":""}]}],"sourceMaterials":{"presentation":{"filename":"05_Пожарная_безопасность.pptx","sha256":"eb0c64b3aa83a3d63d74631d899def9f7683d06858baca516cc8fc254b46d68a"},"tests":{"filename":"06_Тестовые_задания.docx","sha256":"3b36bba9f031c233cd10a4a80e1f7dd2a89af523b5df2145056dc7366086ce00"}},"dbContentHash":"68e9a7f2651ec2697385d880e910c5b5bac2b3f4d91fc1c50c732ef59cd853e9","snapshotContentHash":"5e9c6a18acc409bac0857a7faf7bf74b6bfd77ed04f1ac5d1757f0a1d7f5ea0a","contentHash":"68e9a7f2651ec2697385d880e910c5b5bac2b3f4d91fc1c50c732ef59cd853e9"}]$courses$::jsonb)
  loop
    v_test_id := (v_course ->> 'id')::uuid;
    v_presentation_id := (v_course -> 'presentation' ->> 'id')::uuid;
    v_hash := private.course_content_hash_v3(
      v_course ->> 'slug', v_course ->> 'title', v_course ->> 'description',
      v_course ->> 'icon', (v_course ->> 'displayOrder')::integer,
      v_course -> 'presentation' ->> 'sha256',
      (v_course -> 'presentation' ->> 'pageCount')::integer,
      (v_course -> 'policy' ->> 'durationMinutes')::integer,
      (v_course -> 'policy' ->> 'passScore')::integer,
      (v_course -> 'policy' ->> 'attemptsPerCalendarDay')::integer,
      v_course -> 'policy' ->> 'resetTimezone', v_course -> 'variants',
      coalesce(v_course -> 'seo', '{}'::jsonb),
      nullif(v_course ->> 'jurisdiction', ''),
      nullif(v_course ->> 'effectiveDate', '')::date,
      coalesce(v_course -> 'sources', '[]'::jsonb)
    );
    if v_hash is distinct from v_course ->> 'dbContentHash' then
      raise exception 'COURSE_SNAPSHOT_HASH_MISMATCH:%', v_course ->> 'slug';
    end if;

    insert into public.tests as existing_test (
      id, slug, title, description, icon, display_order, seo, draft_content,
      duration_minutes, pass_score, attempts_per_calendar_day,
      attempt_reset_timezone, status, jurisdiction, effective_date, sources, content_hash,
      created_at, updated_at
    ) values (
      v_test_id, v_course ->> 'slug', v_course ->> 'title',
      v_course ->> 'description', v_course ->> 'icon',
      (v_course ->> 'displayOrder')::integer, coalesce(v_course -> 'seo', '{}'::jsonb),
      jsonb_build_object('questions', '[]'::jsonb, 'questionVariants', v_course -> 'variants'),
      (v_course -> 'policy' ->> 'durationMinutes')::integer,
      (v_course -> 'policy' ->> 'passScore')::integer,
      (v_course -> 'policy' ->> 'attemptsPerCalendarDay')::integer,
      v_course -> 'policy' ->> 'resetTimezone', 'draft',
      nullif(v_course ->> 'jurisdiction', ''),
      nullif(v_course ->> 'effectiveDate', '')::date,
      coalesce(v_course -> 'sources', '[]'::jsonb), v_hash,
      (v_course ->> 'updatedAt')::timestamptz,
      (v_course ->> 'updatedAt')::timestamptz
    )
    on conflict (slug) do update set updated_at = existing_test.updated_at
    returning id into v_test_id;

    if v_test_id is distinct from (v_course ->> 'id')::uuid then
      raise exception 'COURSE_SNAPSHOT_ID_CONFLICT:%', v_course ->> 'slug';
    end if;

    insert into public.course_presentations (
      id, course_id, storage_bucket, storage_path, thumbnail_path,
      source_filename, mime_type, byte_size, sha256, page_count, aspect_ratio,
      status, created_at, validated_at
    ) values (
      v_presentation_id, v_test_id,
      v_course -> 'presentation' ->> 'storageBucket',
      v_course -> 'presentation' ->> 'storagePath',
      v_course -> 'presentation' ->> 'thumbnailPath',
      v_course -> 'presentation' ->> 'sourceFilename',
      v_course -> 'presentation' ->> 'mimeType',
      (v_course -> 'presentation' ->> 'byteSize')::bigint,
      v_course -> 'presentation' ->> 'sha256',
      (v_course -> 'presentation' ->> 'pageCount')::integer,
      v_course -> 'presentation' ->> 'aspectRatio', 'ready',
      (v_course ->> 'updatedAt')::timestamptz,
      (v_course ->> 'updatedAt')::timestamptz
    ) on conflict (id) do nothing;

    insert into public.course_drafts (
      test_id, slug, title, description, icon, display_order, presentation_id,
      duration_minutes, pass_score, attempts_per_calendar_day,
      attempt_reset_timezone, content, questions, question_variants, seo,
      jurisdiction, effective_date, sources,
      content_hash, created_at, updated_at
    ) values (
      v_test_id, v_course ->> 'slug', v_course ->> 'title',
      v_course ->> 'description', v_course ->> 'icon',
      (v_course ->> 'displayOrder')::integer, v_presentation_id,
      (v_course -> 'policy' ->> 'durationMinutes')::integer,
      (v_course -> 'policy' ->> 'passScore')::integer,
      (v_course -> 'policy' ->> 'attemptsPerCalendarDay')::integer,
      v_course -> 'policy' ->> 'resetTimezone',
      '{"modules":[]}'::jsonb, '[]'::jsonb, v_course -> 'variants',
      coalesce(v_course -> 'seo', '{}'::jsonb),
      nullif(v_course ->> 'jurisdiction', ''),
      nullif(v_course ->> 'effectiveDate', '')::date,
      coalesce(v_course -> 'sources', '[]'::jsonb), v_hash,
      (v_course ->> 'updatedAt')::timestamptz,
      (v_course ->> 'updatedAt')::timestamptz
    )
    on conflict (test_id) do update
    set slug = excluded.slug,
        title = excluded.title,
        description = excluded.description,
        icon = excluded.icon,
        display_order = excluded.display_order,
        presentation_id = excluded.presentation_id,
        duration_minutes = excluded.duration_minutes,
        pass_score = excluded.pass_score,
        attempts_per_calendar_day = excluded.attempts_per_calendar_day,
        attempt_reset_timezone = excluded.attempt_reset_timezone,
        content = excluded.content,
        questions = excluded.questions,
        question_variants = excluded.question_variants,
        seo = excluded.seo,
        jurisdiction = excluded.jurisdiction,
        effective_date = excluded.effective_date,
        sources = excluded.sources,
        content_hash = excluded.content_hash,
        draft_version = course_drafts.draft_version + 1,
        updated_at = excluded.updated_at
    where (course_drafts.slug, course_drafts.title, course_drafts.description,
      course_drafts.icon, course_drafts.display_order, course_drafts.presentation_id,
      course_drafts.duration_minutes, course_drafts.pass_score,
      course_drafts.attempts_per_calendar_day, course_drafts.attempt_reset_timezone,
      course_drafts.content, course_drafts.questions, course_drafts.question_variants,
      course_drafts.seo,
      course_drafts.jurisdiction, course_drafts.effective_date,
      course_drafts.sources, course_drafts.content_hash)
      is distinct from
      (excluded.slug, excluded.title, excluded.description, excluded.icon,
      excluded.display_order, excluded.presentation_id, excluded.duration_minutes,
      excluded.pass_score, excluded.attempts_per_calendar_day,
      excluded.attempt_reset_timezone, excluded.content, excluded.questions,
      excluded.question_variants, excluded.seo, excluded.jurisdiction,
      excluded.effective_date, excluded.sources, excluded.content_hash);

    if not exists (
      select 1
      from public.tests test
      join public.test_revisions revision on revision.id = test.current_revision_id
      where test.id = v_test_id
        and revision.content_hash = v_hash
        and revision.presentation_id = v_presentation_id
        and revision.jurisdiction is not distinct from nullif(v_course ->> 'jurisdiction', '')
        and revision.effective_date is not distinct from nullif(v_course ->> 'effectiveDate', '')::date
        and revision.sources = coalesce(v_course -> 'sources', '[]'::jsonb)
    ) then
      perform private.publish_course_revision_v3_unmetered(null, v_test_id, v_hash);
    else
      update public.tests set status = 'published' where id = v_test_id;
    end if;
  end loop;
end;
$seed$;

do $seed$
declare
  v_article jsonb;
  v_article_id uuid;
  v_revision_id uuid;
  v_hash text;
  v_version integer;
begin
  for v_article in
    select value from jsonb_array_elements($articles$[{"slug":"bezopasnyy-podem-gruza","title":"Как поднять и перенести груз без рывка и геройства","description":"Практическая проверка маршрута, веса, захвата и помощи перед ручным перемещением коробки, детали или инструмента.","coverImage":"/images/generated/article-manual-lifting.webp","blocks":[{"type":"paragraph","content":"Спина часто страдает не из-за одной огромной коробки, а из-за повторяющихся неудобных движений: потянуться через борт, повернуться с грузом, поднять предмет с неизвестным содержимым. Лучшее движение — то, которого удалось избежать тележкой, подъёмником или изменением маршрута."},{"tone":"info","type":"callout","title":"Универсального безопасного веса нет","content":"Риск зависит не только от килограммов, но и от размера, формы, высоты, частоты подъёмов, расстояния, покрытия пола и состояния человека. Следуйте нормам и инструкции вашего рабочего места; если сомневаетесь — используйте помощь или средство механизации."},{"type":"heading","level":2,"content":"Проверка до подъёма"},{"type":"list","items":["Узнайте массу и содержимое. Если маркировки нет, не проверяйте вес резким рывком.","Оцените форму: есть ли надёжные ручки, острые края, смещение содержимого или плохой обзор.","Осмотрите путь и место установки: двери открыты, проход свободен, пол сухой, высота понятна.","Выберите тележку, подъёмное средство или напарника до того, как груз окажется в руках.","Договоритесь о командах, если переносите вдвоём: кто ведёт, когда поднимать, идти и опускать."],"style":"ordered"},{"type":"heading","level":2,"content":"Само движение"},{"type":"paragraph","content":"Подойдите близко к предмету, обеспечьте устойчивую опору и возьмитесь надёжно. Поднимайте плавно без рывка, держите груз ближе к корпусу и смотрите по маршруту. Чтобы изменить направление, переставляйте ноги, а не скручивайте корпус под нагрузкой. Опускайте так же контролируемо, сохраняя пальцы вне зон защемления."},{"rows":[["Груз закрывает обзор","Тележка, второй человек или другой способ перемещения"],["Нет удобного захвата","Тара с ручками, захватное приспособление или переупаковка"],["Нужно тянуться выше плеч","Изменить высоту хранения или применить подъёмное средство"],["Предстоит длинный маршрут","Использовать колёсную технику и заранее освободить путь"],["Нужно много повторений","Чередовать задачи и механизировать процесс по местной процедуре"]],"type":"table","caption":"Когда план нужно изменить","headers":["Признак","Лучшее решение"]},{"type":"heading","level":2,"content":"Перенос вдвоём"},{"type":"paragraph","content":"Два человека не автоматически делают подъём безопасным. Разница в росте, темпе и видимости может создать перекос. Один участник должен давать короткие команды. Поднимают и опускают одновременно, а если кто-то теряет захват — сразу сообщают и безопасно прекращают движение, не пытаясь молча удержать всё одному."},{"type":"heading","level":2,"content":"Сигналы тела"},{"type":"paragraph","content":"Боль, онемение, слабость, головокружение или резкая усталость — причина остановиться и сообщить о состоянии. Не «разрабатывайте» боль ещё одним подъёмом. Если симптомы появились внезапно, усиливаются или связаны с травмой, обратитесь за медицинской помощью по установленному порядку."},{"type":"quote","content":"Профессионализм — не поднять больше всех, а выбрать способ, который можно безопасно повторить всю смену."},{"url":"/topics/biot","text":"Изучить охрану труда","type":"button","style":"primary"}],"seo":{"title":"Как поднять и перенести груз без рывка и геройства","ogImage":"/images/generated/article-manual-lifting.webp","ogTitle":"Как поднять и перенести груз без рывка и геройства","indexable":true,"description":"Практическая проверка маршрута, веса, захвата и помощи перед ручным перемещением коробки, детали или инструмента.","ogDescription":"Практическая проверка маршрута, веса, захвата и помощи перед ручным перемещением коробки, детали или инструмента."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-11","sources":[{"url":"https://adilet.zan.kz/rus/docs/K1500000414","title":"Трудовой кодекс Республики Казахстан"},{"url":"https://adilet.zan.kz/rus/docs/V1500012665","title":"Правила обучения, инструктирования и проверки знаний по безопасности и охране труда"}],"createdAt":"2026-08-03T00:00:00.000Z","updatedAt":"2026-08-25T20:15:07.518Z"},{"slug":"elektrobezopasnost-na-rabochem-meste","title":"Электробезопасность для всех: восемь ситуаций без самодеятельности","description":"Что делать обычному пользователю при повреждённом кабеле, искрении, запахе гари, мокрой розетке или падении провода.","coverImage":"/images/generated/article-electrical-safety.webp","blocks":[{"type":"paragraph","content":"Для поражения током не нужен большой щит или высоковольтная линия. Повреждённый удлинитель, мокрая розетка или металлический корпус с неисправностью выглядят обыденно — именно поэтому к ним легко потянуться рукой."},{"tone":"warning","type":"callout","title":"Базовое правило","content":"Не касайтесь человека, оборудования или провода, если они могут находиться под напряжением. Остановите приближение других людей и вызовите обученный электротехнический персонал или экстренную службу."},{"type":"heading","level":2,"content":"Восемь сигналов «не трогать»"},{"type":"list","items":["видна медная жила, треснула изоляция или вилка держится на проводах;","розетка, кабель или корпус нагреваются сильнее обычного;","есть искрение, потрескивание, запах гари или следы копоти;","оборудование щиплет током или срабатывает защита;","вода попала на электрическое устройство либо находится рядом с подключением;","кабель пережат дверью, техникой, мебелью или лежит в проходе;","щит открыт, крышка снята или знак опасности повреждён;","провод упал на землю, транспорт, ограждение или дерево."],"style":"unordered"},{"type":"heading","level":2,"content":"Правильная реакция обычного пользователя"},{"rows":[["Повреждён удлинитель","Не использовать, обозначить и передать на замену"],["Появился запах гари","Прекратить работу, отойти, сообщить; отключение выполняют безопасным установленным способом"],["Розетка мокрая","Не касаться ни розетки, ни воды рядом; ограничить доступ и вызвать специалиста"],["Автомат снова отключился","Не включать многократно; сообщить для поиска причины"],["Провод упал на землю","Не приближаться и не касаться предметов рядом; предупредить людей и вызвать помощь"]],"type":"table","caption":"Не ремонтируйте то, к чему не допущены","headers":["Ситуация","Безопасное действие"]},{"type":"heading","level":2,"content":"Почему «быстро подкрутить» опасно"},{"type":"paragraph","content":"Отключённое на вид устройство может получить напряжение повторно, сохранить заряд или быть связано с другим источником. Безопасная электротехническая работа требует определённой последовательности отключения, проверки, защиты от включения и допуска. Изолента поверх неизвестного повреждения этой последовательностью не является."},{"type":"heading","level":2,"content":"Если человек попал под напряжение"},{"type":"paragraph","content":"Не хватайте его руками. Немедленно вызовите 112 и сообщите диспетчеру, что возможен электрический ток. Добивайтесь отключения источника безопасным способом через подготовленный персонал. Приближайтесь и оказывайте помощь только когда подтверждено отсутствие электрической опасности, следуя указаниям диспетчера и своей подготовке."},{"tone":"info","type":"callout","title":"Перед подключением","content":"Проверьте корпус, кабель и вилку; убедитесь, что место сухое, а провод не окажется под ногами или колёсами. Используйте оборудование только по назначению и в условиях, указанных изготовителем."},{"type":"quote","content":"Электричество не прощает пробного касания. Сомнение — достаточная причина отойти и позвать специалиста."},{"url":"/topics","text":"Выбрать программу обучения","type":"button","style":"primary"}],"seo":{"title":"Электробезопасность для всех: восемь ситуаций без самодеятельности","ogImage":"/images/generated/article-electrical-safety.webp","ogTitle":"Электробезопасность для всех: восемь ситуаций без самодеятельности","indexable":true,"description":"Что делать обычному пользователю при повреждённом кабеле, искрении, запахе гари, мокрой розетке или падении провода.","ogDescription":"Что делать обычному пользователю при повреждённом кабеле, искрении, запахе гари, мокрой розетке или падении провода."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-12","sources":[{"url":"https://adilet.zan.kz/rus/docs/V1500010907","title":"Правила техники безопасности при эксплуатации электроустановок"},{"url":"https://adilet.zan.kz/rus/docs/V1500010889","title":"Правила техники безопасности при эксплуатации электроустановок потребителей"}],"createdAt":"2026-08-04T00:00:00.000Z","updatedAt":"2026-08-04T00:00:00.000Z"},{"slug":"kak-podgotovitsya-k-testu-po-bezopasnosti","title":"Как подготовиться к тесту по безопасности без зубрёжки","description":"Метод коротких занятий, который помогает понять логику безопасных решений, спокойно пройти тест и применять знания в работе.","coverImage":"/images/generated/article-test-prep.webp","blocks":[{"type":"paragraph","content":"Тест по безопасности проверяет не память на формулировки ради самой памяти. Полезная цель подготовки — быстро распознать опасность и выбрать действие, которое сначала защищает людей, затем оборудование и процесс. Такой подход помогает и в незнакомом вопросе."},{"tone":"success","type":"callout","title":"Короткие занятия работают лучше марафона","content":"Разделите подготовку на несколько сессий по 15–25 минут. После каждой темы отвечайте на вопросы без подсказки и возвращайтесь только к ошибкам."},{"type":"heading","level":2,"content":"Сначала соберите карту тем"},{"type":"paragraph","content":"Откройте программу курса и выпишите крупные разделы: опасности рабочего места, СИЗ, пожар, первая помощь, аварийные действия, безопасная эксплуатация оборудования. Отметьте темы тремя цветами: понимаю, путаюсь, не изучал. Начинайте не с любимого раздела, а с последней группы."},{"type":"heading","level":2,"content":"Учите через сценарии"},{"rows":[["Какая здесь опасность?","Умение заметить источник вреда"],["Кто может пострадать?","Понимание зоны и последствий"],["Что сделать первым?","Приоритет действий"],["Когда нельзя продолжать?","Границу безопасной работы"]],"type":"table","caption":"Четыре вопроса к каждой теме","headers":["Вопрос","Что он проверяет"]},{"type":"paragraph","content":"Например, вместо заучивания списка про повреждённый кабель представьте сцену: кабель искрит в мокром проходе. Опасность — ток и пожар; приближаться нельзя; сначала ограничивают доступ и вызывают подготовленного специалиста. Один сценарий связывает сразу несколько правил."},{"type":"heading","level":2,"content":"Разбирайте ошибку, а не запоминайте букву"},{"type":"list","items":["Ответьте без подсказки и отметьте уверенность: уверен, сомневаюсь или угадываю.","После проверки объясните своими словами, почему верный вариант безопаснее остальных.","Найдите правило или фрагмент курса, который подтверждает решение.","Составьте похожий пример из своей работы.","Повторите этот вопрос на следующий день, перемешав его с другими темами."],"style":"ordered"},{"type":"heading","level":2,"content":"Что делать в день теста"},{"type":"list","items":["заранее проверьте устройство, интернет, заряд и спокойное место;","внимательно прочитайте отрицания и ограничения: «нельзя», «кроме», «в первую очередь»;","сначала исключите явно опасные варианты: самовольный ремонт, вход в опасную зону, сокрытие события;","не меняйте ответ только из-за тревоги — меняйте, если нашли конкретную ошибку в рассуждении;","если формат позволяет, оставьте несколько минут на вопросы, где сомневались."],"style":"unordered"},{"tone":"info","type":"callout","title":"Если результат ниже ожидаемого","content":"Это не приговор и не повод бездумно повторять весь курс. Выпишите темы ошибок, заново разберите сценарии и пройдите повторную попытку по предусмотренному порядку. Ценность теста — показать пробел до реальной работы."},{"type":"heading","level":2,"content":"План на три дня"},{"rows":[["Первый","Карта тем, изучение слабых разделов, 10 проверочных вопросов"],["Второй","Сценарии из ошибок, смешанный мини-тест, повтор без подсказки"],["Третий","Короткое повторение стоп-сигналов и спокойное прохождение теста"]],"type":"table","headers":["День","Задача"]},{"type":"quote","content":"Хорошая подготовка заканчивается не фразой «я помню ответ», а фразой «я понимаю, почему так безопаснее»."},{"url":"/topics","text":"Выбрать курс и пройти тест","type":"button","style":"primary"}],"seo":{"title":"Как подготовиться к тесту по безопасности без зубрёжки","ogImage":"/images/generated/article-test-prep.webp","ogTitle":"Как подготовиться к тесту по безопасности без зубрёжки","indexable":true,"description":"Метод коротких занятий, который помогает понять логику безопасных решений, спокойно пройти тест и применять знания в работе.","ogDescription":"Метод коротких занятий, который помогает понять логику безопасных решений, спокойно пройти тест и применять знания в работе."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-12","sources":[{"url":"https://adilet.zan.kz/rus/docs/V1500012665","title":"Правила обучения, инструктирования и проверки знаний по безопасности и охране труда"},{"url":"https://adilet.zan.kz/rus/docs/K1500000414","title":"Трудовой кодекс Республики Казахстан"}],"createdAt":"2026-08-11T00:00:00.000Z","updatedAt":"2026-08-11T00:00:00.000Z"},{"slug":"kogda-ostanovit-opasnuyu-rabotu","title":"Когда работу нужно остановить: семь ясных сигналов","description":"Как распознать непосредственную опасность, корректно прекратить действие и сообщить о проблеме без конфликта и героизма.","coverImage":"/images/generated/article-stop-work.webp","blocks":[{"type":"paragraph","content":"Остановка работы — не наказание и не проявление слабости. Это управляемая пауза, когда фактические условия перестали соответствовать безопасному способу выполнения задачи. Чем раньше замечен сигнал, тем меньше последствий."},{"type":"heading","level":2,"content":"Семь стоп-сигналов"},{"type":"list","items":["защитное ограждение, блокировка, сигнализация или аварийная остановка отсутствует либо неисправна;","появились дым, искрение, запах газа или гари, необычный нагрев, вибрация или шум;","люди вошли в опасную зону, а оператор не может надёжно контролировать их положение;","условия изменились: дождь, ветер, плохая видимость, разлив, обрушение, движение другой техники;","нужного инструмента или СИЗ нет, они повреждены либо не подходят задаче;","задание выходит за рамки инструктажа, допуска, наряда или вашей подготовки;","вы не понимаете команду, сигналы связи потеряны или действия участников противоречат друг другу."],"style":"unordered"},{"tone":"warning","type":"callout","title":"Не исправляйте опасность ценой новой опасности","content":"Не заходите под груз, не снимайте защитный кожух, не касайтесь повреждённого кабеля и не входите в загазованную зону, чтобы «быстро всё поправить», если это не предусмотрено безопасной процедурой и вашей подготовкой."},{"type":"heading","level":2,"content":"Как остановить действие"},{"type":"list","items":["Подайте понятный установленный сигнал остановки. Если единого сигнала нет, скажите громко и однозначно: «Стоп, опасность».","Прекратите своё действие безопасным способом; не делайте резкого манёвра, который создаст новый риск.","Предупредите людей рядом и не допускайте входа в опасную зону в пределах своих возможностей.","Сообщите руководителю: что увидели, где, когда и чем это угрожает.","Возобновляйте работу только после устранения причины, подтверждения безопасных условий и понятного задания."],"style":"ordered"},{"type":"heading","level":2,"content":"Формула спокойного сообщения"},{"rows":[["Факт","На площадке повреждено ограждение проёма"],["Риск","Человек может упасть с высоты"],["Моё действие","Я остановил перемещение материалов рядом"],["Запрос","Нужно оградить проём и подтвердить безопасный маршрут"]],"type":"table","caption":"Факт — риск — запрос","headers":["Часть","Пример"]},{"type":"paragraph","content":"Такая формула убирает спор о намерениях. Вы не обвиняете коллегу и не доказываете, кто прав, а показываете наблюдаемый факт и следующий безопасный шаг. Если опасность не устраняется, используйте предусмотренный в организации канал эскалации."},{"type":"heading","level":2,"content":"Что говорит право работника"},{"type":"paragraph","content":"Трудовой кодекс Казахстана закрепляет гарантии в области безопасности и охраны труда, включая отказ от выполнения работы при непосредственной опасности для жизни и здоровья. Конкретный порядок уведомления и дальнейших действий уточняйте в инструкциях вашего рабочего места. В экстренной ситуации сначала выводят людей из опасности, затем оформляют сообщения."},{"tone":"success","type":"callout","title":"Правильный итог остановки","content":"Не просто «работа снова идёт», а причина понятна, риск устранён или контролируется, участники получили одинаковые инструкции и готовы безопасно продолжить."},{"url":"/topics/biot","text":"Проверить знания по охране труда","type":"button","style":"primary"}],"seo":{"title":"Когда работу нужно остановить: семь ясных сигналов","ogImage":"/images/generated/article-stop-work.webp","ogTitle":"Когда работу нужно остановить: семь ясных сигналов","indexable":true,"description":"Как распознать непосредственную опасность, корректно прекратить действие и сообщить о проблеме без конфликта и героизма.","ogDescription":"Как распознать непосредственную опасность, корректно прекратить действие и сообщить о проблеме без конфликта и героизма."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-11","sources":[{"url":"https://adilet.zan.kz/rus/docs/K1500000414","title":"Трудовой кодекс Республики Казахстан"},{"url":"https://adilet.zan.kz/rus/docs/V1500012665","title":"Правила обучения, инструктирования и проверки знаний по безопасности и охране труда"}],"createdAt":"2026-08-06T00:00:00.000Z","updatedAt":"2026-08-25T20:15:07.694Z"},{"slug":"ohrana-truda-kazakhstan-2026","title":"Безопасный рабочий день: что проверить до начала смены","description":"Простой маршрут для работника: понять задачу, заметить опасность, проверить защиту и не начинать работу, если условия небезопасны.","coverImage":"/images/generated/article-occupational-safety.webp","blocks":[{"type":"paragraph","content":"Большинство безопасных смен начинается не с длинной инструкции, а с короткой паузы перед работой. За две минуты можно уточнить задачу, осмотреть место и понять, что изменилось со вчерашнего дня. Этот навык полезен и в цехе, и на складе, и в офисе."},{"tone":"success","type":"callout","title":"Главная мысль","content":"Если вы не понимаете задачу, не видите безопасного способа её выполнить или замечаете непосредственную опасность, не начинайте работу молча. Остановитесь, предупредите людей рядом и обратитесь к непосредственному руководителю."},{"type":"heading","level":2,"content":"Проверка за две минуты"},{"type":"list","items":["Задача: я точно понимаю, что нужно сделать и где заканчивается моя зона работы?","Место: проходы свободны, освещение достаточное, на полу нет разлива, льда, кабелей или мусора?","Оборудование: нет необычного шума, запаха, нагрева, повреждений или снятых ограждений?","Защита: нужные СИЗ на месте, подходят по размеру и не повреждены?","Связь: я знаю, кому сообщить об отклонении и как вызвать помощь?"],"style":"ordered"},{"type":"heading","level":2,"content":"Что изменилось сегодня"},{"type":"paragraph","content":"Привычное место может стать опасным после ремонта, перестановки, смены материала, погоды или работ другой бригады. Не полагайтесь только на память. Посмотрите на фактическую обстановку: новый маршрут техники, открытый люк, мокрая поверхность или временный кабель важнее вчерашней картинки в голове."},{"rows":[["Необычный запах, дым или искрение","Не включать и не трогать оборудование; отойти и сообщить"],["Снято ограждение или блокировка","Не запускать механизм и обозначить опасную зону"],["СИЗ повреждено или не подходит","Запросить исправную замену до начала работы"],["Задание отличается от инструктажа","Уточнить способ работы и необходимые меры защиты"],["Люди находятся в опасной зоне","Остановить начало операции и предупредить их"]],"type":"table","caption":"Сигналы, которые нельзя игнорировать","headers":["Сигнал","Безопасное действие"]},{"type":"heading","level":2,"content":"Как задать вопрос без лишнего напряжения"},{"type":"paragraph","content":"Хороший вопрос описывает факт, риск и нужное решение. Например: «На кабеле повреждена изоляция, прикасаться опасно. Кто может отключить линию и заменить кабель?» Такая формулировка быстрее приводит к действию, чем общее «тут что-то не так»."},{"type":"quote","content":"Сначала безопасный способ — потом скорость. Потерянные две минуты дешевле происшествия."},{"type":"heading","level":2,"content":"Когда работу нужно остановить"},{"type":"paragraph","content":"Трудовой кодекс Казахстана предусматривает гарантии работнику при непосредственной опасности для жизни и здоровья. На практике важно не уходить молча: прекратите опасное действие, по возможности предупредите окружающих и сразу сообщите руководителю установленным способом. Не пытайтесь самостоятельно устранять неисправность, если это не входит в вашу подготовку и полномочия."},{"tone":"info","type":"callout","title":"Запомните три глагола","content":"Остановиться. Предупредить. Сообщить. Эта последовательность подходит для большинства внезапных опасностей на рабочем месте."},{"type":"divider"},{"type":"paragraph","content":"Сделайте двухминутную проверку привычкой в начале смены и после любого перерыва, изменения задания или перемещения на новое место. Она не заменяет инструктаж, но помогает применить его к реальной обстановке."},{"url":"/topics","text":"Выбрать курс по безопасности","type":"button","style":"primary"}],"seo":{"title":"Безопасный рабочий день: что проверить до начала смены","ogImage":"/images/generated/article-occupational-safety.webp","ogTitle":"Безопасный рабочий день: что проверить до начала смены","indexable":true,"description":"Простой маршрут для работника: понять задачу, заметить опасность, проверить защиту и не начинать работу, если условия небезопасны.","ogDescription":"Простой маршрут для работника: понять задачу, заметить опасность, проверить защиту и не начинать работу, если условия небезопасны."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-12","sources":[{"url":"https://adilet.zan.kz/rus/docs/K1500000414","title":"Трудовой кодекс Республики Казахстан"},{"url":"https://adilet.zan.kz/rus/docs/V1500012665","title":"Правила обучения, инструктирования и проверки знаний по безопасности и охране труда"}],"createdAt":"2026-08-10T00:00:00.000Z","updatedAt":"2026-08-10T00:00:00.000Z"},{"slug":"pervaya-pomoshch-na-rabote","title":"Первая помощь на работе: как не потеряться в первые минуты","description":"Безопасный алгоритм для очевидца: оценить обстановку, вызвать помощь, поддержать пострадавшего и не навредить лишними действиями.","coverImage":"/images/generated/article-first-aid.webp","blocks":[{"type":"paragraph","content":"Первая помощь начинается не с аптечки, а с оценки опасности. Если броситься к пострадавшему под напряжение, в дым или под движущийся механизм, пострадавших станет больше. Спокойная последовательность действий важнее попытки вспомнить всё сразу."},{"tone":"warning","type":"callout","title":"При угрозе жизни звоните сразу","content":"Вызовите скорую помощь по номеру 103 или единую экстренную службу 112. Выполняйте указания диспетчера. Эта статья помогает вспомнить порядок действий, но не заменяет очное обучение и практическую отработку первой помощи."},{"type":"heading","level":2,"content":"Алгоритм очевидца"},{"type":"list","items":["Остановитесь и оцените место: электричество, огонь, газ, движение техники, падающие предметы и другие угрозы.","Позовите конкретного человека: «Вы в синей куртке, вызовите 112 и принесите аптечку». Так просьба не растворится в толпе.","Сообщите диспетчеру точный адрес, проходную или цех, количество пострадавших, видимую опасность и свой номер телефона.","Если подход безопасен, проверьте реакцию человека и следуйте инструкциям диспетчера в пределах своей подготовки.","Оставайтесь рядом, наблюдайте за состоянием и передайте прибывшим специалистам только известные факты."],"style":"ordered"},{"type":"heading","level":2,"content":"Что сказать экстренной службе"},{"rows":[["Где","Склад на улице Абая, въезд через вторую проходную, сектор B"],["Что произошло","Работник упал с лестницы, находится в сознании"],["Сколько пострадавших","Один человек"],["Есть ли опасность","Движение погрузчиков остановлено, место ограждено"],["Кто встретит","Коллега ждёт бригаду у проходной"]],"type":"table","caption":"Короткое сообщение экономит время","headers":["Нужно сообщить","Пример"]},{"type":"heading","level":2,"content":"Помогать — не значит делать всё"},{"type":"paragraph","content":"Не давайте лекарства, еду или питьё без указания медицинского специалиста. Не перемещайте человека после падения или удара, если на месте нет непосредственной угрозы. Не пытайтесь «вправить» повреждение. При кровотечении, ожоге, нарушении сознания или дыхания действуйте по подсказкам диспетчера и тем приёмам, которым вы обучены."},{"tone":"info","type":"callout","title":"Если рядом автоматический дефибриллятор","content":"Попросите принести устройство и включите его. Голосовые подсказки ведут пользователя по шагам. Не касайтесь пострадавшего во время анализа ритма и разряда и продолжайте выполнять указания устройства и диспетчера."},{"type":"heading","level":2,"content":"После передачи медикам"},{"type":"paragraph","content":"Сообщите руководителю о происшествии установленным способом и запишите факты, пока они свежи: время, место, что вы увидели и какие действия выполнили. Не публикуйте фото пострадавшего и медицинские подробности в общих чатах. После тяжёлого события нормально чувствовать растерянность — обратитесь за поддержкой, если она нужна."},{"type":"quote","content":"Безопасность места, ранний вызов помощи и точные сведения — уже существенная помощь пострадавшему."},{"url":"/topics","text":"Выбрать курс по безопасности","type":"button","style":"primary"}],"seo":{"title":"Первая помощь на работе: как не потеряться в первые минуты","ogImage":"/images/generated/article-first-aid.webp","ogTitle":"Первая помощь на работе: как не потеряться в первые минуты","indexable":true,"description":"Безопасный алгоритм для очевидца: оценить обстановку, вызвать помощь, поддержать пострадавшего и не навредить лишними действиями.","ogDescription":"Безопасный алгоритм для очевидца: оценить обстановку, вызвать помощь, поддержать пострадавшего и не навредить лишними действиями."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-12","sources":[{"url":"https://adilet.zan.kz/rus/docs/V2000021814","title":"Правила и стандарт оказания первой помощи лицами без медицинского образования"},{"url":"https://adilet.zan.kz/rus/docs/K2000000360","title":"Кодекс Республики Казахстан «О здоровье народа и системе здравоохранения»"}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z"},{"slug":"pervyy-den-na-novom-rabochem-meste","title":"Первый день на новом рабочем месте: 12 вопросов до старта","description":"Что узнать новичку о рисках, маршрутах, оборудовании, СИЗ и связи, прежде чем выполнять первую самостоятельную задачу.","coverImage":"/images/generated/article-new-worker.webp","blocks":[{"type":"paragraph","content":"В первый день хочется показать самостоятельность и не задавать «глупых» вопросов. Но незнакомые маршруты, сигналы и неписаные привычки делают новичка особенно уязвимым. Хороший старт — это не скорость, а ясность."},{"tone":"success","type":"callout","title":"Вопрос — часть безопасной работы","content":"Если объяснение непонятно, попросите показать действие ещё раз и повторите порядок своими словами. Подтверждённое понимание полезнее вежливого кивка."},{"type":"heading","level":2,"content":"Четыре вопроса о месте"},{"type":"list","items":["Где разрешено ходить и какие зоны доступны только по допуску?","Где ближайшие обычный и аварийный выходы, точка сбора и безопасное укрытие, если оно предусмотрено?","Как движется транспорт и где пешеход имеет ограниченную видимость?","Где находятся аптечка, ручной пожарный извещатель, телефон или другое средство связи?"],"style":"ordered"},{"type":"heading","level":2,"content":"Четыре вопроса о задаче"},{"type":"list","items":["Как выглядит нормальное начало, выполнение и безопасное завершение работы?","Какие опасности здесь наиболее вероятны и как они контролируются?","Какие СИЗ, инструмент, ограждения или разрешения нужны именно для этой операции?","В каких случаях я обязан остановиться и кого уведомить?"],"style":"ordered"},{"type":"heading","level":2,"content":"Четыре вопроса о помощи"},{"type":"list","items":["Кто мой непосредственный руководитель и кто его заменяет?","К кому обратиться при неисправности оборудования или нехватке СИЗ?","Каким способом сообщают об опасности, травме или почти-происшествии?","Как вызвать экстренную помощь и кто встретит службу у входа?"],"style":"ordered"},{"type":"heading","level":2,"content":"Проверьте понимание действием"},{"rows":[["Эвакуация","Могу без подсказки показать два пути и точку сбора"],["Остановка","Знаю безопасный способ остановить свою операцию"],["СИЗ","Умею осмотреть, надеть и отрегулировать нужную защиту"],["Связь","Сохранил нужный номер или знаю доступный канал"],["Границы","Понимаю, какие действия мне пока нельзя выполнять самостоятельно"]],"type":"table","caption":"Не просто услышать, а уметь показать","headers":["Тема","Самопроверка"]},{"type":"heading","level":2,"content":"Не копируйте опасную привычку"},{"type":"paragraph","content":"Фраза «мы всегда так делаем» не доказывает безопасность. Сопоставляйте показанный приём с инструктажем, знаками и защитными устройствами. Если опытный коллега предлагает обойти блокировку, снять СИЗ или сократить процедуру, остановитесь и уточните порядок у руководителя."},{"tone":"info","type":"callout","title":"В конце первой смены","content":"Запишите три вещи: что осталось непонятным, где вы заметили риск и какой навык нужно повторить с наставником. Это короткий план на безопасный второй день."},{"type":"paragraph","content":"Обучение и инструктаж дают основу, но новая задача, новое оборудование или изменившиеся условия требуют нового уточнения. Не переносите автоматически вчерашний способ на сегодняшнюю работу."},{"url":"/topics","text":"Начать обучение в SafetyHub","type":"button","style":"primary"}],"seo":{"title":"Первый день на новом рабочем месте: 12 вопросов до старта","ogImage":"/images/generated/article-new-worker.webp","ogTitle":"Первый день на новом рабочем месте: 12 вопросов до старта","indexable":true,"description":"Что узнать новичку о рисках, маршрутах, оборудовании, СИЗ и связи, прежде чем выполнять первую самостоятельную задачу.","ogDescription":"Что узнать новичку о рисках, маршрутах, оборудовании, СИЗ и связи, прежде чем выполнять первую самостоятельную задачу."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-12","sources":[{"url":"https://adilet.zan.kz/rus/docs/K1500000414","title":"Трудовой кодекс Республики Казахстан"},{"url":"https://adilet.zan.kz/rus/docs/V1500012665","title":"Правила обучения, инструктирования и проверки знаний по безопасности и охране труда"}],"createdAt":"2026-08-02T00:00:00.000Z","updatedAt":"2026-08-02T00:00:00.000Z"},{"slug":"pozharno-tehnicheskij-minimum","title":"Пожарная тревога на работе: что делать без паники","description":"Понятная последовательность действий при дыме, запахе гари или сигнале тревоги — от сообщения до безопасного выхода.","coverImage":"/images/generated/article-fire-safety.webp","blocks":[{"type":"paragraph","content":"При пожаре мозг пытается сначала проверить, «точно ли всё серьёзно». Это опасная задержка. Дым, запах гари, вспышка или сигнал системы оповещения — достаточная причина сразу действовать по плану объекта."},{"tone":"warning","type":"callout","title":"Приоритет — выйти и помочь выйти другим","content":"Сообщите о пожаре по номеру 101 или 112 и запускайте предусмотренное оповещение. Не рискуйте жизнью ради вещей, документов или самостоятельного тушения."},{"type":"heading","level":2,"content":"Четыре шага при тревоге"},{"type":"list","items":["Подайте сигнал установленным способом и позвоните 101 или 112. Назовите адрес, место возгорания и свою фамилию; не завершайте звонок раньше оператора.","Прекратите работу. Если это предусмотрено инструкцией и не создаёт риска, безопасно остановите оборудование.","Идите к ближайшему доступному эвакуационному выходу по знакам. Не пользуйтесь лифтом и не возвращайтесь за вещами.","Прибудьте в точку сбора, отметьтесь у ответственного и оставайтесь там до дальнейших указаний."],"style":"ordered"},{"type":"heading","level":2,"content":"Если на маршруте дым"},{"type":"paragraph","content":"Не входите в густой дым и не открывайте дверь, за которой заметны сильный нагрев или дым. Используйте другой обозначенный путь. Двигайтесь спокойно, не толкайте людей, помогите тому, кто растерялся или плохо ориентируется, но не создавайте дополнительную опасность для себя."},{"rows":[["Сработала тревога, но дыма не видно","Всё равно начать эвакуацию по плану"],["Обычный выход перекрыт","Следовать к другому обозначенному выходу"],["Коллега хочет вернуться за телефоном","Остановить его и продолжить движение к выходу"],["Человек не может выйти самостоятельно","Сообщить ответственному и экстренной службе точное место"],["Вы уже вышли","Не заходить обратно без разрешения экстренных служб"]],"type":"table","caption":"Решения в первые минуты","headers":["Ситуация","Что делать"]},{"type":"heading","level":2,"content":"Когда допустим огнетушитель"},{"type":"paragraph","content":"Первичное средство тушения используют только обученные люди, если очаг небольшой, средство подходит для этого вида возгорания, помещение не заполнено дымом, а путь к выходу остаётся за спиной. Если огонь растёт, появляется дым или средство не сработало сразу — уходите."},{"tone":"info","type":"callout","title":"Что узнать заранее","content":"Найдите два ближайших выхода, ручной извещатель, точку сбора и местный порядок оповещения. Делать это во время тревоги поздно."},{"type":"heading","level":2,"content":"После выхода"},{"type":"paragraph","content":"В точке сбора не расходятся по домам и не уезжают с территории без отметки: иначе спасатели могут искать человека внутри здания. Сообщите, если вы видели очаг, закрытый проход или человека, оставшегося в помещении. Не распространяйте догадки — передавайте только то, что наблюдали сами."},{"type":"quote","content":"Хорошая эвакуация выглядит скучно: ранний сигнал, знакомый маршрут, спокойное движение и точный учёт людей."},{"url":"/topics/pozharnaya-bezopasnost","text":"Изучить пожарную безопасность","type":"button","style":"primary"}],"seo":{"title":"Пожарная тревога на работе: что делать без паники","ogImage":"/images/generated/article-fire-safety.webp","ogTitle":"Пожарная тревога на работе: что делать без паники","indexable":true,"description":"Понятная последовательность действий при дыме, запахе гари или сигнале тревоги — от сообщения до безопасного выхода.","ogDescription":"Понятная последовательность действий при дыме, запахе гари или сигнале тревоги — от сообщения до безопасного выхода."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-11","sources":[{"url":"https://adilet.zan.kz/rus/docs/Z1400000188","title":"Закон Республики Казахстан «О гражданской защите»"},{"url":"https://adilet.zan.kz/rus/docs/V2200026867","title":"Правила пожарной безопасности"}],"createdAt":"2026-08-09T00:00:00.000Z","updatedAt":"2026-08-25T20:15:07.807Z"},{"slug":"siz-normy-vydachi-rk","title":"СИЗ без формальности: как проверить защиту перед работой","description":"Каска, очки, перчатки и респиратор защищают только тогда, когда подходят задаче, исправны и правильно надеты.","coverImage":"/images/generated/article-ppe.webp","blocks":[{"type":"paragraph","content":"Средство индивидуальной защиты — последний барьер между опасностью и человеком. Оно не исправляет неисправный станок и не заменяет ограждение, но может снизить последствия, если выбрано под конкретный риск и правильно используется."},{"type":"heading","level":2,"content":"Пять вопросов перед тем, как надеть СИЗ"},{"type":"list","items":["От какой опасности оно защищает именно в этой задаче?","Подходит ли модель и класс защиты для материала, инструмента и условий?","Подходит ли размер и можно ли отрегулировать посадку?","Нет ли трещин, разрывов, загрязнения, просрочки или отсутствующих деталей?","Знаю ли я ограничения и признаки, когда защиту нужно заменить?"],"style":"ordered"},{"tone":"warning","type":"callout","title":"«Есть на мне» не значит «защищает»","content":"Неподходящий фильтр, расстёгнутая каска, поцарапанный щиток или слишком большие перчатки создают ложное чувство безопасности. Если вы сомневаетесь в выборе или посадке, уточните до начала работы."},{"type":"heading","level":2,"content":"Быстрый осмотр"},{"rows":[["Каска","Корпус без трещин и сильных вмятин; внутренняя оснастка целая; посадка отрегулирована"],["Защитные очки","Линзы дают чистый обзор; нет трещин; дужки или ремень держат очки"],["Перчатки","Материал подходит риску; нет проколов и разрывов; размер не мешает захвату"],["Респиратор","Тип фильтра соответствует опасности; прилегание проверено; клапаны и ремни исправны"],["Защитная обувь","Подошва целая и чистая; носок не деформирован; шнуровка или застёжки исправны"]],"type":"table","caption":"На что посмотреть до смены","headers":["СИЗ","Проверка"]},{"type":"heading","level":2,"content":"Посадка важнее привычки"},{"type":"paragraph","content":"Если очки запотевают, каска сползает, а перчатка цепляется за детали, человек начинает поправлять или снимать защиту. Это сигнал не «терпеть», а подобрать размер, регулировку или совместимую модель. Несколько СИЗ должны работать вместе: дужки очков не должны нарушать прилегание респиратора, а капюшон — мешать креплению каски."},{"type":"heading","level":2,"content":"Когда нужна немедленная замена"},{"type":"list","items":["после удара, падения или контакта с веществом, если это могло повредить защиту;","при трещине, разрыве, деформации, потере прозрачности или нарушении крепления;","если фильтр исчерпал ресурс либо появились запах, сопротивление дыханию или иные признаки по инструкции изготовителя;","если СИЗ невозможно нормально очистить или оно было неправильно хранилось;","если изменились работа или опасность, а текущая защита для них не предназначена."],"style":"unordered"},{"type":"paragraph","content":"Календарный срок — не разрешение пользоваться повреждённой вещью. Сообщите о дефекте и получите исправную замену установленным на рабочем месте способом. Не ремонтируйте защитное средство скотчем, клеем или случайной деталью, если такой ремонт не предусмотрен изготовителем."},{"tone":"success","type":"callout","title":"Полезная привычка","content":"Осматривайте СИЗ дважды: перед использованием и после него. Второй осмотр помогает заметить повреждение заранее, а не в начале следующей срочной задачи."},{"url":"/topics/biot","text":"Пройти курс по охране труда","type":"button","style":"primary"}],"seo":{"title":"СИЗ без формальности: как проверить защиту перед работой","ogImage":"/images/generated/article-ppe.webp","ogTitle":"СИЗ без формальности: как проверить защиту перед работой","indexable":true,"description":"Каска, очки, перчатки и респиратор защищают только тогда, когда подходят задаче, исправны и правильно надеты.","ogDescription":"Каска, очки, перчатки и респиратор защищают только тогда, когда подходят задаче, исправны и правильно надеты."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-11","sources":[{"url":"https://adilet.zan.kz/rus/docs/K1500000414","title":"Трудовой кодекс Республики Казахстан"},{"url":"https://adilet.zan.kz/rus/docs/V1500012675","title":"Нормы выдачи специальной одежды и других средств индивидуальной защиты"}],"createdAt":"2026-08-08T00:00:00.000Z","updatedAt":"2026-08-25T20:15:07.908Z"},{"slug":"soobshit-ob-opasnosti-i-incidentah","title":"Чуть не случилось: зачем сообщать об опасных ситуациях","description":"Что записать после почти-происшествия, как отделить факты от догадок и превратить сигнал в реальное улучшение.","coverImage":"/images/generated/article-near-miss.webp","blocks":[{"type":"paragraph","content":"Груз качнулся рядом с человеком, коробка упала в пустой проход, инструмент сорвался, но никого не задел. Легко выдохнуть и забыть. Однако такая ситуация бесплатно показывает слабое место до того, как появится травма."},{"tone":"info","type":"callout","title":"Опасная ситуация — это данные, а не донос","content":"Цель сообщения — убрать условие, которое может повториться. Хорошая запись описывает событие и обстановку, а не ищет виноватого."},{"type":"heading","level":2,"content":"Сначала обезопасьте место"},{"type":"paragraph","content":"Если риск сохраняется, остановите действие, предупредите людей и сообщите ответственному. Не оставляйте упавший предмет, разлив или повреждение «до удобного момента». При травме или ухудшении самочувствия сначала вызывают помощь и действуют по аварийному порядку, а запись делают позже."},{"type":"heading","level":2,"content":"Пять фактов для полезного сообщения"},{"type":"list","items":["Когда и где это произошло — время, участок, ориентир.","Что выполнялось непосредственно перед событием.","Что вы увидели или услышали: движение, звук, положение предметов.","Кто или что могло пострадать и насколько близко находилось.","Какие временные меры уже приняты: остановка, ограждение, отключение специалистом."],"style":"ordered"},{"rows":[["Водитель опять невнимательный","Погрузчик вошёл в поворот, когда пешеход был в отмеченном переходе"],["Стеллаж плохой","На второй стойке видна деформация, нижняя балка смещена"],["Все нарушают","В 15:20 трое людей прошли через закрытую сигнальную ленту"],["Повезло, всё нормально","Коробка массой около 10 кг упала в метре от рабочего места"]],"type":"table","caption":"Факт и догадка звучат по-разному","headers":["Неудачная формулировка","Полезная формулировка"]},{"type":"heading","level":2,"content":"Фото полезно не всегда"},{"type":"paragraph","content":"Фотографируйте только если это разрешено, безопасно и не мешает помощи. Не заходите ради кадра в опасную зону. Не снимайте пострадавшего и документы с персональными данными. Иногда точная схема, время и описание расположения предметов полезнее красивой фотографии."},{"type":"heading","level":2,"content":"Как понять, что сообщение сработало"},{"type":"list","items":["опасность временно изолирована или устранена;","сообщению присвоен понятный статус или его получил конкретный человек;","определена причина, а не только убраны последствия;","изменение доведено до тех, кто сталкивается с таким же риском;","после исправления проверено, что проблема не повторяется."],"style":"unordered"},{"type":"quote","content":"«Никто не пострадал» — хороший исход, но плохая причина ничего не менять."},{"type":"paragraph","content":"Если событие всё же привело к травме, не пытайтесь самостоятельно решать, считается ли оно связанным с трудовой деятельностью. Своевременно сообщите о нём установленным способом и сохраните фактическую информацию для официального рассмотрения."},{"url":"/topics","text":"Освежить знания по безопасности","type":"button","style":"primary"}],"seo":{"title":"Чуть не случилось: зачем сообщать об опасных ситуациях","ogImage":"/images/generated/article-near-miss.webp","ogTitle":"Чуть не случилось: зачем сообщать об опасных ситуациях","indexable":true,"description":"Что записать после почти-происшествия, как отделить факты от догадок и превратить сигнал в реальное улучшение.","ogDescription":"Что записать после почти-происшествия, как отделить факты от догадок и превратить сигнал в реальное улучшение."},"jurisdiction":"Республика Казахстан","effectiveDate":"2026-08-12","sources":[{"url":"https://adilet.zan.kz/rus/docs/K1500000414","title":"Трудовой кодекс Республики Казахстан"},{"url":"https://adilet.zan.kz/rus/docs/V1500012655","title":"Формы материалов расследования несчастных случаев, связанных с трудовой деятельностью"}],"createdAt":"2026-08-05T00:00:00.000Z","updatedAt":"2026-08-05T00:00:00.000Z"}]$articles$::jsonb)
  loop
    v_hash := private.article_content_hash_v2(
      v_article ->> 'slug', v_article ->> 'title',
      v_article ->> 'description', v_article ->> 'coverImage',
      v_article -> 'blocks', v_article -> 'seo',
      nullif(v_article ->> 'jurisdiction', ''),
      nullif(v_article ->> 'effectiveDate', '')::date,
      v_article -> 'sources'
    );

    insert into public.articles as existing_article (
      slug, title, description, cover_image, blocks, seo, status,
      is_published, jurisdiction, effective_date, sources, content_hash,
      created_at, updated_at
    ) values (
      v_article ->> 'slug', v_article ->> 'title',
      v_article ->> 'description', v_article ->> 'coverImage',
      '[]'::jsonb, v_article -> 'seo', 'draft', false,
      nullif(v_article ->> 'jurisdiction', ''),
      nullif(v_article ->> 'effectiveDate', '')::date,
      v_article -> 'sources', v_hash,
      (v_article ->> 'createdAt')::timestamptz,
      (v_article ->> 'updatedAt')::timestamptz
    )
    on conflict (slug) do update set updated_at = existing_article.updated_at
    returning id into v_article_id;

    insert into public.article_drafts (
      article_id, slug, title, description, cover_image, blocks, seo,
      jurisdiction, effective_date, sources, content_hash, created_at, updated_at
    ) values (
      v_article_id, v_article ->> 'slug', v_article ->> 'title',
      v_article ->> 'description', v_article ->> 'coverImage',
      v_article -> 'blocks', v_article -> 'seo',
      nullif(v_article ->> 'jurisdiction', ''),
      nullif(v_article ->> 'effectiveDate', '')::date,
      v_article -> 'sources', v_hash,
      (v_article ->> 'createdAt')::timestamptz,
      (v_article ->> 'updatedAt')::timestamptz
    )
    on conflict (article_id) do update
    set slug = excluded.slug,
        title = excluded.title,
        description = excluded.description,
        cover_image = excluded.cover_image,
        blocks = excluded.blocks,
        seo = excluded.seo,
        jurisdiction = excluded.jurisdiction,
        effective_date = excluded.effective_date,
        sources = excluded.sources,
        content_hash = excluded.content_hash,
        draft_version = article_drafts.draft_version + 1,
        updated_at = excluded.updated_at
    where (article_drafts.slug, article_drafts.title, article_drafts.description,
      article_drafts.cover_image, article_drafts.blocks, article_drafts.seo,
      article_drafts.jurisdiction, article_drafts.effective_date,
      article_drafts.sources, article_drafts.content_hash)
      is distinct from
      (excluded.slug, excluded.title, excluded.description, excluded.cover_image,
      excluded.blocks, excluded.seo, excluded.jurisdiction,
      excluded.effective_date, excluded.sources, excluded.content_hash);

    perform private.sync_content_asset_usages(
      'article_draft', v_article_id, 0,
      jsonb_build_object(
        'coverImage', v_article ->> 'coverImage',
        'blocks', v_article -> 'blocks',
        'seo', v_article -> 'seo'
      )
    );

    if not exists (
      select 1
      from public.articles article
      join public.article_revisions revision on revision.id = article.current_revision_id
      where article.id = v_article_id
        and revision.content_hash = v_hash
        and revision.jurisdiction is not distinct from nullif(v_article ->> 'jurisdiction', '')
        and revision.effective_date is not distinct from nullif(v_article ->> 'effectiveDate', '')::date
        and revision.sources = v_article -> 'sources'
    ) then
      select content_version + 1 into v_version
      from public.articles where id = v_article_id for update;
      insert into public.article_revisions (
        article_id, version, slug, title, description, cover_image, blocks, seo,
        jurisdiction, effective_date, sources, content_hash, published_at
      ) values (
        v_article_id, v_version, v_article ->> 'slug', v_article ->> 'title',
        v_article ->> 'description', v_article ->> 'coverImage',
        v_article -> 'blocks', v_article -> 'seo',
        nullif(v_article ->> 'jurisdiction', ''),
        nullif(v_article ->> 'effectiveDate', '')::date,
        v_article -> 'sources', v_hash,
        (v_article ->> 'updatedAt')::timestamptz
      ) returning id into v_revision_id;
      perform private.sync_content_asset_usages(
        'article_revision', v_article_id, v_version,
        jsonb_build_object(
          'coverImage', v_article ->> 'coverImage',
          'blocks', v_article -> 'blocks',
          'seo', v_article -> 'seo'
        )
      );
      update public.articles
      set title = v_article ->> 'title',
          description = v_article ->> 'description',
          cover_image = v_article ->> 'coverImage',
          blocks = v_article -> 'blocks',
          seo = v_article -> 'seo',
          status = 'published',
          is_published = true,
          published_at = coalesce(published_at, (v_article ->> 'createdAt')::timestamptz),
          current_revision_id = v_revision_id,
          content_version = v_version,
          jurisdiction = nullif(v_article ->> 'jurisdiction', ''),
          effective_date = nullif(v_article ->> 'effectiveDate', '')::date,
          sources = v_article -> 'sources',
          content_hash = v_hash,
          updated_at = (v_article ->> 'updatedAt')::timestamptz
      where id = v_article_id;
    else
      update public.articles
      set status = 'published', is_published = true
      where id = v_article_id;
    end if;
  end loop;
end;
$seed$;

